INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('h-piramides', 'historia', 'Construcción de la Gran Pirámide de Giza', -2560, 'Erigida durante el reinado del faraón Keops en el Antiguo Egipto, fue la estructura más alta hecha por el hombre durante más de 3.800 años.', 'Se estima que se utilizaron 2,3 millones de bloques de piedra caliza, cada uno con un peso promedio de 2,5 toneladas.', 'Siglo XXVI a.C.', 'Pyramid', 'medio'),
  ('h-stonehenge', 'historia', 'Construcción del monumento megalítico de Stonehenge', -2500, 'Monumento megalítico circular alineado con el solsticio de verano y de invierno en las llanuras de Salisbury, Inglaterra.', 'Algunas de las ''piedras azules'' pesan hasta cuatro toneladas y fueron transportadas más de 220 km desde las colinas de Preseli en Gales.', 'Siglo XXV a.C.', 'Landmark', 'medio'),
  ('h-codigo-hammurabi', 'historia', 'Promulgación del Código de Hammurabi', -1750, 'Uno de los conjuntos de leyes escritas más antiguos de Babilonia, famoso por consagrar el principio de proporcionalidad ''ojo por ojo''.', 'Estaba tallado en una estela de diorita de más de dos metros para que ningún gobernante pudiera modificar la ley a su antojo.', 'Siglo XVIII a.C.', 'Scroll', 'medio'),
  ('h-tutankamon', 'historia', 'Sepulcro y tesoros del Faraón Tutankamón', -1323, 'El joven faraón de la dinastía XVIII fue sepultado con ricos ajuares en el Valle de los Reyes en Tebas.', 'Su tumba (KV62) permaneció casi intacta durante más de 3.200 años hasta que Howard Carter la abrió en 1922.', 'Siglo XIV a.C.', 'Crown', 'medio'),
  ('h-juegos-olimpicos', 'historia', 'Primeros Juegos Olímpicos en Olimpia', -776, 'Celebrados en honor a Zeus en la antigua Grecia, marcando el inicio del cómputo cronológico griego por olimpiadas.', 'Durante los Juegos se declaraba la ''Paz Olímpica'' (ékécheiria): todas las guerras entre polis griegas debían suspenderse obligatoriamente.', 'Siglo VIII a.C.', 'Flame', 'medio'),
  ('h-fundacion-roma', 'historia', 'Fundación mítica de Roma por Rómulo', -753, 'Según la tradición romana, la ciudad eterna fue fundada sobre la colina del Palatino tras el mítico amamantamiento por la loba Luperca.', 'Rómulo trazó el perímetro sagrado de la ciudad (pomerium) con un arado tirado por un buey blanco y una vaca.', 'Siglo VIII a.C.', 'Shield', 'medio'),
  ('h-maraton', 'historia', 'Batalla de Maratón y la hazaña de Filípides', -490, 'Atenas derrotó a la primera invasión persa del rey Darío I. El emisario Filípides corrió sin parar hasta Atenas para anunciar la victoria.', 'Al llegar a Atenas, Filípides gritó ''¡Nenikékamen!'' (Hemos vencido) y cayó muerto por el agotamiento, inspirando la carrera olímpica moderna de 42 km.', 'Siglo V a.C.', 'Footprints', 'medio'),
  ('h-termopilas', 'historia', 'Batalla de las Termópilas: Leónidas y los 300', -480, '300 espartanos y sus aliados contuvieron durante tres días al gigantesco ejército persa de Jerjes I en el estrecho paso de las Termópilas.', 'Cuando Jerjes exigió que entregaran sus armas, Leónidas respondió con la célebre frase: ''Molon labe'' (Ven a buscarlas tú mismo).', 'Siglo V a.C.', 'ShieldAlert', 'medio'),
  ('h-guerras-medicas-salamina', 'historia', 'Batalla naval de Salamina', -480, 'La flota aliada de las polis griegas derrotó decisivamente a la colosal armada del Imperio Persa en los estrechos de Salamina.', 'Temístocles engañó a Jerjes enviándole un mensajero secreto que fingió una traición para hacer entrar a las naves persas en aguas angostas.', 'Siglo V a.C.', 'Ship', 'medio'),
  ('h-muerte-socrates', 'historia', 'Juicio y muerte del filósofo Sócrates', -399, 'El maestro de la mayéutica y padre de la ética ateniense fue condenado a beber cicuta acusado de corromper a la juventud.', 'Rechazó un plan de fuga organizado por sus discípulos porque consideraba que violar las leyes de la polis destruiría la justicia.', 'Siglo IV a.C.', 'BookOpen', 'medio'),
  ('h-alejandro-magno', 'historia', 'Alejandro Magno conquista el Imperio Persa', -330, 'El joven rey macedonio derrotó a Darío III y expandió su imperio desde Grecia hasta Egipto y las fronteras de la India.', 'Nunca perdió una sola batalla en 15 años de campañas militares consecutivas.', 'Siglo IV a.C.', 'Crown', 'medio'),
  ('h-biblioteca-alejandria', 'historia', 'Fundación de la Gran Biblioteca de Alejandría', -283, 'El mayor centro de investigación, traducción y acopio de manuscritos del mundo helenístico en Egipto.', 'Todo barco que atracaba en el puerto de Alejandría debía entregar sus rollos para ser copiados antes de ser devueltos.', 'Siglo III a.C.', 'Library', 'medio'),
  ('h-anibal-alpes', 'historia', 'Aníbal Barca cruza los Alpes con elefantes', -218, 'El general cartaginés sorprendió a Roma cruzando los gélidos Alpes con 37 elefantes de guerra para llevar la Segunda Guerra Púnica a Italia.', 'Solo un elefante de combate cartaginés, llamado Surus (''El Sirio''), sobrevivió a todo el invierno en suelo itálico.', 'Siglo III a.C.', 'Mountain', 'medio'),
  ('h-muralla-china', 'historia', 'Inicio de la Gran Muralla China unificada', -214, 'El primer emperador unió y reforzó las fortificaciones del norte para proteger a la naciente China unificada de los nómadas xiongnu.', 'El mortero utilizado para unir los bloques incluía harina de arroz pegajoso, haciéndolo resistente al salitre y al tiempo.', 'Siglo III a.C.', 'Castle', 'medio'),
  ('h-cleopatra-cesar', 'historia', 'Encuentro de Cleopatra y Julio César', -48, 'La joven reina egipcia recuperó su trono pactando una alianza política y militar con el comandante supremo de Roma.', 'Cleopatra burló la vigilancia de su hermano entrando de incógnito al palacio real envuelta dentro de un saco de ropa de cama.', 'Siglo I a.C.', 'Crown', 'medio'),
  ('h-julio-cesar', 'historia', 'Asesinato de Julio César en los Idus de Marzo', -44, 'Un grupo de más de 60 senadores apuñaló al dictador perpetuo en la Curia de Pompeyo, precipitando el fin de la República Romana.', 'César recibió 23 puñaladas, pero según el médico Antistio, solo una (la segunda en el pecho) fue mortal de necesidad.', 'Siglo I a.C.', 'Sword', 'medio'),
  ('h-batalla-accio', 'historia', 'Batalla de Accio y el fin del Egipto Ptolemaico', -31, 'La flota de Octavio derrotó a Marco Antonio y Cleopatra, convirtiendo a Egipto en provincia romana y dando inicio al Imperio Romano.', 'Con la muerte de Cleopatra VII terminó la dinastía ptolemaica y más de 3.000 años de historia de faraones en Egipto.', 'Siglo I a.C.', 'Anchor', 'medio'),
  ('h-erupcion-vesubio', 'historia', 'Erupción del Vesubio y destrucción de Pompeya', 79, 'El volcán italiano sepultó las prósperas ciudades romanas de Pompeya y Herculano bajo toneladas de ceniza y rocas piroclásticas.', 'El desastre preservó frescos, grafitis y panes intactos en los hornos, congelando la vida cotidiana romana en el tiempo.', 'Siglo I d.C.', 'Flame', 'medio'),
  ('h-coliseo-romano', 'historia', 'Inauguración del Coliseo Romano', 80, 'El emperador inauguró el Anfiteatro Flavio con 100 días ininterrumpidos de juegos gladiatorios y naumaquias (batallas navales inundadas).', 'Podía albergar hasta 65.000 espectadores y se desalojaba en solo 15 minutos gracias a sus 80 vomitorios.', 'Siglo I d.C.', 'Landmark', 'medio'),
  ('h-cangrande-pantheon', 'historia', 'Reconstrucción del Panteón de Agripa en Roma', 125, 'Templo erigido con la cúpula de hormigón no armado más grande del mundo, proeza insuperable de la ingeniería romana.', 'El óculo cenital superior de 9 metros está permanentemente abierto; el piso de mármol cuenta con pequeños orificios para drenar la lluvia.', 'Siglo II d.C.', 'Landmark', 'medio'),
  ('h-edicto-milan', 'historia', 'Edicto de Milán y libertad religiosa', 313, 'El emperador Constantino proclamó la tolerancia y libertad de culto en todo el Imperio Romano, deteniendo las sangrientas persecuciones a cristianos.', 'Devolvió a las comunidades cristianas todos los templos y propiedades confiscadas durante las persecuciones de Diocleciano.', 'Siglo IV d.C.', 'HeartHandshake', 'medio'),
  ('h-caida-roma', 'historia', 'Caída del Imperio Romano de Occidente', 476, 'El caudillo bárbaro Odoacro depuso al joven emperador Rómulo Augústulo, marcando tradicionalmente el fin de la Edad Antigua y el inicio del Medievo.', 'Paradójicamente, el último emperador de Roma compartía el nombre del mítico fundador de la ciudad (Rómulo) y del primer emperador (Augusto).', 'Siglo V d.C.', 'ShieldAlert', 'medio'),
  ('h-justiniano-santa-sofia', 'historia', 'Consagración de la Basílica de Santa Sofía', 537, 'La mayor catedral de la cristiandad durante casi mil años, joya insigne de la arquitectura y los mosaicos del Imperio Bizantino.', 'Al contemplar su colosal cúpula dorada por primera vez, Justiniano exclamó con orgullo: ''¡Salomón, te he superado!''.', 'Siglo VI d.C.', 'Landmark', 'medio'),
  ('h-islam-hejira', 'historia', 'La Hégira de Mahoma desde La Meca a Medina', 622, 'La emigración de la primera comunidad islámica para escapar de la persecución marcó el año cero del calendario musulmán.', 'En Medina se redactó la Carta de Medina, considerada uno de los primeros pactos constitucionales multi-religiosos de la historia.', 'Siglo VII d.C.', 'Moon', 'medio'),
  ('h-batalla-poitiers', 'historia', 'Batalla de Poitiers (Tours)', 732, 'El líder de los francos frenó el avance militar del Califato Omeya en Europa occidental en los campos de Tours.', 'La férrea falange defensiva de infantería de Carlos Martel resistió repetidas cargas de caballería sin romper filas.', 'Siglo VIII d.C.', 'Shield', 'medio'),
  ('h-carlomagno', 'historia', 'Coronación de Carlomagno como Emperador', 800, 'El papa coronó al rey de los francos en la Basílica de San Pedro en Roma en Navidad, resucitando la dignidad imperial en Europa occidental.', 'Carlomagno aprendió a leer en su adultez, pero nunca llegó a dominar la escritura, aunque dormía con tablillas bajo la almohada para practicar.', 'Siglo IX d.C.', 'Crown', 'medio'),
  ('h-vikingos-america', 'historia', 'Leif Erikson llega a Terranova (Vinland)', 1000, 'El navegante nórdico zarpó de Groenlandia y estableció el primer asentamiento europeo documentado en Norteamérica casi 500 años antes que Colón.', 'Llamó a la tierra ''Vinland'' (Tierra del Vino) porque encontraron abundantes parras de uvas silvestres.', 'Siglo X d.C.', 'Compass', 'medio'),
  ('h-batalla-hastings', 'historia', 'Batalla de Hastings y conquista normanda de Inglaterra', 1066, 'Guillermo de Normandía derrotó al rey anglosajón Harold Godwinson, transformando la monarquía británica, el idioma inglés y las leyes europeas.', 'Toda la batalla y la preparación naval quedaron inmortalizadas en el famoso Tapiz de Bayeux, un bordado de casi 70 metros de longitud.', 'Siglo XI d.C.', 'Swords', 'medio'),
  ('h-guilherme-conquistador-domesday', 'historia', 'Redacción del Gran Censo Domesday Book', 1086, 'El primer exhaustivo catastro general de tierras, animales, siervos y molinos de toda Inglaterra bajo la corona normanda.', 'Los súbditos le llamaron ''Domesday'' (Día del Juicio) porque sus dictámenes eran tan inapelables como el juicio de Dios.', 'Siglo XI d.C.', 'Scroll', 'medio'),
  ('h-cruzadas', 'historia', 'Conquista de Jerusalén en la Primera Cruzada', 1099, 'Los caballeros cruzados europeos asediaron y tomaron la Ciudad Santa, estableciendo el Reino Latino de Jerusalén.', 'Godofredo rechazó el título de rey de Jerusalén diciendo que jamás llevaría una corona de oro donde Jesús llevó una de espinas.', 'Siglo XI d.C.', 'Cross', 'medio'),
  ('h-carta-magna', 'historia', 'Firma de la Carta Magna en Inglaterra', 1215, 'Los barones ingleses forzaron al rey a aceptar que ningún monarca está por encima de la ley, sentando las bases del constitucionalismo moderno.', 'Introdujo el principio del ''Habeas Corpus'': ningún hombre libre podía ser encarcelado sin un juicio legal previo.', 'Siglo XIII d.C.', 'FileText', 'medio'),
  ('h-peste-negra', 'historia', 'Llegada de la Peste Negra a Europa', 1347, 'La epidemia de peste bubónica transmitida por pulgas en barcos genoveses aniquiló a más de un tercio de la población europea.', 'Dio origen al término ''cuarentena'': la ciudad de Venecia obligaba a los barcos a fondear 40 días antes de desembarcar.', 'Siglo XIV d.C.', 'Skull', 'medio'),
  ('h-juanna-arco-orleans', 'historia', 'Levantamiento del Sitio de Orleans por Juana de Arco', 1429, 'La joven campesina de 17 años lideró el ejército de Francia infundiendo un fervor patriótico que cambió la Guerra de los Cien Años.', 'Prefería portar su estandarte blanco con lirios dorados al frente de las tropas en lugar de empuñar la espada para no herir a nadie.', 'Siglo XV d.C.', 'Flag', 'medio'),
  ('h-constantinopla', 'historia', 'Caída de Constantinopla ante el Imperio Otomano', 1453, 'Los cañones otomanos derribaron las legendarias murallas teodosianas de Constantinopla, poniendo fin al Imperio Bizantino tras 1.100 años.', 'El cierre de las rutas comerciales terrestres hacia la India forzó a los europeos a buscar rutas marítimas, impulsando la era de los descubrimientos.', 'Siglo XV d.C.', 'Castle', 'medio'),
  ('h-colon-america', 'historia', 'Llegada de Cristóbal Colón a América', 1492, 'Tras más de dos meses de travesía en La Niña, La Pinta y La Santa María, la expedición avistó la isla de Guanahaní en las Bahamas.', 'Colón murió en 1506 convencido de que había llegado a las costas orientales de Asia y no a un continente desconocido para Europa.', 'Siglo XV d.C.', 'Ship', 'medio'),
  ('h-reyes-catolicos-granada', 'historia', 'Rendición de Granada ante los Reyes Católicos', 1492, 'La entrega pacífica de las llaves de la Alhambra puso fin a casi ocho siglos de dominio andalusí en la península ibérica.', 'El último emir nazarí, Boabdil, lloró al contemplar la ciudad por última vez en el paso conocido como ''El Suspiro del Moro''.', 'Siglo XV d.C.', 'Castle', 'medio'),
  ('h-reforma-lutero', 'historia', 'Martín Lutero publica las 95 Tesis en Wittenberg', 1517, 'El monje agustino clavó sus objeciones a la venta de indulgencias papales en la puerta de la iglesia del castillo, detonando la Reforma Protestante.', 'Gracias a la imprenta, sus 95 tesis fueron traducidas al alemán y se difundieron por toda Europa en menos de cuatro semanas.', 'Siglo XVI d.C.', 'BookOpen', 'medio'),
  ('h-conquista-mexico', 'historia', 'Caída de Tenochtitlan y conquista de México', 1521, 'Tras un largo asedio por tierra y agua en el lago Texcoco, los españoles y sus aliados tlaxcaltecas tomaron la capital azteca.', 'La ciudad de Tenochtitlan tenía más de 200.000 habitantes en su apogeo, siendo más grande y limpia que la mayoría de ciudades europeas de la época.', 'Siglo XVI d.C.', 'Pyramid', 'medio'),
  ('h-magallanes-elcano', 'historia', 'Primera vuelta al mundo (Magallanes y Elcano)', 1522, 'La nao Victoria regresó a España al mando de Elcano, completando la primera circunnavegación del globo terráqueo en la historia.', 'De los 250 tripulantes que zarparon en cinco barcos en 1519, solo 18 hombres famélicos regresaron vivos en un único barco.', 'Siglo XVI d.C.', 'Globe', 'medio'),
  ('h-armada-invencible', 'historia', 'Naufragio y dispersión de la Gran Armada Española', 1588, 'La colosal flota española enviada para invadir Inglaterra fue diezmada por tempestades atlánticas y brulotes en el Canal de la Mancha.', 'Felipe II acogió con resignación la noticia sentenciando: ''No envié mis naves a luchar contra los elementos''.', 'Siglo XVI d.C.', 'Ship', 'medio'),
  ('h-westfalia', 'historia', 'Paz de Westfalia y el estado-nación moderno', 1648, 'Puso fin a la devastadora Guerra de los Treinta Años y consagró el principio de soberanía territorial: ningún imperio puede intervenir en los asuntos de otro estado.', 'Fue el primer congreso diplomático formal de la historia moderna, estableciendo el protocolo de embajadas que usamos hoy.', 'Siglo XVII d.C.', 'FileCheck', 'medio'),
  ('h-independencia-eeuu', 'historia', 'Declaración de Independencia de EE. UU.', 1776, 'Las Trece Colonias norteamericanas proclamaron su separación de la Corona Británica en Filadelfia, proclamando la igualdad y los derechos inalienables.', '56 delegados firmaron el pergamino, sabiendo que cometían delito de alta traición castigado con la horca por el rey Jorge III.', 'Siglo XVIII d.C.', 'Scroll', 'medio'),
  ('h-paz-versalles-1783', 'historia', 'Tratado de París y reconocimiento de EE.UU.', 1783, 'Gran Bretaña reconoció formalmente la soberanía e independencia de las trece colonias americanas tras la guerra.', 'El retrato pictórico conmemorativo quedó inconcluso porque los diplomáticos británicos se negaron a posar junto a los vencedores.', 'Siglo XVIII d.C.', 'FileText', 'medio'),
  ('h-revolucion-francesa', 'historia', 'Toma de la Bastilla y Revolución Francesa', 1789, 'El pueblo de París asaltó la prisión fortaleza real, dando inicio al derrumbe del Antiguo Régimen y la proclamación de los Derechos del Hombre.', 'El rey Luis XVI escribió en su diario ese día la palabra ''Rien'' (Nada), creyendo que solo era un disturbio pasajero.', 'Siglo XVIII d.C.', 'Flag', 'medio'),
  ('h-napoleon-emperador', 'historia', 'Coronación de Napoleón Bonaparte como Emperador', 1804, 'En la catedral de Notre Dame de París, Napoleón tomó la corona de manos del papa Pío VII y se la colocó él mismo en la cabeza para demostrar que su poder no dependía de la Iglesia.', 'Estableció el Código Civil Napoleónico, que sigue siendo la base legal de gran parte de Europa y América Latina.', 'Siglo XIX d.C.', 'Crown', 'medio'),
  ('h-waterloo', 'historia', 'Batalla de Waterloo y derrota final de Napoleón', 1815, 'Las fuerzas británicas y prusianas vencieron al ejército de Napoleón en Bélgica, poniendo fin a las Guerras Napoleónicas y enviándolo al exilio en Santa Elena.', 'La lluvia torrencial de la noche previa impidió a Napoleón mover su artillería temprano en la mañana, retraso que fue decisivo para su derrota.', 'Siglo XIX d.C.', 'Swords', 'medio'),
  ('h-lincoln-emancipacion', 'historia', 'Proclamación de Emancipación de Abraham Lincoln', 1863, 'En plena Guerra Civil estadounidense, el presidente Lincoln declaró libres para siempre a más de 3,5 millones de personas esclavizadas en los estados confederados.', 'Lincoln afirmó: ''Si mi nombre alguna vez pasa a la historia, será por este acto, y mi alma entera está puesta en él''.', 'Siglo XIX d.C.', 'Unlock', 'medio'),
  ('h-titanic', 'historia', 'Hundimiento del transatlántico RMS Titanic', 1912, 'El barco de pasajeros más grande y lujoso de su tiempo chocó contra un iceberg en su viaje inaugural y se hundió en menos de tres horas en el Atlántico Norte.', 'Llevaba botes salvavidas solo para 1.178 personas, a pesar de que a bordo viajaban más de 2.220 entre pasajeros y tripulación.', 'Siglo XX d.C.', 'Ship', 'medio'),
  ('h-primera-guerra', 'historia', 'Inicio de la Primera Guerra Mundial', 1914, 'El magnicidio del heredero austrohúngaro en Sarajevo activó el sistema de alianzas europeas, desatando la Gran Guerra de trincheras.', 'Fue el primer conflicto militar masivo donde se emplearon tanques de guerra, aviación de combate y armas químicas.', 'Siglo XX d.C.', 'Bomb', 'medio'),
  ('h-canal-panama', 'historia', 'Apertura oficial del Canal de Panamá', 1914, 'Titánica obra de ingeniería interoceánica con esclusas que unió la navegación del Atlántico y el Pacífico.', 'El barco de vapor Ancón fue la primera nave en cruzar el canal el 15 de agosto de 1914 en plena eclosión de la Primera Guerra Mundial.', 'Siglo XX d.C.', 'Anchor', 'medio')
INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('h-revolucion-rusa', 'historia', 'Revolución Rusa de Octubre y auge bolchevique', 1917, 'Los bolcheviques asaltaron el Palacio de Invierno en Petrogrado, derrocaron al gobierno provisional y fundaron el primer estado socialista del mundo.', 'El crucero militar Aurora disparó una salva sin munición que fue la señal acordada para comenzar el asalto.', 'Siglo XX d.C.', 'Flame', 'medio'),
  ('h-crisis-1929', 'historia', 'El Jueves Negro y el Crack bursátil de Wall Street', 1929, 'El desplome financiero de la bolsa estadounidense hundió a la economía global en la mayor recesión del siglo XX.', 'En un solo día de ventas histéricas se ofertaron casi 13 millones de acciones sin que existieran compradores.', 'Siglo XX d.C.', 'TrendingDown', 'medio'),
  ('h-segunda-guerra', 'historia', 'Invasión de Polonia e inicio de la 2ª Guerra Mundial', 1939, 'Alemania invadió Polonia mediante la guerra relámpago (Blitzkrieg), llevando a Gran Bretaña y Francia a declarar la guerra y desatar el conflicto más mortífero de la historia.', 'Más de 100 millones de militares fueron movilizados en todo el mundo durante el conflicto.', 'Siglo XX d.C.', 'ShieldAlert', 'medio'),
  ('h-dia-d', 'historia', 'Desembarco de Normandía (Día D)', 1944, 'Más de 150.000 soldados aliados cruzaron el canal de la Mancha en la mayor operación anfibia de la historia militar para liberar a Francia.', 'La operación de engaño militar ''Guardaespaldas'' creó un ejército fantasma inflable en Inglaterra para hacer creer a los nazis que desembarcarían en Calais.', 'Siglo XX d.C.', 'Compass', 'medio'),
  ('h-hiroshima', 'historia', 'Lanzamiento de la bomba atómica sobre Hiroshima', 1945, 'El bombardero Enola Gay arrojó la bomba atómica ''Little Boy'' sobre la ciudad japonesa, precipitando el fin de la guerra y abriendo la Era Nuclear.', 'La temperatura en el hipocentro de la explosión superó los 4.000 grados Celsius, vaporizando instantáneamente el acero y la piedra.', 'Siglo XX d.C.', 'Zap', 'medio'),
  ('h-naciones-unidas', 'historia', 'Firma de la Carta fundacional de la ONU', 1945, 'Nace la Organización de las Naciones Unidas para promover la paz mundial y prevenir futuros conflictos tras la Segunda Guerra Mundial.', 'A China se le concedió el honor de estampar la primera firma en el documento oficial en reconocimiento a sus millones de víctimas.', 'Siglo XX d.C.', 'Globe', 'medio'),
  ('h-tratado-roma', 'historia', 'Firma del Tratado de Roma (Nacimiento de la UE)', 1957, 'Seis países europeos crearon la Comunidad Económica Europea, apostando por la integración comercial y la paz tras siglos de guerras sangrientas.', 'El tratado original tuvo que firmarse con páginas en blanco en su interior porque la imprenta suiza no alcanzó a imprimir los anexos a tiempo.', 'Siglo XX d.C.', 'Handshake', 'medio'),
  ('h-muro-berlin-construccion', 'historia', 'Construcción del Muro de Berlín', 1961, 'La Alemania oriental comunista levantó de la noche a la mañana una barrera fortificada de hormigón para frenar el éxodo masivo de ciudadanos hacia Occidente.', 'Dividió familias enteras durante 28 años y llegó a tener más de 155 kilómetros de perímetro fortificado.', 'Siglo XX d.C.', 'Wall', 'medio'),
  ('h-crisis-misiles-cuba', 'historia', 'Crisis de los Misiles en Cuba', 1962, 'Trece días de tensión límite entre EE.UU. y la Unión Soviética que llevaron a la humanidad al filo de la guerra nuclear.', 'A raíz de este episodio se creó el famoso ''teléfono rojo'', un enlace directo de teletipo cifrado entre la Casa Blanca y el Kremlin.', 'Siglo XX d.C.', 'AlertTriangle', 'medio'),
  ('h-muro-berlin-caida', 'historia', 'Caída del Muro de Berlín y fin de la Guerra Fría', 1989, 'Miles de ciudadanos derribaron el muro con picos y martillos tras una confusa conferencia de prensa oficial, simbolizando el colapso del bloque soviético.', 'El portavoz Günter Schabowski leyó mal un borrador y dijo por televisión que los permisos de viaje entraban en vigor ''inmediatamente, sin demora''.', 'Siglo XX d.C.', 'Unlock', 'medio'),
  ('h-fin-apartheid-mandela', 'historia', 'Elecciones democráticas y fin del Apartheid', 1994, 'Primeros comicios sin segregación racial en Sudáfrica que consagraron a Nelson Mandela como presidente tras 27 años de cárcel.', 'Millones de votantes de todas las razas formaron filas de varios kilómetros durante días bajo el lema de la ''Nación del Arcoíris''.', 'Siglo XX d.C.', 'Award', 'medio'),
  ('h-atentados-11s', 'historia', 'Atentados del 11 de Septiembre en Nueva York', 2001, 'Cuatro aviones secuestrados fueron estrellados contra las Torres Gemelas y el Pentágono, transformando para siempre la geopolítica y la seguridad mundial.', 'El rescate civil movilizó una flotilla espontánea de barcos civiles en Manhattan que evacuó a más de 500.000 personas por agua en un solo día.', 'Siglo XXI d.C.', 'AlertTriangle', 'medio'),
  ('b-arca-noe', 'biblia', 'El Arca de Noé y el Gran Diluvio', -2400, 'Preservación milagrosa de la vida terrestre ante las aguas del juicio divino mediante un arca de madera de gofer calafateada con brea.', 'El arca medía unos 300 codos de largo (aprox. 135 metros), proporciones idénticas a las utilizadas por los cargueros modernos de altamar.', 'Siglo XXIV a.C.', 'Ship', 'medio'),
  ('b-torre-babel', 'biblia', 'La Torre de Babel y la confusión de lenguas', -2200, 'Los seres humanos intentaron erigir una torre que alcanzara el cielo para hacerse un nombre, resultando en la dispersión lingüística de las naciones.', 'El término hebreo ''Babel'' alude fonéticamente al verbo ''balal'', que denota mezclar o confundir.', 'Siglo XXII a.C.', 'Landmark', 'medio'),
  ('b-abraham-llamado', 'biblia', 'Llamado de Abraham a salir de Ur', -2091, 'Dios llamó a Abram a dejar su tierra idólatra y su parentela para viajar hacia la tierra prometida de Canaán, prometiéndole hacer de él una gran nación.', 'Ur de los Caldeos era en esa época una de las metrópolis comerciales y astrológicas más avanzadas del mundo antiguo mesopotámico.', 'Siglo XXI a.C.', 'Compass', 'medio'),
  ('b-jose-egipto', 'biblia', 'José es vendido y asciende a gobernador de Egipto', -1876, 'Traicionado por la envidia de sus hermanos y encarcelado injustamente, José interpretó los sueños del Faraón y salvó a la región de una gran hambruna.', 'Su túnica de muchos colores era un manto ceremonial propio de príncipes y herederos en el Cercano Oriente.', 'Siglo XIX a.C.', 'Crown', 'medio'),
  ('b-sacrificio-isaac', 'biblia', 'La prueba de fe de Abraham en el Monte Moriah', -1850, 'Dios probó la obediencia de Abraham pidiéndole la entrega de su hijo prometido, proveyendo finalmente un carnero trabado en un zarzal.', 'El monte Moriah es identificado por las Escrituras como el lugar exacto donde Salomón erigiría el Templo de Jerusalén siglos después.', 'Siglo XIX a.C.', 'Mountain', 'medio'),
  ('b-escala-jacob', 'biblia', 'La escalera celestial de Jacob en Betel', -1770, 'Mientras huía hacia Harán, Jacob soñó con una escalera que unía la tierra con el cielo por donde ascendían y descendían ángeles de Dios.', 'Jacob tomó la piedra que le sirvió de cabecera, la ungió con aceite como memorial y proclamó: ''¡Cuán terrible es este lugar! No es otra cosa que casa de Dios''.', 'Siglo XVIII a.C.', 'Sparkles', 'medio'),
  ('b-exodo-mar-rojo', 'biblia', 'El Éxodo y cruce milagroso del Mar Rojo', -1446, 'Tras las diez plagas sobre Egipto, el pueblo de Israel salió de la esclavitud y cruzó a pie enjuto por medio del mar abierto ante la persecución del faraón.', 'La fiesta de la Pascua judía (Pésaj) conmemora anualmente esta misma noche de liberación desde hace más de 3.400 años.', 'Siglo XV a.C.', 'Waves', 'medio'),
  ('b-zarza-ardiente', 'biblia', 'Llamado de Moisés ante la zarza ardiente', -1446, 'Jehová se manifestó en una zarza que ardía sin consumirse y reveló su Nombre sagrado ''YO SOY EL QUE SOY'' para comisionar la liberación de Israel.', 'Moisés debió descalzarse de inmediato porque el suelo donde pisaba había sido consagrado como tierra santa por la presencia divina.', 'Siglo XV a.C.', 'Flame', 'medio'),
  ('b-tablas-ley', 'biblia', 'Entrega de la Ley en el Monte Sinaí', -1445, 'Moisés subió a la cumbre humeante del monte y recibió de Dios los Diez Mandamientos tallados en tablas de piedra.', 'El arca de la alianza fue construida con madera de acacia, el único árbol capaz de sobrevivir en el árido desierto del Sinaí.', 'Siglo XV a.C.', 'Scroll', 'medio'),
  ('b-plagas-egipto', 'biblia', 'Las diez plagas sobre la tierra de Egipto', -1445, 'Poderosas señales milagrosas que desmoronaron el poderío de los faraones y sus dioses tutelares hasta lograr la libertad del pueblo hebreo.', 'Cada una de las plagas desafió y venció directamente a deidades del panteón egipcio (como Hapi en el Nilo de sangre o Ra en las tinieblas).', 'Siglo XV a.C.', 'Zap', 'medio'),
  ('b-mana-desierto', 'biblia', 'La provisión diaria del Maná en el desierto', -1444, 'Pan del cielo que descendía cada mañana como escarcha menuda alimentando a cientos de miles de israelitas durante cuarenta años de travesía.', 'El nombre ''maná'' proviene de la pregunta de asombro de los hebreos al verlo: ''¿Man-hu?'', que significa en hebreo ''¿Qué es esto?''.', 'Siglo XV a.C.', 'Sun', 'medio'),
  ('b-murallas-jerico', 'biblia', 'Caída de las murallas de Jericó', -1406, 'Siguiendo la instrucción divina, los sacerdotes y guerreros marcharon siete días alrededor de la ciudad fortificada; al sonar las trompetas y clamar el pueblo, los muros colapsaron.', 'Jericó es considerada por los arqueólogos como una de las ciudades amuralladas habitadas más antiguas del planeta.', 'Siglo XV a.C.', 'Castle', 'medio'),
  ('b-sol-detenido-josue', 'biblia', 'El sol se detiene sobre Gabaón en la batalla', -1400, 'En apoyo a los gabaonitas contra los reyes amorreos, Josué oró y el sol y la luna se detuvieron casi un día entero para consumar la victoria.', 'El libro de Josué consigna que ''no hubo día como aquel, ni antes ni después de él, habiendo atendido Jehová a la voz de un hombre''.', 'Siglo XIV a.C.', 'Sun', 'medio'),
  ('b-debora-barac', 'biblia', 'Victoria de Débora y Barac en el Monte Tabor', -1235, 'Débora convocó al ejército israelita y venció a los 900 carros de hierro del general cananeo Sísara junto al torrente de Cisón.', 'Fue la única jueza mujer mencionada en el libro de los Jueces, juzgando al pueblo bajo una palmera en la región montañosa de Efraín.', 'Siglo XIII a.C.', 'Shield', 'medio'),
  ('b-gedeon-valientes', 'biblia', 'Gedeón y sus 300 valientes derrotan a Madián', -1160, 'Dios redujo el ejército de 32.000 a solo 300 hombres armados únicamente con trompetas, cántaros y antorchas para demostrar que la victoria provenía del Señor.', 'El método de selección consistió en observar cómo bebían agua en el arroyo: los que lamían el agua vigilando alertas fueron los elegidos.', 'Siglo XII a.C.', 'Torch', 'medio'),
  ('b-samuel-ungimiento', 'biblia', 'Llamamiento del profeta Samuel en Silo', -1075, 'Siendo aún un niño en el tabernáculo de Silo, Samuel escuchó la voz de Dios en la noche y fue establecido como el gran profeta y juez que ungió a los primeros reyes de Israel.', 'Samuel ungió tanto al primer rey (Saúl) como al rey más importante de la dinastía mesiánica (David).', 'Siglo XI a.C.', 'Bell', 'medio'),
  ('b-sansone-filisteos', 'biblia', 'Hazañas y último sacrificio de Sansón en Gaza', -1075, 'Juez dotado de fuerza sobrehumana por el Espíritu Santo que derribó las columnas maestras del templo de Dagón liberando a su pueblo.', 'El texto bíblico señala que mató a más enemigos filisteos en el instante de su muerte que a lo largo de toda su vida terrenal.', 'Siglo XI a.C.', 'Dumbbell', 'medio'),
  ('b-saul-rey', 'biblia', 'Saúl es ungido como el primer rey de Israel', -1050, 'Ante la petición del pueblo de tener un monarca como las demás naciones, Samuel ungió a Saúl de la tribu de Benjamín como primer rey.', 'El texto bíblico resalta que Saúl sobrepasaba a todo el pueblo desde los hombros para arriba por su gran estatura física.', 'Siglo XI a.C.', 'Crown', 'medio'),
  ('b-david-goliat', 'biblia', 'David vence al gigante Goliat en el valle de Ela', -1025, 'El joven pastor David rechazó la pesada armadura del rey Saúl y derribó al campeón filisteo de casi tres metros con una honda y una sola piedra lisa.', 'Goliat desafió a los ejércitos de Israel durante 40 días consecutivos por la mañana y por la tarde antes del combate.', 'Siglo XI a.C.', 'Target', 'medio'),
  ('b-david-coronado', 'biblia', 'David es coronado rey sobre todo Israel', -1003, 'Todas las tribus se unieron en Hebrón para ungir a David como rey unificado. Poco después conquistó la fortaleza de Jebús y la nombró Jerusalén.', 'David reinó 7 años en Hebrón y 33 años en Jerusalén, completando 40 años de gobierno.', 'Siglo XI a.C.', 'Crown', 'medio'),
  ('b-arca-jerusalen-david', 'biblia', 'David traslada el Arca del Pacto a Jerusalén', -1000, 'El monarca unificó a la nación entronizando la presencia divina en la Ciudad de David entre trompetas, danzas y sacrificios de alabanza.', 'David danzó con júbilo vistiendo un sencillo efod de lino, motivo por el cual su esposa Mical lo censuró desde la ventana.', 'Siglo X a.C.', 'Music', 'medio'),
  ('b-juicio-salomon', 'biblia', 'El juicio sabio de Salomón entre dos madres', -960, 'Resolvió la disputa de un bebé fingiendo partirlo en dos con una espada, descubriendo de inmediato el amor de la verdadera madre.', 'La fama de su entendimiento atrajo a la reina de Saba, quien viajó miles de kilómetros en caravana de camellos para comprobar sus enigmas.', 'Siglo X a.C.', 'Crown', 'medio'),
  ('b-templo-salomon', 'biblia', 'Dedicación del Templo de Salomón en Jerusalén', -959, 'Tras siete años de edificación con cedros del Líbano y oro purísimo, la presencia divina en forma de nube (Shejiná) llenó la Casa del Señor.', 'No se escuchó sonido de hachas ni martillos en el monte sagrado durante las obras: las piedras llegaban talladas exactamente desde la cantera.', 'Siglo X a.C.', 'Landmark', 'medio'),
  ('b-reino-dividido', 'biblia', 'División del reino: Israel y Judá', -931, 'A la muerte de Salomón, diez tribus del norte se rebelaron contra los altos tributos de Roboam y fundaron el Reino del Norte (Israel) bajo Jeroboam.', 'A partir de este momento, los profetas bíblicos profetizaron a menudo a dos naciones separadas de hermanos.', 'Siglo X a.C.', 'GitFork', 'medio'),
  ('b-elias-carmelo', 'biblia', 'Elías y el fuego del cielo en el Monte Carmelo', -860, 'Elías desafió a 450 profetas de Baal; tras empapar su altar con doce cántaros de agua, oró y cayó fuego del cielo que consumió el holocausto y las piedras.', 'El pueblo cayó sobre sus rostros y gritó al unísono: ''¡El Señor es Dios! ¡El Señor es Dios!''', 'Siglo IX a.C.', 'Flame', 'medio'),
  ('b-elias-arrebato', 'biblia', 'Elías arrebatado al cielo en un carro de fuego', -850, 'El gran profeta de Israel fue llevado en un torbellino por un carro y caballos de fuego junto al río Jordán sin experimentar la muerte física.', 'Eliseo recogió el manto caído de su maestro y con él golpeó las aguas del Jordán, las cuales se abrieron a ambos lados de inmediato.', 'Siglo IX a.C.', 'Flame', 'medio'),
  ('b-jonas-ninive', 'biblia', 'Proclamación de Jonás y arrepentimiento de Nínive', -760, 'Tras permanecer tres días en el vientre de un gran pez, proclamó el mensaje divino en la orgullosa capital asiria logrando su conversión masiva.', 'El rey ninivita promulgó un ayuno riguroso en el que incluso el ganado y las bestias debieron vestir tela de cilicio y abstenerse de pastar.', 'Siglo VIII a.C.', 'Fish', 'medio'),
  ('b-caida-samaria', 'biblia', 'Caída de Samaria y cautiverio del Reino del Norte', -722, 'El ejército asirio conquistó la capital de Israel tras un asedio de tres años y deportó a las diez tribus hacia Mesopotamia y Media.', 'Los asirios repoblaron la región con colonos de Babilonia y Cutha, dando origen a la población samaritana.', 'Siglo VIII a.C.', 'ShieldAlert', 'medio'),
  ('b-ezequias-jerusalen', 'biblia', 'Liberación milagrosa de Jerusalén ante Senaquerib', -701, 'El emperador asirio sitió Jerusalén con un ejército formidable. El rey Ezequías oró en el Templo y el ángel del Señor salvó la ciudad durante la noche.', 'Ezequías excavó un túnel subterráneo en la roca viva de más de 500 metros para meter agua desde la fuente de Gijón a la ciudad protegida.', 'Siglo VIII a.C.', 'ShieldCheck', 'medio'),
  ('b-angeles-senoquerib', 'biblia', 'Liberación milagrosa de Jerusalén del asedio asirio', -701, 'El ángel de Jehová derrotó en una sola noche a 185.000 soldados asirios sitiadores respondiendo a la ferviente oración de Ezequías.', 'El prisma de arcilla del rey asirio Senaquerib descubierto por la arqueología confiesa que encerró a Ezequías ''como ave enjaulada'', pero jamás conquistó la urbe.', 'Siglo VIII a.C.', 'Shield', 'medio'),
  ('b-josias-reforma', 'biblia', 'El rey Josías halla el Libro de la Ley e inicia la reforma', -622, 'Durante las reparaciones del Templo abandonado, el sumo sacerdote Hilcías encontró el rollo de la Torá, provocando el arrepentimiento y una gran renovación nacional.', 'Josías ordenó celebrar la Pascua con una solemnidad y pureza que no se había visto desde los días de los jueces.', 'Siglo VII a.C.', 'BookOpen', 'medio'),
  ('b-exilio-babilonia', 'biblia', 'Destrucción de Jerusalén y exilio a Babilonia', -586, 'Las tropas babilónicas quemaron el Templo de Salomón, derribaron las murallas de la ciudad y llevaron cautiva a la élite de Judá a Babilonia.', 'Durante este exilio de 70 años, la fe judía se consolidó alrededor de las sinagogas y la recopilación de los textos sagrados.', 'Siglo VI a.C.', 'Flame', 'medio'),
  ('b-horno-fuego-babilonia', 'biblia', 'Los tres hebreos ilesos en el horno de Babilonia', -585, 'Se negaron a inclinarse ante la estatua dorada de Nabucodonosor y caminaron sueltos e ilesos en medio del fuego siete veces calentado.', 'El emperador babilónico contempló atónito a cuatro figuras en el fuego y declaró que la cuarta tenía apariencia ''semejante a un hijo de los dioses''.', 'Siglo VI a.C.', 'Flame', 'medio'),
  ('b-valle-huesos-secos', 'biblia', 'Visión profética de los huesos secos de Ezequiel', -580, 'Visión simbólica donde un valle lleno de osamentas áridas se reviste de tendones, piel y aliento de vida proclamando la restauración de Israel.', 'El Señor le preguntó a Ezequiel: ''Hijo de hombre, ¿vivirán estos huesos?'', a lo que el profeta respondió con reverencia: ''Señor Jehová, tú lo sabes''.', 'Siglo VI a.C.', 'Sparkles', 'medio'),
  ('b-escritura-pared-balsasar', 'biblia', 'La misteriosa escritura en la pared de Belsasar', -539, 'Durante una fiesta idólatra aparecieron dedos humanos trazando: MENE, MENE, TEKEL, UPARSIN, anunciando la caída inminente del imperio babilónico.', 'Esa misma noche las tropas persas de Ciro el Grande vadearon el cauce del Éufrates y tomaron la gran Babilonia sin resistencia armada.', 'Siglo VI a.C.', 'Scroll', 'medio'),
  ('b-daniel-foso', 'biblia', 'Daniel es librado en el foso de los leones', -538, 'Arrojado al foso por negarse a dejar de orar a Dios tres veces al día, Dios envió a su ángel para cerrar la boca de los leones hambrientos.', 'El rey Darío pasó la noche en vela ayunando y al amanecer corrió conmovido gritando: ''¡Daniel, siervo del Dios vivo, ¿ha podido tu Dios librarte?!''', 'Siglo VI a.C.', 'Cat', 'medio'),
  ('b-decreto-ciro', 'biblia', 'Decreto de Ciro el Grande y retorno a Jerusalén', -536, 'El rey persa Ciro conquistó Babilonia y promulgó un edicto permitiendo a los judíos regresar a su patria y reconstruir el Templo del Señor.', 'El ''Cilindro de Ciro'', descubierto en 1879, confirma arqueológicamente su política de repatriar a los pueblos exiliados con sus cultos.', 'Siglo VI a.C.', 'Scroll', 'medio'),
  ('b-ester-haman', 'biblia', 'La reina Ester intercede y salva a su pueblo', -480, 'Arriesgando su vida al presentarse ante el rey Asuero sin ser llamada, la joven reina judía desenmascaró el genocidio planeado por el malvado Amán.', 'Este acontecimiento dio origen a la fiesta judía de Purim, que se celebra con regocijo y donaciones a los necesitados.', 'Siglo V a.C.', 'Crown', 'medio')
INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('b-nehemias-muros', 'biblia', 'Nehemías reconstruye los muros de Jerusalén en 52 días', -445, 'Copero del rey de Persia, Nehemías lideró a los pobladores que reconstruyeron las murallas caídas con una mano sosteniendo el palustre y con la otra la espada.', 'La rapidez de la obra (menos de dos meses) causó temor y asombro entre los gobernadores enemigos vecinos.', 'Siglo V a.C.', 'Hammer', 'medio'),
  ('b-nacimiento-jesus', 'biblia', 'Nacimiento de Jesús en Belén de Judea', -4, 'El Mesías prometido nació en un humilde establo de Belén y fue recostado en un pesebre, anunciado por coros angelicales a los pastores.', 'El cálculo erróneo del monje Dionisio el Exiguo en el siglo VI situó el año 1 un poco después de la muerte real de Herodes el Grande.', 'Siglo I a.C.', 'Star', 'medio'),
  ('b-anunciacion-maria', 'biblia', 'La Anunciación del Ángel Gabriel a María', -4, 'El mensajero celestial anunció en Nazaret el nacimiento virginal del Salvador por la sombra y el poder del Espíritu Santo.', 'La humilde sumisión de María (''Hágase en mí según tu palabra'') es recordada en la historia teológica como el momento del ''Fiat''.', 'Siglo I a.C.', 'Heart', 'medio'),
  ('b-bautismo-jesus', 'biblia', 'Bautismo de Jesús por Juan en el río Jordán', 26, 'Al salir Jesús de las aguas del Jordán, los cielos se abrieron, el Espíritu Santo descendió como paloma y una voz del cielo proclamó: ''Este es mi Hijo amado''.', 'Juan el Bautista vestía ropas de pelo de camello y se alimentaba de langostas del desierto y miel silvestre.', 'Siglo I d.C.', 'Droplets', 'medio'),
  ('b-sermon-monte', 'biblia', 'Jesús proclama el Sermón del Monte y Bienaventuranzas', 28, 'El discurso medular de la ética cristiana pronunciado frente al Mar de Galilea, enseñando a amar a los enemigos y ser luz del mundo.', 'En esta solemne ocasión Jesús enseñó a sus discípulos el modelo perfecto de oración conocido universalmente como el Padre Nuestro.', 'Siglo I d.C.', 'BookOpen', 'medio'),
  ('b-multiplicacion-panes', 'biblia', 'La multiplicación milagrosa de los panes y peces', 29, 'Con solo cinco panes de cebada y dos peces aportados por un muchacho, Jesús bendijo y sació a miles sobrando doce cestas colmadas.', 'Es el único milagro público de Jesús que se encuentra relatado en los cuatro Evangelios canónicos (Mateo, Marcos, Lucas y Juan).', 'Siglo I d.C.', 'Sparkles', 'medio'),
  ('b-crucifixion-resurreccion', 'biblia', 'Crucifixión y Resurrección de Jesús en Jerusalén', 30, 'Crucificado fuera de las murallas en el Gólgota bajo Poncio Pilato, resucitó victorioso al tercer día, dejando la tumba vacía y venciendo la muerte.', 'El velo del Templo que separaba el Lugar Santo del Lugar Santísimo se rasgó de arriba a abajo en el momento de su expiración.', 'Siglo I d.C.', 'Cross', 'medio'),
  ('b-pentecostes', 'biblia', 'Llegada del Espíritu Santo en Pentecostés', 30, 'Reunidos en el aposento alto, un viento recio llenó la casa y lenguas de fuego se posaron sobre ellos; Pedro predicó y ese día se bautizaron 3.000 personas.', 'Los discípulos hablaron en diversas lenguas extranjeras que eran comprendidas con asombro por peregrinos llegados de más de 15 regiones del mundo.', 'Siglo I d.C.', 'Flame', 'medio'),
  ('b-resurreccion-lazaro', 'biblia', 'La resurrección de Lázaro en Betania', 30, 'Jesús ordenó abrir el sepulcro de roca y exclamó ''¡Lázaro, ven fuera!'', saliendo el difunto atado con vendas tras cuatro días de muerto.', 'Momentos antes del prodigio se registra el versículo más corto y emotivo de las Sagradas Escrituras: ''Jesús lloró'' (Juan 11:35).', 'Siglo I d.C.', 'Heart', 'medio'),
  ('b-entrada-triunfal', 'biblia', 'Entrada triunfal de Jesús en Jerusalén (Domingo de Ramos)', 33, 'Aclamado como Rey de Israel por una multitud que tendía sus mantos y ramas de palmera al grito festivo de ''¡Hosanna en las alturas!''.', 'Entró montado pacíficamente sobre un pollino de asna, cumpliendo con exactitud milimétrica la profecía veterotestamentaria de Zacarías.', 'Siglo I d.C.', 'Sun', 'medio'),
  ('b-ultima-cena', 'biblia', 'La Última Cena e institución del Nuevo Pacto', 33, 'En el aposento alto lavó los pies de los discípulos e instituyó el pan y la copa como memoria perpetua de su cuerpo y su sangre.', 'Jesús les legó en esa cena el mandamiento nuevo: ''Que os améis unos a otros como yo os he amado''.', 'Siglo I d.C.', 'Wine', 'medio'),
  ('b-getsemani-oracion', 'biblia', 'Agonía y oración de Jesús en el huerto de Getsemaní', 33, 'En profunda angustia oró con sudores como gotas de sangre: ''Padre, si es tu voluntad aparta de mí esta copa; pero no se haga mi voluntad, sino la tuya''.', 'El nombre ''Getsemaní'' proviene del arameo ''Gath-Šmānê'' y significa literalmente ''prensa de aceite'' o lagar de olivas.', 'Siglo I d.C.', 'Moon', 'medio'),
  ('b-camino-emaus', 'biblia', 'Aparición de Jesús a los discípulos camino a Emaús', 33, 'Acompañó de incógnito a dos discípulos desanimados desgranando las profecías mesiánicas, siendo reconocido solo al partir el pan.', 'Al reconocerlo y desaparecer de su vista, exclamaron con gozo: ''¿No ardía nuestro corazón en nosotros mientras nos hablaba en el camino?''.', 'Siglo I d.C.', 'Footprints', 'medio'),
  ('b-ascension-monte-olivos', 'biblia', 'La gloriosa Ascensión de Jesucristo a los cielos', 33, 'Cuarenta días después de resucitar, bendijo a los discípulos en el Monte de los Olivos y fue elevado ante sus ojos envuelto en una nube.', 'Dos ángeles con vestiduras blancas prometieron a los apóstoles: ''Este mismo Jesús que ha sido tomado vendrá así de la misma manera''.', 'Siglo I d.C.', 'Cloud', 'medio'),
  ('b-conversion-pablo', 'biblia', 'Conversión de Saulo en el camino a Damasco', 34, 'El perseguidor de la Iglesia fue derribado por una luz resplandeciente del cielo y escuchó la voz de Jesús: ''Saulo, Saulo, ¿por qué me persigues?'', transformándolo en el gran apóstol de los gentiles.', 'Estuvo ciego tres días en Damasco sin comer ni beber hasta que Ananías le impuso las manos y cayeron de sus ojos como escamas.', 'Siglo I d.C.', 'Sun', 'medio'),
  ('b-esteban-martirio', 'biblia', 'Martirio de Esteban, primer mártir cristiano', 35, 'Lleno de fe y del Espíritu Santo, Esteban defendió la verdad ante el Sanedrín y oró por sus asesinos mientras era apedreado: ''Señor, no les tomes en cuenta este pecado''.', 'Los testigos que apedrearon a Esteban dejaron sus mantos a los pies de un joven fariseo fanático llamado Saulo.', 'Siglo I d.C.', 'Sparkles', 'medio'),
  ('b-concilio-jerusalen', 'biblia', 'Concilio de Jerusalén (Hechos 15)', 49, 'Los apóstoles y ancianos acordaron que la salvación es por la gracia de Cristo mediante la fe y no requería someter a los creyentes no judíos a las ordenanzas rituales de la circuncisión mosaica.', 'Fue la primera gran asamblea teológica y ecuménica de la Iglesia universal de la que se tiene registro.', 'Siglo I d.C.', 'Users', 'medio'),
  ('b-carcelero-filipos', 'biblia', 'Terremoto y salvación del carcelero de Filipos', 50, 'A medianoche, mientras cantaban himnos en el calabozo, un sismo abrió los cerrojos y el custodio conmovido halló la fe con su familia.', 'El carcelero cayó de rodillas preguntando ''¿Qué debo hacer para ser salvo?'', recibiendo la respuesta: ''Cree en el Señor Jesucristo y serás salvo tú y tu casa''.', 'Siglo I d.C.', 'Music', 'medio'),
  ('b-areopago-atenas', 'biblia', 'Discurso del Apóstol Pablo en el Areópago de Atenas', 51, 'Debatió con filósofos atenienses epicúreos y estoicos partiendo del monumento dedicado ''Al Dios No Conocido'' para predicar la resurrección.', 'Pablo citó con destreza versos de poetas clásicos griegos como Arato y Epiménides: ''Porque en él vivimos, nos movemos y somos''.', 'Siglo I d.C.', 'BookOpen', 'medio'),
  ('b-naufragio-malta', 'biblia', 'Naufragio y supervivencia de Pablo en la Isla de Malta', 60, 'La nave que lo conducía encadenado a Roma sucumbió a dos semanas de temporal en el mar Adriático sin perderse una sola vida humana.', 'Al encender una hoguera en la playa una víbora venenosa mordió su mano; al ver que no hinchaba ni moría, los nativos pensaron que era un dios.', 'Siglo I d.C.', 'Anchor', 'medio'),
  ('b-incendio-roma-neron', 'biblia', 'Gran Incendio de Roma y persecución de Nerón', 64, 'El emperador romano culpó falsamente a los cristianos del incendio de la ciudad, desatando la primera gran persecución imperial donde murieron Pedro y Pablo.', 'Según la tradición antigua, Pedro pidió ser crucificado cabeza abajo por no considerarse digno de morir igual que su Maestro.', 'Siglo I d.C.', 'Flame', 'medio'),
  ('b-destruccion-segundo-templo', 'biblia', 'Destrucción del Segundo Templo por las legiones de Tito', 70, 'Cumpliendo la profecía de Jesús (''no quedará piedra sobre piedra que no sea derribada''), las legiones romanas incendiaron y arrasaron el santuario de Jerusalén.', 'El Muro de los Lamentos es el único vestigio del muro de contención exterior de la explanada del templo que permanece en pie hoy.', 'Siglo I d.C.', 'Building', 'medio'),
  ('b-canon-biblico', 'biblia', 'Delimitación formal del canon bíblico del Tanaj', 90, 'Fijación y preservación rigurosa de los 24 libros canónicos hebreos de la Ley, los Profetas y los Escritos tras la caída del Templo.', 'Confirmaron la sacralidad de textos discutidos como Cantar de los Cantares y Eclesiastés al comprobar que inspiraban las manos a santidad.', 'Siglo I d.C.', 'BookCheck', 'medio'),
  ('b-apocalipsis-patmos', 'biblia', 'Juan escribe el Apocalipsis en la isla de Patmos', 95, 'Exiliado en una pequeña isla del mar Egeo bajo la persecución del emperador Domiciano, el anciano apóstol recibió las revelaciones finales del regreso glorioso de Cristo.', 'Patmos era una isla prisión minera romana a la que eran desterrados los criminales y disidentes políticos.', 'Siglo I d.C.', 'BookOpen', 'medio'),
  ('c-rueda', 'ciencia', 'Invención de la rueda en Mesopotamia', -3500, 'Inicialmente creada como torno para modelar cerámica, pronto revolucionó el transporte terrestre, los molinos de grano y la ingeniería militar.', 'Las ruedas más antiguas encontradas no eran de radios, sino discos macizos de madera cortados de tres tablones unidos.', 'Siglo XXXV a.C.', 'Disc', 'medio'),
  ('c-escritura-cuneiforme', 'ciencia', 'Invención de la escritura cuneiforme en Mesopotamia', -3200, 'Primer sistema documentado de registro lingüístico humano mediante incisiones en forma de cuña sobre tabletas de barro húmedo.', 'Nació esencialmente con fines contables para inventariar sacos de cebada, cabezas de ganado y pagos tributarios en los templos.', 'Siglo XXXII a.C.', 'FileText', 'medio'),
  ('c-arquimedes-eureka', 'ciencia', 'Arquímedes descubre el principio de flotación', -250, 'Al sumergirse en una tina de baño observó que el agua derramada era proporcional al volumen de su cuerpo, saliendo desnudo por la calle gritando ''¡Eureka!'' (¡Lo encontré!).', 'El rey Hierón II le había encargado verificar si su corona era de oro puro o si el orfebre había mezclado plata sin fundir la corona.', 'Siglo III a.C.', 'Sparkles', 'medio'),
  ('c-papel-cailun', 'ciencia', 'Invención del papel flexible por Cai Lun en China', 105, 'Elaboró las primeras láminas delgadas triturando cortezas de morera, restos de cáñamo, trapos viejos y redes de pescar en agua.', 'La corte imperial china guardó el secreto técnico de fabricación durante más de seiscientos años hasta la batalla del río Talas.', 'Siglo II d.C.', 'Scroll', 'medio'),
  ('c-polvora-china', 'ciencia', 'Descubrimiento de la pólvora por alquimistas chinos', 850, 'Mezcla deflagrante de salitre, azufre y carbón vegetal descubierta mientras intentaban sintetizar el elixir de la inmortalidad.', 'Los textos taoístas tempranos alertaban a los practicantes que la mezcla quemaba barbas y reducía a cenizas los talleres experimentales.', 'Siglo IX d.C.', 'Flame', 'medio'),
  ('c-optica-alhazen', 'ciencia', 'Tratado de Óptica y método experimental de Alhacén', 1021, 'Demostró experimentalmente que la visión se produce porque los rayos de luz reflejados penetran en el ojo, fundando la óptica moderna.', 'Desarrolló la cámara oscura y es considerado por los historiadores como el verdadero padre del método científico experimental riguroso.', 'Siglo XI d.C.', 'Eye', 'medio'),
  ('c-brujula-china', 'ciencia', 'Invención de la brújula magnética para navegación', 1044, 'El aprovechamiento de agujas de hierro magnetizado flotantes transformó la orientación de los buques en altamar sin depender de las estrellas.', 'En sus inicios en China las primeras brújulas tenían forma de cucharas de magnetita orientadas hacia el sur con propósitos geománticos.', 'Siglo XI d.C.', 'Compass', 'medio'),
  ('c-imprenta-gutenberg', 'ciencia', 'Gutenberg perfecciona la imprenta de tipos móviles', 1440, 'Creó tipos individuales fundidos en aleación metálica reutilizable y una prensa de madera de uvas, permitiendo reproducir libros en serie velozmente.', 'La Biblia de Gutenberg de 42 líneas fue su obra maestra: imprimió unos 180 ejemplares, de los cuales sobreviven solo 49 en todo el mundo.', 'Siglo XV d.C.', 'BookOpen', 'medio'),
  ('c-copernico-heliocentrico', 'ciencia', 'Copérnico publica la teoría heliocéntrica', 1543, 'En ''De revolutionibus orbium coelestium'' demostró matemáticamente que el Sol, y no la Tierra, es el centro del sistema planetario.', 'Copérnico vio la primera copia impresa de su libro en su lecho de muerte, el mismo día en que falleció.', 'Siglo XVI d.C.', 'Sun', 'medio'),
  ('c-anatomia-vesalio', 'ciencia', 'Publicación de ''De humani corporis fabrica'' de Vesalio', 1543, 'Cimbró la medicina renacentista corrigiendo cientos de errores milenarios de Galeno mediante disecciones directas del cuerpo humano.', 'Las magistrales planchas grabadas en madera que ilustraban músculos y huesos fueron ejecutadas por artistas del taller del pintor Tiziano.', 'Siglo XVI d.C.', 'HeartPulse', 'medio'),
  ('c-telescopio-galileo', 'ciencia', 'Galileo Galilei apunta su telescopio al cielo', 1609, 'Descubrió los cráteres lunares, las cuatro lunas mayores de Júpiter y las fases de Venus, derribando para siempre la física aristotélica geocéntrica.', 'Galileo pulía a mano sus propias lentes de cristal en Venecia logrando hasta 30 aumentos, muy superior a los catalejos holandeses.', 'Siglo XVII d.C.', 'Eye', 'medio'),
  ('c-microscopio-leeuwenhoek', 'ciencia', 'Descubrimiento de los microbios por Leeuwenhoek', 1674, 'Comerciante de telas holandés que pulió lentes microscópicas diminutas observando por primera vez bacterias y protozoos vivos.', 'Llamó a estos microorganismos ''animálculos'' y los descubrió examinando gotas de agua estancada y el sarro de su propia boca.', 'Siglo XVII d.C.', 'Microscope', 'medio'),
  ('c-newton-principia', 'ciencia', 'Newton publica los ''Principia Mathematica''', 1687, 'Formuló las tres leyes del movimiento universal y la Ley de la Gravitación Universal, unificando la mecánica celeste y terrestre en una sola física.', 'El astrónomo Edmond Halley financió de su propio bolsillo la impresión del libro porque la Royal Society se había quedado sin fondos.', 'Siglo XVII d.C.', 'Atom', 'medio'),
  ('c-ley-gravedad-manzana', 'ciencia', 'Formulación de la Ley de Gravitación Universal de Newton', 1687, 'Demostró matemáticamente en los ''Principia'' que la misma fuerza que hace caer una fruta mantiene a la Luna en su órbita alrededor de la Tierra.', 'Newton confirmó en persona a su biógrafo William Stukeley que la idea le asaltó mientras meditaba en el jardín bajo un manzano en Woolsthorpe.', 'Siglo XVII d.C.', 'Apple', 'medio'),
  ('c-maquina-vapor', 'ciencia', 'James Watt patenta la máquina de vapor moderna', 1769, 'Añadió un condensador separado que redujo el consumo de carbón en un 75%, multiplicando la potencia mecánica y desatando la Revolución Industrial.', 'Para convencer a los mineros de comprar su máquina, inventó la unidad de medida ''caballo de fuerza'' (horsepower) comparándola con los animales.', 'Siglo XVIII d.C.', 'Cpu', 'medio'),
  ('c-oxigeno-lavoisier', 'ciencia', 'Descubrimiento del oxígeno y conservación de la masa', 1777, 'Sentó las bases de la química moderna refutando el flogisto con su ley: ''En la naturaleza nada se crea, nada se destruye, todo se transforma''.', 'Su esposa Marie-Anne no solo traducía los artículos científicos del inglés sino que dibujaba a mano con minucia todos los matraces del laboratorio.', 'Siglo XVIII d.C.', 'Beaker', 'medio'),
  ('c-vacuna-jenner', 'ciencia', 'Edward Jenner crea la primera vacuna (contra la viruela)', 1796, 'Inoculó a un niño con fluido de viruela bovina de una lechera y demostró que quedaba inmune a la mortal viruela humana, fundando la inmunología.', 'La palabra ''vacuna'' proviene precisamente del latín ''vaccinus'' (relativo a las vacas).', 'Siglo XVIII d.C.', 'ShieldPlus', 'medio'),
  ('c-pila-volta', 'ciencia', 'Alessandro Volta inventa la primera pila eléctrica química', 1800, 'Apiló discos alternados de cobre y zinc separados por cartón empapado en salmuera, produciendo la primera corriente eléctrica continua de la historia.', 'Napoleón Bonaparte quedó tan maravillado con la demostración que nombró conde y senador del reino a Volta.', 'Siglo XIX d.C.', 'BatteryCharging', 'medio'),
  ('c-darwin-especies', 'ciencia', 'Darwin publica ''El Origen de las Especies''', 1859, 'Planteó que todas las formas de vida descienden de antepasados comunes mediante el mecanismo biológico de la selección natural.', 'Los primeros 1.250 ejemplares impresos de la primera edición se agotaron por completo en el primer día de venta.', 'Siglo XIX d.C.', 'TreePine', 'medio'),
  ('c-teoria-germenes-pasteur', 'ciencia', 'Teoría microbiana y pasteurización por Louis Pasteur', 1862, 'Demostró que las fermentaciones y dolencias infecciosas provienen de microorganismos vivos, refutando la generación espontánea.', 'Demostró su tesis empleando matraces de cuello de cisne que permitían el flujo de aire pero impedían la entrada de partículas de polvo.', 'Siglo XIX d.C.', 'ShieldAlert', 'medio'),
  ('c-tabla-periodica-mendeleiev', 'ciencia', 'Creación de la Tabla Periódica de los Elementos', 1869, 'Organizó los elementos químicos según sus masas atómicas y propiedades periódicas dejando huecos para elementos aún no descubiertos.', 'Predijo con exactitud matemática pasmosa las características del galio y el germanio antes de que nadie los hubiera visto o aislado.', 'Siglo XIX d.C.', 'Grid', 'medio'),
  ('c-telefono-bell', 'ciencia', 'Alexander Graham Bell patenta el teléfono', 1876, 'Transmitió la voz humana a través de un cable eléctrico con la histórica frase: ''Señor Watson, venga aquí, lo necesito''.', 'Bell presentó su solicitud de patente en la oficina de Washington solo dos horas antes que su rival Elisha Gray.', 'Siglo XIX d.C.', 'Phone', 'medio'),
  ('c-bombilla-edison', 'ciencia', 'Edison patenta la bombilla incandescente duradera', 1879, 'Tras probar más de 6.000 materiales distintos, logró que un filamento de bambú carbonizado brillara más de 1.200 horas continuas en el vacío.', 'Edison decía: ''No he fracasado; he encontrado diez mil formas que no funcionan''.', 'Siglo XIX d.C.', 'Lightbulb', 'medio'),
  ('c-electricidad-foco-tesla', 'ciencia', 'Patente del motor de corriente alterna por Nikola Tesla', 1888, 'Desarrolló el motor de inducción y el sistema de corriente alterna polifásico que electrificó las ciudades y fábricas del planeta entero.', 'Su sistema derrotó comercialmente a la corriente continua de Edison al iluminar de forma espectacular la Exposición Universal de Chicago en 1893.', 'Siglo XIX d.C.', 'Zap', 'medio'),
  ('c-cinematografo-edison-kinetoscopio', 'ciencia', 'Patente del Kinetoscopio por Thomas Edison', 1891, 'Primer dispositivo individual para contemplar imágenes en movimiento continuo mediante una película de celuloide perforada.', 'Edison creía que el cine era un entretenimiento individual y no apostó inicialmente por proyectarlo en pantallas frente a salas colectivas.', 'Siglo XIX d.C.', 'Film', 'medio'),
  ('c-rayos-x', 'ciencia', 'Wilhelm Röntgen descubre los Rayos X', 1895, 'Observó una radiación invisible capaz de atravesar papel negro y cartón; tomó la primera radiografía médica de la mano de su esposa Anna Bertha.', 'Al ver la imagen de los huesos de su mano con el anillo de bodas, su esposa exclamó horrorizada: ''¡He visto mi propia muerte!''.', 'Siglo XIX d.C.', 'Camera', 'medio')
INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('c-aspirina-hoffmann', 'ciencia', 'Síntesis del ácido acetilsalicílico (Aspirina)', 1897, 'Sintetizó una variante química pura del principio de la corteza de sauce para mitigar el dolor reumático crónico de su propio padre.', 'Es el analgésico sintético más producido en la historia de la medicina humana con miles de millones de comprimidos consumidos anualmente.', 'Siglo XIX d.C.', 'Pill', 'medio'),
  ('c-radioactividad-curie', 'ciencia', 'Marie Curie y Pierre Curie descubren el Radio y el Polonio', 1898, 'Aislaron elementos químicos altamente radiactivos a partir de toneladas de pechblenda en un cobertizo precario de París.', 'Marie Curie fue la primera mujer en ganar un Premio Nobel y la única persona en la historia en ganarlo en dos disciplinas científicas distintas (Física y Química).', 'Siglo XIX d.C.', 'Activity', 'medio'),
  ('c-grupo-sanguineo-landsteiner', 'ciencia', 'Identificación de los grupos sanguíneos humanos ABO', 1901, 'Descubrió que la sangre humana posee tipos antigénicos incompatibles, posibilitando las transfusiones seguras que salvan millones de vidas.', 'Recibió el Premio Nobel de Medicina en 1930 y el 14 de junio, fecha de su nacimiento, se celebra el Día Mundial del Donante de Sangre.', 'Siglo XX d.C.', 'Droplet', 'medio'),
  ('c-hermanos-wright', 'ciencia', 'Primer vuelo a motor controlado de los Hermanos Wright', 1903, 'En las dunas de Kitty Hawk (Carolina del Norte), el biplano Flyer voló durante 12 segundos recorriendo 36 metros de distancia en el aire.', 'Eran fabricantes y reparadores de bicicletas; financiaron todo el desarrollo aeronáutico con las ganancias de su taller.', 'Siglo XX d.C.', 'Plane', 'medio'),
  ('c-relatividad-einstein', 'ciencia', 'Einstein publica la Teoría de la Relatividad Especial', 1905, 'Demostró que el tiempo y el espacio son relativos a la velocidad del observador y que la masa y la energía son equivalentes (E = mc²).', 'En ese mismo año 1905, trabajando como examinador de tercera clase en una oficina de patentes, publicó cuatro artículos revolucionarios.', 'Siglo XX d.C.', 'Zap', 'medio'),
  ('c-deriva-continental-wegener', 'ciencia', 'Propuesta de la Deriva Continental y Pangea', 1912, 'Postuló que los continentes actuales formaban un supercontinente primitivo que se fracturó desplazándose sobre el manto terrestre.', 'La comunidad geológica de su tiempo lo tildó de loco hasta que la tectónica de placas submarina de los años 60 corroboró plenamente su modelo.', 'Siglo XX d.C.', 'Globe', 'medio'),
  ('c-modelo-atomico-bohr', 'ciencia', 'Presentación del modelo atómico cuántico de Bohr', 1913, 'Propuso que los electrones orbitan el núcleo atómico en niveles de energía discretos emitiendo fotones de luz al saltar entre órbitas.', 'Su formulación mereció el Nobel en 1922; cuando fue ennoblecido eligió para su blasón el símbolo del Yin y el Yang con el lema ''Los opuestos se complementan''.', 'Siglo XX d.C.', 'Atom', 'medio'),
  ('c-insulina-banting-best', 'ciencia', 'Descubrimiento y extracción de la insulina médica', 1921, 'Aislaron con éxito la hormona pancreática transformando la diabetes tipo 1 de un diagnóstico mortal e irreversible en una patología tratable.', 'Vendieron la patente farmacéutica de la insulina a la Universidad de Toronto por la simbólica cifra de 1 dólar para no lucrar con la salud pública.', 'Siglo XX d.C.', 'Activity', 'medio'),
  ('c-mecanica-cuantica-heisenberg', 'ciencia', 'Enunciado del Principio de Incertidumbre cuántica', 1927, 'Determinó que es físicamente imposible conocer al mismo tiempo y con precisión infinita la posición y la velocidad de una partícula subatómica.', 'El propio acto de observar e iluminar una partícula con un fotón altera irremediablemente su trayectoria original.', 'Siglo XX d.C.', 'HelpCircle', 'medio'),
  ('c-penicilina-fleming', 'ciencia', 'Alexander Fleming descubre la penicilina', 1928, 'Notó que una placa de cultivo olvidada con estafilococos había sido invadida por un hongo verde que destruyó todas las bacterias a su alrededor.', 'El hallazgo inauguró la era de los antibióticos y ha salvado más de 200 millones de vidas de infecciones mortales.', 'Siglo XX d.C.', 'FlaskConical', 'medio'),
  ('c-expansion-universo-hubble', 'ciencia', 'Descubrimiento de la expansión cósmica del Universo', 1929, 'Comprobó observando el corrimiento al rojo de las galaxias que el cosmos no es estático sino que se expande a velocidades proporcionales a su distancia.', 'Al enterarse del hallazgo de Hubble, Albert Einstein retiró su constante cosmológica admitiendo que había sido el mayor error de su carrera.', 'Siglo XX d.C.', 'Telescope', 'medio'),
  ('c-radar-watson-watt', 'ciencia', 'Invención y despliegue del radar defensivo', 1935, 'Sistema pionero de detección y telemetría por radio que alertaba de aviones enemigos antes de que fueran visibles a simple vista.', 'Fue el escudo tecnológico que permitió a la Real Fuerza Aérea británica vencer a la Luftwaffe en la crucial Batalla de Inglaterra.', 'Siglo XX d.C.', 'Radio', 'medio'),
  ('c-fision-nuclear-meitner-hahn', 'ciencia', 'Descubrimiento de la fisión nuclear del uranio', 1938, 'Comprobaron que bombardear núcleos pesados de uranio con neutrones los divide liberando descomunales cantidades de energía nuclear.', 'Lise Meitner aportó la interpretación teórica matemática crucial en su exilio sueco pero fue omitida deliberadamente del Premio Nobel otorgado a Hahn.', 'Siglo XX d.C.', 'Radioactive', 'medio'),
  ('c-turing-enigma', 'ciencia', 'Alan Turing descifra la máquina Enigma en Bletchley Park', 1940, 'Diseñaron las computadoras electromecánicas ''Bombe'' que descifraron las comunicaciones militares secretas nazis salvando millones de vidas.', 'Los principios matemáticos que ideó Turing en ese período constituyeron los pilares fundacionales de la ciencia de la computación contemporánea.', 'Siglo XX d.C.', 'Cpu', 'medio'),
  ('c-primer-computador-eniac', 'ciencia', 'Presentación de ENIAC, primer computador electrónico', 1945, 'Coloso de 30 toneladas con 17.000 válvulas de vacío programable para calcular trayectorias de artillería en milésimas de segundo.', 'El equipo original de pioneras que programaba manualmente sus circuitos conectando clavijas y cables estuvo compuesto por seis brillantes matemáticas.', 'Siglo XX d.C.', 'Server', 'medio'),
  ('c-transistor', 'ciencia', 'Invención del transistor en Bell Labs', 1947, 'Reemplazó a las voluminosas válvulas de vacío con semiconductores de silicio y germanio, permitiendo la miniaturización de toda la computación moderna.', 'Sin el transistor no existirían los microprocesadores, los celulares, las computadoras personales ni Internet.', 'Siglo XX d.C.', 'Cpu', 'medio'),
  ('c-adn-watson-crick', 'ciencia', 'Descubrimiento de la doble hélice del ADN', 1953, 'Descifraron la estructura molecular helicoidal que almacena y replica todo el código genético de los seres vivos en Cambridge.', 'La fotografía 51 tomada por Rosalind Franklin mediante difracción de rayos X fue la prueba decisiva para deducir la doble hélice.', 'Siglo XX d.C.', 'Dna', 'medio'),
  ('c-vacuna-polio-salk', 'ciencia', 'Desarrollo de la vacuna contra la poliomielitis', 1953, 'Inmunización con virus inactivado que frenó el flagelo que paralizaba a decenas de miles de niños anualmente en todo el planeta.', 'Al ser consultado en televisión sobre quién poseía la patente legal de su cura, Salk replicó: ''La gente, no hay patente. ¿Se podría patentar el Sol?''.', 'Siglo XX d.C.', 'ShieldCheck', 'medio'),
  ('c-sputnik', 'ciencia', 'Lanzamiento del Sputnik 1 al espacio', 1957, 'La Unión Soviética puso en órbita el primer satélite artificial de la historia, una esfera metálica de 83 kg con cuatro antenas que emitía ''bips''.', 'El sonido de sus señales radiales podía ser sintonizado por radioaficionados de todo el mundo al pasar sobre sus cabezas cada 96 minutos.', 'Siglo XX d.C.', 'Radio', 'medio'),
  ('c-rayo-laser-maiman', 'ciencia', 'Creación del primer rayo láser funcional', 1960, 'Hizo emitir por primera vez un haz de luz coherente y monocromática concentrada estimulando un cristal cilíndrico de rubí sintético.', 'La prensa lo bautizó inicialmente con sorna como ''una solución que busca un problema''; hoy es el corazón de las telecomunicaciones por fibra óptica.', 'Siglo XX d.C.', 'Zap', 'medio'),
  ('c-apolo-11', 'ciencia', 'Neil Armstrong pisa la Luna en el Apolo 11', 1969, 'El módulo lunar Eagle alunizó en el Mar de la Tranquilidad ante la mirada de 650 millones de personas por televisión en todo el mundo.', 'La computadora de navegación del Apolo 11 tenía solo 4 KB de RAM y funcionaba con memoria de núcleos magnéticos cosida a mano.', 'Siglo XX d.C.', 'Moon', 'medio'),
  ('c-arpanet', 'ciencia', 'Primer mensaje transmitido por ARPANET (Nacimiento de Internet)', 1969, 'Investigadores de UCLA intentaron enviar la palabra ''LOGIN'' a la Universidad de Stanford; el sistema colapsó en la letra G, transmitiendo solo ''LO''.', 'Ese humilde ''LO'' fue el primer mensaje jamás enviado a través de la red de conmutación de paquetes antecesora de Internet.', 'Siglo XX d.C.', 'Network', 'medio'),
  ('c-microprocesador-intel-4004', 'ciencia', 'Lanzamiento del Intel 4004, primer microprocesador', 1971, 'El cerebro informático completo integrado en una sola pastilla de silicio con 2.300 transistores que detonó la revolución de los microcomputadores.', 'Tenía la misma potencia de cálculo que el ENIAC de 30 toneladas pero cabía holgadamente sobre la yema de un dedo humano.', 'Siglo XX d.C.', 'Cpu', 'medio'),
  ('c-voyager-lanzamiento', 'ciencia', 'Lanzamiento de las sondas interestelares Voyager 1 y 2', 1977, 'Zarparon para explorar Júpiter, Saturno, Urano y Neptuno; hoy en día viajan por el espacio interestelar llevando el Disco de Oro de la Tierra.', 'El Voyager 1 es el objeto humano más lejano de la Tierra, situado a más de 24.000 millones de kilómetros de distancia.', 'Siglo XX d.C.', 'Compass', 'medio'),
  ('c-ibm-pc', 'ciencia', 'Lanzamiento del primer IBM PC 5150', 1981, 'IBM estandarizó la arquitectura de computadoras personales para hogares y oficinas con el sistema operativo MS-DOS de Microsoft.', 'Venía con 16 KB de memoria RAM básica y una pantalla fósforo verde sin disco duro (usaba disquetes de 5,25 pulgadas).', 'Siglo XX d.C.', 'Monitor', 'medio'),
  ('c-www-berners-lee', 'ciencia', 'Tim Berners-Lee crea la World Wide Web en el CERN', 1989, 'Inventó los protocolos HTTP, el lenguaje HTML y las direcciones URL para compartir documentos hipertexto científicos a través de Internet.', 'El primer servidor web del mundo corría en la computadora NeXT de Berners-Lee, que tenía una pegatina manuscrita: ''¡Esta máquina es un servidor, NO APAGAR!''.', 'Siglo XX d.C.', 'Globe', 'medio'),
  ('c-hubble', 'ciencia', 'Puesta en órbita del Telescopio Espacial Hubble', 1990, 'El transbordador Discovery colocó en órbita sobre la atmósfera terrestre el observatorio que ha tomado las imágenes más profundas del cosmos.', 'Al principio tenía una aberración esférica milimétrica en su espejo primario que hacía fotos borrosas; fue corregido en el espacio en 1993 como si le pusieran anteojos.', 'Siglo XX d.C.', 'Telescope', 'medio'),
  ('c-dolly', 'ciencia', 'Nacimiento de la oveja Dolly (primer mamífero clonado)', 1996, 'Científicos del Instituto Roslin en Escocia lograron clonar un mamífero a partir de una célula somática adulta diferenciada de glándula mamaria.', 'El equipo bautizó a la oveja ''Dolly'' en honor a la cantante de country Dolly Parton.', 'Siglo XX d.C.', 'Sparkles', 'medio'),
  ('c-genoma-humano', 'ciencia', 'Completación del Proyecto Genoma Humano', 2003, 'Un consorcio internacional descifró el 99% del mapa de los 3.000 millones de pares de bases químicas que componen el código genético humano.', 'Se descubrió que los seres humanos compartimos más del 99,9% de nuestro código genético entre nosotros independientemente de la etnia.', 'Siglo XXI d.C.', 'Dna', 'medio'),
  ('c-iphone', 'ciencia', 'Steve Jobs presenta el primer iPhone', 2007, 'Fusionó un teléfono móvil, un iPod con pantalla ancha y un navegador de Internet multitáctil en un solo dispositivo de cristal sin teclado físico.', 'Durante la presentación en vivo en San Francisco, el prototipo tenía tantos errores de memoria que Jobs tuvo que seguir una secuencia estricta para que no se apagara.', 'Siglo XXI d.C.', 'Smartphone', 'medio'),
  ('c-boson-higgs', 'ciencia', 'Descubrimiento del Bosón de Higgs en el CERN', 2012, 'El Gran Colisionador de Hadrones (LHC) confirmó la partícula del campo de Higgs responsable de otorgar masa a todas las partículas elementales del universo.', 'El físico Peter Higgs de 83 años lloró de emoción en el auditorio del CERN al ver confirmada experimentalmente su teoría planteada 48 años antes.', 'Siglo XXI d.C.', 'Atom', 'medio'),
  ('c-crispr-doudna-charpentier', 'ciencia', 'Invención del editor genético CRISPR-Cas9', 2012, 'Herramienta de tijeras moleculares de alta precisión capaz de cortar y corregir secuencias de ADN en células vivas de cualquier especie.', 'Ambas investigadoras recibieron el Premio Nobel de Química en 2020, constituyendo la primera dupla enteramente femenina en recibirlo conjuntamente.', 'Siglo XXI d.C.', 'Dna', 'medio'),
  ('c-ondas-gravitacionales-ligo', 'ciencia', 'Primera detección directa de ondas gravitacionales', 2015, 'Captación con interferómetros láser de ondulaciones del tejido espaciotemporal causadas por la colisión de dos agujeros negros.', 'El choque estelar ocurrió hace 1.300 millones de años y la distorsión detectada en los brazos de LIGO fue una fracción del diámetro de un protón.', 'Siglo XXI d.C.', 'Radio', 'medio'),
  ('c-agujero-negro-foto', 'ciencia', 'Primera fotografía real de un agujero negro (EHT)', 2019, 'Ocho radiotelescopios sincronizados con relojes atómicos combinaron sus señales para captar la sombra del horizonte de sucesos en la galaxia M87.', 'La cantidad de datos generada fue tan descomunal (5 petabytes) que no se pudo transmitir por Internet; tuvieron que enviar los discos duros en avión.', 'Siglo XXI d.C.', 'Eye', 'medio'),
  ('c-james-webb-espacio', 'ciencia', 'Puesta en órbita del Telescopio Espacial James Webb', 2021, 'El observatorio espacial infrarrojo más potente desplegó su espejo segmentado de oro a 1,5 millones de kilómetros de la Tierra en el punto L2.', 'Su parasol térmico de cinco capas mide como una pista de tenis y mantiene los sensores a -233 grados Celsius para captar las primeras galaxias del cosmos.', 'Siglo XXI d.C.', 'Telescope', 'medio'),
  ('c-chatgpt-ia', 'ciencia', 'Lanzamiento público de ChatGPT y auge de la IA Generativa', 2022, 'OpenAI abrió al público su modelo conversacional basado en transformadores LLM, alcanzando 100 millones de usuarios en solo dos meses.', 'Fue la aplicación de consumo masivo con el crecimiento más veloz de la historia de la tecnología hasta ese momento.', 'Siglo XXI d.C.', 'Brain', 'medio'),
  ('m-epitafio-seikilos', 'musica', 'Inscripción del Epitafio de Sícilo', 100, 'La composición musical completa más antigua con melodía, letra y notación preservada intacta sobre una estela funeraria de mármol.', 'El poema lírico grabado aconseja: ''Mientras vivas, resplandece; no te aflijas por nada en demasía, la vida es ciertamente breve''.', 'Siglo I d.C.', 'Music', 'medio'),
  ('m-canto-gregoriano', 'musica', 'Compilación y unificación del Canto Gregoriano', 600, 'Canto monódico litúrgico a capela en latín que instituyó los primeros modos musicales y las raíces armónicas de Occidente.', 'Se anotaba en pergaminos monacales mediante ''neumas'', pequeños signos gráficos que indicaban el ascenso o descenso tonal de la voz.', 'Siglo VII d.C.', 'BookOpen', 'medio'),
  ('m-guido-arezzo-notas', 'musica', 'Invención del pentagrama y nombres de las notas', 1025, 'Ideó el pentagrama con líneas y nombró las notas (Ut, Re, Mi, Fa, Sol, La) tomando las sílabas iniciales del Himno a San Juan Bautista.', 'Siglos más tarde la primera sílaba ''Ut'' fue reemplazada por ''Do'' (derivado de Dominus) por resultar infinitamente más fácil de entonar.', 'Siglo XI d.C.', 'Music', 'medio'),
  ('m-mona-lisa', 'musica', 'Leonardo da Vinci comienza a pintar la Mona Lisa', 1503, 'Inició el retrato en Florencia empleando su técnica revolucionaria de ''sfumato'' para difuminar contornos y crear su enigmática sonrisa.', 'Leonardo nunca entregó el cuadro a su cliente y lo llevó consigo a Francia hasta el final de sus días.', 'Siglo XVI d.C.', 'Palette', 'medio'),
  ('m-capilla-sixtina', 'musica', 'Miguel Ángel culmina la bóveda de la Capilla Sixtina', 1512, 'Pintó más de 300 figuras colosales al fresco en el techo del Vaticano, incluyendo la célebre escena de ''La Creación de Adán''.', 'Pintó de pie mirando hacia arriba durante cuatro años en andamios especiales, causándole problemas crónicos en la vista y cuello.', 'Siglo XVI d.C.', 'Brush', 'medio'),
  ('m-monteverdi-orfeo', 'musica', 'Estreno de ''L''Orfeo'' de Claudio Monteverdi', 1607, 'Considerada por los musicólogos como la primera obra maestra definitiva del género operístico lírico y dramático.', 'Monteverdi dispuso una plantilla instrumental de más de 40 músicos asignando timbres específicos para contrastar el inframundo con el mundo terrenal.', 'Siglo XVII d.C.', 'Theater', 'medio'),
  ('m-piano-cristofori', 'musica', 'Invención del Piano por Bartolomeo Cristofori', 1700, 'En Florencia, creó un instrumento de teclado con macillos que podía sonar suave (''piano'') o fuerte (''forte'') según la fuerza del dedo.', 'Su nombre original completo era ''Gravicembalo col piano e forte'' (Clavecín con suave y fuerte).', 'Siglo XVIII d.C.', 'Music', 'medio'),
  ('m-bach-tocata-fuga', 'musica', 'Composición de la ''Tocata y Fuga en re menor'' de Bach', 1708, 'La pieza para órgano eclesiástico más célebre, electrizante y dramática de toda la historia musical europea.', 'Su fanfarria inicial penetró tan hondo en la cultura popular que se convirtió en la banda sonora arquetípica del cine de mansiones góticas y terror.', 'Siglo XVIII d.C.', 'Speaker', 'medio'),
  ('m-bach-conciertos-brandeburgo', 'musica', 'Composición de los Conciertos de Brandeburgo por Bach', 1721, 'Cénit del concierto barroco instrumental con combinaciones orquestales audaces y una polifonía de contrapunto inigualada.', 'Bach dedicó la partitura manuscrita al margrave de Brandeburgo, quien jamás pagó por ella ni contó con orquesta capaz de interpretarla.', 'Siglo XVIII d.C.', 'Music', 'medio'),
  ('m-cuatro-estaciones-vivaldi', 'musica', 'Antonio Vivaldi publica ''Las Cuatro Estaciones''', 1725, 'El sacerdote pelirrojo veneciano compuso cuatro conciertos para violín que imitaban truenos, pájaros, arroyos y el hielo crujiente del invierno.', 'Fue una de las primeras obras de ''música descriptiva'' de la historia: Vivaldi incluyó sonetos poéticos explicando qué paisaje sonaba en cada compás.', 'Siglo XVIII d.C.', 'CloudRain', 'medio'),
  ('m-mesias-handel', 'musica', 'Estreno del oratorio ''El Mesías'' de Händel', 1742, 'Compuso la monumental obra sacra en Dublín en solo 24 días, culminando con el universalmente entonado coro del ''Aleluya''.', 'En el estreno de Londres, el rey Jorge II quedó tan sobrecogido por el Aleluya que se puso de pie espontáneamente, tradición que el público sigue imitando hoy.', 'Siglo XVIII d.C.', 'Sparkles', 'medio'),
  ('m-flauta-magica-mozart', 'musica', 'Mozart estrena la ópera ''La Flauta Mágica''', 1791, 'Un cuento de hadas alegórico con el aria imposible de la ''Reina de la Noche'', estrenado en Viena apenas dos meses antes de la prematura muerte del compositor.', 'Mozart la escribió para un teatro popular de barrio y él mismo dirigió la orquesta la noche del estreno.', 'Siglo XVIII d.C.', 'Music', 'medio'),
  ('m-clarinete-mozart', 'musica', 'Concierto para clarinete en La mayor de Mozart', 1791, 'Una de las últimas y más luminosas creaciones completadas por Mozart escasas semanas antes de su prematuro deceso a los 35 años.', 'La compuso exclusivamente para el clarinete di bassetto ideado por su entrañable amigo virtuoso Anton Stadler.', 'Siglo XVIII d.C.', 'Music', 'medio'),
  ('m-novena-beethoven', 'musica', 'Estreno de la Novena Sinfonía de Beethoven en Viena', 1824, 'Completamente sordo, Beethoven revolucionó la historia de la música incorporando cantantes solistas y coro con el ''Himno a la Alegría''.', 'Al finalizar el concierto, la solista Caroline Unger tuvo que girarlo suavemente hacia el público para que pudiera ver los aplausos que no podía oír.', 'Siglo XIX d.C.', 'Volume2', 'medio')
INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('m-chopin-nocturnos', 'musica', 'Publicación de los célebres Nocturnos de Frédéric Chopin', 1832, 'Elevó la miniatura pianística a la máxima cima de la poesía romántica con su lirismo de ensueño y melancolía polaca.', 'Chopin repudiaba los teatros multitudinarios y prefería interpretar sus nocturnos en pequeños salones bohemios a la tenue luz de las velas.', 'Siglo XIX d.C.', 'Piano', 'medio'),
  ('m-carmen-bizet', 'musica', 'Estreno de la ópera ''Carmen'' de Georges Bizet en París', 1875, 'Obra maestra de la ópera realista ambientada en Sevilla inmortalizada por temas como la ''Habanera'' y la ''Canción del toreador''.', 'En su velada de estreno fue censurada por escandalosa y Bizet falleció desconsolado a los tres meses ignorando que sería un triunfo inmortal.', 'Siglo XIX d.C.', 'Sparkles', 'medio'),
  ('m-tchaikovsky-lago-cisnes', 'musica', 'Estreno de ''El Lago de los Cisnes'' de Chaikovski', 1877, 'La obra sinfónica de ballet clásico más representada y aclamada con la legendaria dualidad de los cisnes Odette y Odile.', 'Los bailarines del Teatro Bolshói de Moscú protestaron en su estreno porque la orquestación les parecía excesivamente ruidosa y compleja de seguir.', 'Siglo XIX d.C.', 'Crown', 'medio'),
  ('m-noche-estrellada', 'musica', 'Vincent van Gogh pinta ''La Noche Estrellada''', 1889, 'Desde su ventana del sanatorio de Saint-Rémy en el sur de Francia, plasmó el cielo nocturno arremolinado con pinceladas enérgicas y cipreses.', 'Van Gogh solo vendió un cuadro en toda su vida (''El viñedo rojo''), viviendo en extrema pobreza asistido por su hermano Theo.', 'Siglo XIX d.C.', 'Star', 'medio'),
  ('m-debussy-claro-luna', 'musica', 'Composición de ''Claro de Luna'' por Claude Debussy', 1890, 'Pieza clave del impresionismo para piano inspirada en los versos del poeta Paul Verlaine con armonías sutiles y evocadoras.', 'Debussy demoró quince años en dar por concluida la revisión de la Suite Bergamasque antes de autorizar su publicación comercial en 1905.', 'Siglo XIX d.C.', 'Moon', 'medio'),
  ('m-scott-joplin-ragtime', 'musica', 'Publicación de ''Maple Leaf Rag'' por Scott Joplin', 1899, 'El primer éxito masivo de partituras afroamericanas con ritmo sincopado que vendió más de un millón de copias.', 'Joplin se ganó el título de ''El Rey del Ragtime'' y sus síncopas pianísticas abrieron las puertas de par en par a la gestación del Jazz.', 'Siglo XIX d.C.', 'Music', 'medio'),
  ('m-consagracion-stravinsky', 'musica', 'Estreno de ''La Consagración de la Primavera'' de Stravinsky', 1913, 'Sus ritmos salvajes e instrumentación atonal provocaron una célebre batalla campal de puñetazos e insultos en el Teatro de los Campos Elíseos de París.', 'La música era tan radicalmente moderna que los bailarines no podían oír el compás por los gritos del público enfurecido.', 'Siglo XX d.C.', 'Flame', 'medio'),
  ('m-carlos-gardel-tango', 'musica', 'Carlos Gardel graba ''Mi noche triste'' y funda el tango canción', 1917, 'Transformó el tango de ser una música arrabalera bailable en un conmovedor género lírico-poético que conquistó el mundo.', 'La inconfundible voz de Gardel (''El Zorzal Criollo'') fue declarada Patrimonio Cultural e Histórico de la Humanidad por la UNESCO.', 'Siglo XX d.C.', 'Mic', 'medio'),
  ('m-george-gershwin-rhapsody-in-blue', 'musica', 'Estreno de ''Rhapsody in Blue'' de George Gershwin', 1924, 'Fusión sinfónica cumbre entre el jazz de los clubes neoyorquinos y la alta tradición orquestal clásica europea.', 'El famoso glissando de clarinete que abre la pieza nació de una broma en un ensayo del músico Ross Gorman que a Gershwin le fascinó.', 'Siglo XX d.C.', 'Music', 'medio'),
  ('m-jazz-armstrong', 'musica', 'Louis Armstrong y la era dorada del Jazz', 1927, 'Con sus grabaciones de los ''Hot Five'' en Chicago, transformó el jazz de una improvisación colectiva a un arte solista virtuoso.', 'Popularizó el canto ''scat'' (vocalizaciones rítmicas con sílabas sin sentido) al caerse la partitura con la letra al suelo durante una grabación.', 'Siglo XX d.C.', 'Mic', 'medio'),
  ('m-robert-johnson-blues', 'musica', 'Grabaciones legendarias de blues de Robert Johnson', 1936, '29 temas grabados en una modesta habitación de hotel que cimentaron para siempre las bases del blues del Delta y el rock.', 'Su vertiginoso talento dio pie a la célebre leyenda de que pactó con el Diablo en un cruce de caminos en Clarksdale a medianoche.', 'Siglo XX d.C.', 'Guitar', 'medio'),
  ('m-guernica-picasso', 'musica', 'Pablo Picasso pinta ''El Guernica''', 1937, 'Enorme mural cubista en blanco, negro y gris como denuncia desgarradora del bombardeo nazi sobre la villa vasca de Guernica.', 'Cuando un oficial nazi vio una postal del cuadro y preguntó: ''¿Usted hizo esto?'', Picasso respondió secamente: ''No, lo hicieron ustedes''.', 'Siglo XX d.C.', 'Palette', 'medio'),
  ('m-billie-holiday-strange-fruit', 'musica', 'Billie Holiday graba el himno ''Strange Fruit''', 1939, 'Valiente canción protesta contra los linchamientos raciales en el sur de EE.UU. que sacudió la conciencia política de una época.', 'Su discográfica habitual se negó en redondo a editarla por miedo a represalias, teniéndola que grabar en un sello independiente clandestino.', 'Siglo XX d.C.', 'Mic', 'medio'),
  ('m-charlie-parker-bebop', 'musica', 'Revolución del Bebop por Charlie Parker y Dizzy Gillespie', 1945, 'Rompieron con las orquestas de baile comerciales acelerando los tempos con solos de armonía avanzada y virtuosismo deslumbrante.', 'Parker practicaba hasta catorce horas diarias en su adolescencia hasta poder tocar cualquier solo en los doce tonos musicales existentes.', 'Siglo XX d.C.', 'Music', 'medio'),
  ('m-muddy-waters-electric-blues', 'musica', 'Muddy Waters electrifica el Blues de Chicago', 1950, 'Conectó su guitarra al amplificador en los clubes de Chicago, transformando el blues rural en el sonido crudo que engendró el rock.', 'Bandas británicas icónicas como The Rolling Stones y Led Zeppelin bautizaron sus grupos o compusieron canciones inspiradas directamente en él.', 'Siglo XX d.C.', 'Zap', 'medio'),
  ('m-elvis-rock', 'musica', 'Elvis Presley desata la locura del Rock and Roll', 1956, 'Con ''Heartbreak Hotel'' y sus movimientos pélvicos en televisión nacional, el cantante de Memphis convirtió el rock en el fenómeno juvenil del siglo.', 'En el show de Ed Sullivan, las cámaras de televisión recibieron la orden estricta de enfocar a Elvis solo de la cintura para arriba.', 'Siglo XX d.C.', 'Radio', 'medio'),
  ('m-bossa-nova-joao-gilberto', 'musica', 'Lanzamiento de ''Chega de Saudade'' y nace la Bossa Nova', 1958, 'Hibridación intimista del compás de samba brasileño con acordes alterados de jazz y un fraseo vocal susurrado.', 'El peculiar rasgueo sincopado de guitarra acústica ideado por João Gilberto (la famosa ''batida'') transformó la música popular de Brasil.', 'Siglo XX d.C.', 'Guitar', 'medio'),
  ('m-kind-of-blue', 'musica', 'Miles Davis graba ''Kind of Blue''', 1959, 'En dos sesiones improvisadas en una iglesia de Nueva York, grabó el álbum de jazz modal más vendido e influyente de todos los tiempos.', 'Davis entregó a los músicos solo bocetos de escalas momentos antes de tocar; la mayoría de las pistas se grabaron en una sola toma.', 'Siglo XX d.C.', 'Disc', 'medio'),
  ('m-bob-dylan-blowing', 'musica', 'Bob Dylan lanza el himno ''Blowin'' in the Wind''', 1963, 'Canción insignia del movimiento pacifista y pro derechos civiles estadounidenses que consagró a Dylan como el trovador de una generación.', 'Dylan redactó la melodía y sus tres estrofas poéticas en escasos diez minutos de inspiración en un café del Greenwich Village neoyorquino.', 'Siglo XX d.C.', 'Mic', 'medio'),
  ('m-beatles-ed-sullivan', 'musica', 'The Beatles debutan en EE.UU. en The Ed Sullivan Show', 1964, '73 millones de televidentes (el 40% de la población de EE.UU.) sintonizaron la pantalla desatando la ''Beatlemanía'' e invasión británica.', 'Durante los minutos de la transmisión, la policía de Nueva York reportó que el índice de delincuencia juvenil en la ciudad cayó casi a cero.', 'Siglo XX d.C.', 'Users', 'medio'),
  ('m-beach-boys-pet-sounds', 'musica', 'Lanzamiento del álbum vanguardista ''Pet Sounds''', 1966, 'Obra cumbre de la producción psicodélica y arreglos orquestales incorporando timbres de campanas de bicicleta y theremines.', 'Paul McCartney confesó reiteradamente que ''God Only Knows'' es para él la composición armónica más hermosa jamás grabada.', 'Siglo XX d.C.', 'Disc', 'medio'),
  ('m-sgt-pepper', 'musica', 'The Beatles lanzan ''Sgt. Pepper''s Lonely Hearts Club Band''', 1967, 'El álbum conceptual que transformó el estudio de grabación en un instrumento musical de psicodelia, vanguardia y orquestaciones barrocas.', 'Fue el primer álbum de rock de la historia que imprimió las letras de todas las canciones completas en la contraportada del vinilo.', 'Siglo XX d.C.', 'Disc', 'medio'),
  ('m-woodstock', 'musica', 'Festival de Música y Arte de Woodstock', 1969, 'Medio millón de jóvenes se congregaron en una granja de Bethel (Nueva York) bajo el lema de ''Tres días de paz y música''.', 'Jimi Hendrix cerró el festival con una eléctrica y distorsionada reinterpretación del himno nacional de EE.UU. imitando bombas cayendo en Vietnam.', 'Siglo XX d.C.', 'Sun', 'medio'),
  ('m-jimi-hendrix-woodstock', 'musica', 'Jimi Hendrix deconstruye el himno de EE.UU. en Woodstock', 1969, 'Interpretación visceral con distorsión y feedback de ''The Star-Spangled Banner'' como protesta antibélica contra la Guerra de Vietnam.', 'Hendrix, que era zurdo, tocaba una guitarra Fender Stratocaster para diestros colocada al revés a la que únicamente le invertía las cuerdas.', 'Siglo XX d.C.', 'Guitar', 'medio'),
  ('m-imagine-lennon', 'musica', 'John Lennon lanza el himno pacifista ''Imagine''', 1971, 'Compuesta en un piano blanco de su casa en Tittenhurst Park, se convirtió en el himno por excelencia de la fraternidad universal y la paz.', 'Años después, Lennon reconoció que gran parte de la letra e inspiración lírica provenían del libro de poemas ''Grapefruit'' de Yoko Ono.', 'Siglo XX d.C.', 'Heart', 'medio'),
  ('m-dark-side-moon', 'musica', 'Pink Floyd lanza ''The Dark Side of the Moon''', 1973, 'Obra cumbre del rock progresivo que explora el paso del tiempo, el dinero, la locura y la mortalidad con su icónica portada del prisma de luz.', 'Permaneció en la lista Billboard 200 de álbumes más vendidos durante un récord inigualable de 958 semanas consecutivas (más de 18 años).', 'Siglo XX d.C.', 'Disc', 'medio'),
  ('m-bohemian-rhapsody', 'musica', 'Queen lanza la ópera rock ''Bohemian Rhapsody''', 1975, 'Una suite de casi seis minutos que fusiona balada, solo de guitarra de Brian May, sección operística de 180 pistas vocales y hard rock.', 'Las cintas maestras de grabación se volvieron casi transparentes por la cantidad de veces que tuvieron que regrabar las pistas corales.', 'Siglo XX d.C.', 'Mic', 'medio'),
  ('m-queen-a-night-at-the-opera', 'musica', 'Lanzamiento del álbum ''A Night at the Opera'' de Queen', 1975, 'Álbum cumbre que fusionó rock progresivo, baladas y ópera lírica gracias al fenómeno irrepetible de ''Bohemian Rhapsody''.', 'Freddie Mercury utilizó un piano de cola como cabecera de su cama para poder extender los brazos y componer notas si despertaba inspirado.', 'Siglo XX d.C.', 'Crown', 'medio'),
  ('m-reggae-marley-exodus', 'musica', 'Lanzamiento de ''Exodus'' por Bob Marley & The Wailers', 1977, 'Grabado en Londres tras sobrevivir a un atentado armado en Jamaica, propagó el mensaje de unidad, paz y reggae por el planeta.', 'La revista estadounidense Time nombró a ''Exodus'' el mejor álbum discográfico del siglo XX por delante de los discos de The Beatles.', 'Siglo XX d.C.', 'Smile', 'medio'),
  ('m-walkman-sony', 'musica', 'Sony lanza el primer reproductor portátil Walkman', 1979, 'El modelo TPS-L2 de color azul y plata permitió por primera vez escuchar música en casete con auriculares estéreo caminando por la calle.', 'Originalmente incluía dos tomas de auriculares y un botón ''hotline'' para que dos personas pudieran hablar entre sí mientras escuchaban música.', 'Siglo XX d.C.', 'Headphones', 'medio'),
  ('m-pink-floyd-the-wall', 'musica', 'Lanzamiento de la ópera rock ''The Wall'' de Pink Floyd', 1979, 'Monumental álbum doble conceptual sobre el trauma de posguerra, la educación autoritaria y el aislamiento psicológico contemporáneo.', 'Durante sus recitales en vivo el equipo montaba un colosal muro de bloques de cartón blanco que al final colapsaba de forma estrepitosa.', 'Siglo XX d.C.', 'Layers', 'medio'),
  ('m-thriller', 'musica', 'Michael Jackson lanza el álbum ''Thriller''', 1982, 'Con ''Billie Jean'', ''Beat It'' y el cortometraje de zombis de 14 minutos, se convirtió en el álbum musical más vendido de todos los tiempos (más de 70 millones de copias).', 'Eddie Van Halen grabó el solo de guitarra eléctrica de ''Beat It'' en solo 15 minutos y se negó a cobrar dinero por su colaboración.', 'Siglo XX d.C.', 'Sparkles', 'medio'),
  ('m-michael-jackson-moonwalk', 'musica', 'Michael Jackson debuta el ''Moonwalk'' en televisión', 1983, 'Durante el especial Motown 25 ejecutó ''Billie Jean'' deslizándose hacia atrás dando la ilusión óptica de desafiar la gravedad terrestre.', 'La leyenda del baile Fred Astaire lo llamó al día siguiente emocionado para felicitarlo y decirle que se movía como un relámpago.', 'Siglo XX d.C.', 'Sparkles', 'medio'),
  ('m-madonna-like-a-virgin', 'musica', 'Lanzamiento de ''Like a Virgin'' por Madonna', 1984, 'Consagró a Madonna como la indiscutible ''Reina del Pop'' y transformó la estética del videoclip y la moda juvenil de los años 80.', 'Su audaz actuación en los premios MTV vestida con un velo de novia y cinturón ''Boy Toy'' desató un terremoto mediático en la televisión.', 'Siglo XX d.C.', 'Music', 'medio'),
  ('m-live-aid', 'musica', 'Concierto benéfico histórico Live Aid', 1985, 'Concierto simultáneo en el estadio de Wembley (Londres) y JFK (Filadelfia) transmitido a 1.900 millones de personas para combatir la hambruna en Etiopía.', 'La actuación de 21 minutos de Queen y Freddie Mercury en Wembley es votada sistemáticamente como el mejor concierto en vivo de la historia del rock.', 'Siglo XX d.C.', 'Users', 'medio'),
  ('m-metallica-master-of-puppets', 'musica', 'Lanzamiento del álbum ''Master of Puppets'' de Metallica', 1986, 'Cúspide técnica del thrash metal por su contundencia rítmica, cambios de compás virtuosos y letras sobre la manipulación social.', 'Fue la primera grabación de metal en la historia en ser incluida en el Registro Nacional de Grabaciones de la Biblioteca del Congreso de EE.UU.', 'Siglo XX d.C.', 'Zap', 'medio'),
  ('m-nirvana-nevermind', 'musica', 'Nirvana lanza ''Nevermind'' y explota el grunge', 1991, 'Con el himno ''Smells Like Teen Spirit'', la banda de Seattle desbancó a Michael Jackson del número 1 de ventas y llevó el rock alternativo a la masa global.', 'El título de la canción nació cuando una amiga de Kurt escribió en la pared de su habitación: ''Kurt huele a Teen Spirit'' (que era una marca de desodorante femenino).', 'Siglo XX d.C.', 'Radio', 'medio'),
  ('m-daft-punk-homework', 'musica', 'Lanzamiento de ''Homework'' y auge del French Touch', 1997, 'Redefinió el house y la música electrónica con sampleos disco y ritmos irresistibles en himnos globales como ''Around the World''.', 'Adoptaron su célebre imagen de androides con cascos cromados para proteger su anonimato y vida cotidiana de la fama mediática.', 'Siglo XX d.C.', 'Headphones', 'medio'),
  ('m-buena-vista-social-club', 'musica', 'Grabación y consagración de ''Buena Vista Social Club''', 1997, 'Rescató del olvido las glorias sonoras del son y el bolero cubano de los años 40 conquistando teatros como el Carnegie Hall.', 'Varios de sus cantantes veteranos estaban retirados de la música e incluso lustraban zapatos en La Habana antes de grabar el disco.', 'Siglo XX d.C.', 'Music', 'medio'),
  ('m-napster', 'musica', 'Nacimiento de Napster y la revolución digital MP3', 1999, 'Plataforma de intercambio P2P que permitió a millones de internautas compartir canciones en MP3 gratis, poniendo en jaque a la industria discográfica mundial.', 'Llegó a tener 80 millones de usuarios registrados antes de ser cerrada por demandas de derechos de autor encabezadas por la banda Metallica.', 'Siglo XX d.C.', 'Download', 'medio'),
  ('m-eminem-marshall-mathers', 'musica', 'Lanzamiento de ''The Marshall Mathers LP'' de Eminem', 2000, 'El álbum de hip-hop más rápidamente vendido en la historia con una técnica de rimas complejas, sátira feroz y desahogo autobiográfico.', 'Despachó 1,76 millones de copias en sus primeros siete días a la venta pulverizando todos los récords anteriores de solistas en EE.UU.', 'Siglo XXI d.C.', 'Mic', 'medio'),
  ('m-ipod-apple', 'musica', 'Apple presenta el primer iPod con ''1.000 canciones en tu bolsillo''', 2001, 'Un reproductor blanco de 5 GB con rueda de desplazamiento táctil (''click wheel'') que inauguró la transición legal hacia la música digital de iTunes.', 'Podía almacenar toda la discografía de una persona en un dispositivo del tamaño de una baraja de naipes.', 'Siglo XXI d.C.', 'Disc', 'medio'),
  ('m-amy-winehouse-back-to-black', 'musica', 'Lanzamiento del álbum ''Back to Black'' de Amy Winehouse', 2006, 'Revitalizó el soul y rhythm & blues de los 60 con letras desgarradoras y una voz con matices emotivos dignos de Billie Holiday.', 'Arrasó con cinco premios Grammy en una sola noche mientras cantaba vía satélite desde un club en Londres al no poder viajar por visa.', 'Siglo XXI d.C.', 'Heart', 'medio'),
  ('m-spotify', 'musica', 'Lanzamiento oficial de Spotify en Europa', 2008, 'La empresa sueca fundó el modelo de streaming legal con acceso ilimitado a millones de canciones por suscripción mensual o publicidad.', 'Logró que la reproducción de una canción comenzara en menos de 200 milisegundos para que el usuario no sintiera retardo con un archivo local.', 'Siglo XXI d.C.', 'PlayCircle', 'medio'),
  ('m-adele-21', 'musica', 'Lanzamiento del colosal álbum ''21'' de Adele', 2011, 'Fenómeno de ventas mundiales impulsado por baladas como ''Rolling in the Deep'' y ''Someone Like You'' superando 31 millones de copias.', 'Fue el álbum más vendido del planeta durante dos años consecutivos (2011 y 2012), hazaña que ningún artista lograba desde Michael Jackson.', 'Siglo XXI d.C.', 'Disc', 'medio'),
  ('m-luis-fonsi-despacito', 'musica', 'Impacto y récord mundial del tema ''Despacito''', 2017, 'Lideró el ranking global Billboard Hot 100 durante 16 semanas batiendo récords universales de streaming para la música hispana.', 'Fue el primer videoclip en la historia de la plataforma YouTube en rebasar la barrera de las cinco mil millones de reproducciones.', 'Siglo XXI d.C.', 'Flame', 'medio'),
  ('m-billie-eilish-bad-guy', 'musica', 'Lanzamiento de ''When We All Fall Asleep...'' de Billie Eilish', 2019, 'Redefinió el pop alternativo de la era del streaming componiendo y grabando voces íntimas y bajos densos en el dormitorio familiar.', 'Con solo 18 años se convirtió en la persona más joven en conquistar las cuatro categorías reina de los Grammy en una sola edición.', 'Siglo XXI d.C.', 'Headphones', 'medio'),
  ('m-bad-bunny-un-verano-sin-ti', 'musica', 'Lanzamiento de ''Un Verano Sin Ti'' de Bad Bunny', 2022, 'Primer disco cantado completamente en castellano en recibir la nominación a Álbum del Año en la historia de los Grammy anglosajones.', 'Fue la producción discográfica más reproducida del mundo en Spotify en todo el planeta durante dos años consecutivos.', 'Siglo XXI d.C.', 'Sun', 'medio'),
  ('e-lumiere', 'cine', 'Primera proyección cinematográfica de los Hermanos Lumière', 1895, 'En el Grand Café de París exhibieron ''La llegada de un tren a la estación'', causando que algunos espectadores gritaran asustados creyendo que el tren se saldría de la tela.', 'El padre de los inventores les dijo: ''El cine es un invento sin ningún futuro comercial''.', 'Siglo XIX d.C.', 'Film', 'medio'),
  ('e-viaje-luna-melies', 'cine', 'Estreno de ''Viaje a la Luna'' de Georges Méliès', 1902, 'El ilusionista francés filmó la primera película de ciencia ficción, famosa por la cápsula espacial incrustándose en el ojo de la Luna.', 'Pintó a mano cuadro por cuadro copias en color en su taller con un ejército de 200 mujeres coloristas.', 'Siglo XX d.C.', 'Moon', 'medio')
INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('e-nosferatu-murnau', 'cine', 'Estreno de ''Nosferatu'' de F.W. Murnau', 1922, 'Obra maestra del expresionismo alemán y piedra angular de los filmes de terror gótico protagonizada por el conde Orlok.', 'Al no obtener los derechos del Drácula de Bram Stoker, cambiaron los nombres; sin embargo la viuda demandó y ordenó quemar todas las copias originales.', 'Siglo XX d.C.', 'Ghost', 'medio'),
  ('e-cantor-jazz', 'cine', 'Estreno de ''El Cantor de Jazz'' (primer filme sonoro)', 1927, 'La película de Warner Bros con sistema Vitaphone sincronizado puso fin a tres décadas de cine mudo con la famosa frase: ''¡Esperen un minuto, todavía no han oído nada!''.', 'Muchas estrellas del cine mudo vieron arruinadas sus carreras porque sus tonos de voz no encajaban con la imagen romántica de la pantalla.', 'Siglo XX d.C.', 'Mic', 'medio'),
  ('e-metropolis-lang', 'cine', 'Estreno de ''Metrópolis'' de Fritz Lang', 1927, 'Pilar fundacional de la ciencia ficción distópica con rascacielos monumentales y el robot androide femenino María.', 'Utilizó el pionero ''proceso Schüfftan'' mediante espejos en ángulo para filmar a los actores reales dentro de detalladas maquetas en miniatura.', 'Siglo XX d.C.', 'Eye', 'medio'),
  ('e-mickey-steamboat', 'cine', 'Debut de Mickey Mouse en ''Steamboat Willie''', 1928, 'El primer cortometraje de animación con sonido completamente sincronizado (música, voces y efectos sonoros acompasados al dibujo).', 'El propio Walt Disney prestó su voz a Mickey Mouse durante los primeros 20 años de existencia del personaje.', 'Siglo XX d.C.', 'Smile', 'medio'),
  ('e-luces-ciudad-chaplin', 'cine', 'Estreno de ''Luces de la Ciudad'' de Charles Chaplin', 1931, 'Chaplin apostó por el cine silente en plena era sonora creando uno de los finales más sublimes y emotivos de la historia del cine.', 'Chaplin repitió la escena donde la florista ciega le ofrece una flor más de 340 veces hasta quedar plenamente complacido con el gesto.', 'Siglo XX d.C.', 'Smile', 'medio'),
  ('e-king-kong-1933', 'cine', 'Estreno de ''King Kong'' y animación Stop-Motion', 1933, 'Hito revolucionario de los efectos ópticos y animación cuadro a cuadro que abarrotó los cines durante la Gran Depresión.', 'El estruendoso rugido de Kong fue diseñado en estudio mezclando grabaciones ralentizadas de leones y tigres reproducidas al revés.', 'Siglo XX d.C.', 'Camera', 'medio'),
  ('e-blancanieves-disney', 'cine', 'Estreno de ''Blancanieves y los siete enanitos''', 1937, 'El primer largometraje animado a color y con sonido de la historia que sentó los cimientos del imperio cinematográfico Disney.', 'Los magnates de Hollywood llamaban burlonamente a la producción ''La locura de Disney'', pero cosechó la mayor recaudación de la década.', 'Siglo XX d.C.', 'Sparkles', 'medio'),
  ('e-mago-oz', 'cine', 'Estreno de ''El Mago de Oz'' y su salto al Technicolor', 1939, 'El histórico momento cinematográfico en que Dorothy abre la puerta de su casa sepia de Kansas y entra al deslumbrante y colorido mundo de Oz.', 'Los zapatos de rubí de Dorothy eran originalmente plateados en el libro de L. Frank Baum, pero se cambiaron a rojo brillante para lucir el Technicolor.', 'Siglo XX d.C.', 'Sparkles', 'medio'),
  ('e-lo-que-el-viento-se-llevo', 'cine', 'Estreno de ''Lo que el viento se llevó''', 1939, 'Épica histórica en Technicolor ambientada en la Guerra de Secesión que ostenta el récord de taquilla ajustada por inflación.', 'Hattie McDaniel se convirtió en la primera actriz afroamericana en ser galardonada con un Premio Óscar por su entrañable rol de ''Mammy''.', 'Siglo XX d.C.', 'Film', 'medio'),
  ('e-ciudadano-kane', 'cine', 'Orson Welles estrena ''Ciudadano Kane''', 1941, 'Con solo 25 años, revolucionó la narrativa cinematográfica con la profundidad de campo, los ángulos bajos de cámara y el misterio de la palabra ''Rosebud''.', 'El magnate de la prensa William Randolph Hearst intentó comprar todos los rollos de película para quemarlos porque la trama se burlaba de su vida.', 'Siglo XX d.C.', 'Clapperboard', 'medio'),
  ('e-casablanca', 'cine', 'Estreno del clásico ''Casablanca''', 1942, 'Drama romántico ambientado en la Segunda Guerra Mundial en el Rick''s Café Américain con líneas inolvidables como ''Siempre nos quedará París''.', 'La famosa frase ''Tócala de nuevo, Sam'' jamás se pronuncia de esa forma exacta en toda la película.', 'Siglo XX d.C.', 'Heart', 'medio'),
  ('e-cantando-bajo-lluvia', 'cine', 'Estreno de ''Cantando bajo la lluvia''', 1952, 'El musical más celebrado de la era dorada de Hollywood que retrata con desternillante ironía el salto del cine mudo al sonoro.', 'Gene Kelly filmó su inolvidable baile con paraguas chapoteando en los charcos con casi 40 grados de fiebre en pleno invierno.', 'Siglo XX d.C.', 'Music', 'medio'),
  ('e-siete-samurais-kurosawa', 'cine', 'Estreno de ''Los Siete Samuráis'' de Akira Kurosawa', 1954, 'Obra cumbre que transformó el cine de acción mundial con el uso de múltiples cámaras simultáneas y cámara lenta en los combates.', 'Su estructura argumental inspiró directamente clásicos del western como ''Los Siete Magníficos'' y la trama de ''Bichos'' de Pixar.', 'Siglo XX d.C.', 'Sword', 'medio'),
  ('e-godzilla-1954', 'cine', 'Estreno de ''Godzilla'' (Gojira) en Japón', 1954, 'Nace el coloso radiactivo emblema del género Kaiju como poderosa metáfora visual de los traumas atómicos de la posguerra.', 'El traje de monstruo pesaba más de 100 kilos de caucho macizo; el actor dentro sólo soportaba rodar tres minutos antes de casi asfixiarse.', 'Siglo XX d.C.', 'Flame', 'medio'),
  ('e-disneyland', 'cine', 'Inauguración del primer parque Disneyland en California', 1955, 'El primer parque temático moderno con el Castillo de la Bella Durmiente, diseñado para que padres e hijos pudieran divertirse juntos.', 'El día de apertura fue tan caluroso que el asfalto recién colocado derretía los tacones de los zapatos de las señoras invitadas.', 'Siglo XX d.C.', 'Castle', 'medio'),
  ('e-ben-hur-1959', 'cine', 'Estreno de ''Ben-Hur'' y su mítica carrera de cuadrigas', 1959, 'Superproducción rodada en formato panorámico MGM Camera 65 que conquistó 11 Premios Óscar, una plusmarca que tardó 38 años en ser igualada.', 'El gigantesco circo romano construido para la carrera de cuadrigas requirió miles de toneladas de arena importada del Mediterráneo.', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('e-psicosis-hitchcock', 'cine', 'Alfred Hitchcock aterroriza con ''Psicosis''', 1960, 'Redefinió el cine de suspenso con la escena del motel Bates y los chirridos de violines de Bernard Herrmann.', 'Hitchcock impuso la norma pionera en los cines de prohibir tajantemente la entrada a la sala una vez que la película hubiera comenzado.', 'Siglo XX d.C.', 'Eye', 'medio'),
  ('e-james-bond-dr-no', 'cine', 'Estreno de ''El satánico Dr. No'' y debut de James Bond', 1962, 'Inauguró la saga cinematográfica de espías más duradera de la historia consagrando al agente británico 007 al servicio de Su Majestad.', 'La emblemática frase ''Bond... James Bond'' pronunciada junto a la mesa de baccarat fue improvisada por Sean Connery con flema natural.', 'Siglo XX d.C.', 'Eye', 'medio'),
  ('e-2001-odisea-espacio', 'cine', 'Estreno de ''2001: Odisea del Espacio'' de Stanley Kubrick', 1968, 'Revolución científica y visual de la ciencia ficción que anticipó la inteligencia artificial con el ojo rojo de HAL 9000 un año antes del Apolo 11.', 'Kubrick prescindió de cualquier efecto digital por computador: todas las naves flotantes fueron filmadas con maquetas físicas y trucos ópticos analógicos.', 'Siglo XX d.C.', 'Telescope', 'medio'),
  ('e-padrino', 'cine', 'Estreno de ''El Padrino'' de Francis Ford Coppola', 1972, 'La obra maestra sobre la familia mafiosa Corleone, ganadora de tres premios Óscar y considerada una de las mejores películas jamás filmadas.', 'Marlon Brando rellenó sus mejillas con algodón para que Vito Corleone tuviera la mandíbula caída de un bulldog.', 'Siglo XX d.C.', 'Crown', 'medio'),
  ('e-pong-atari', 'cine', 'Nacimiento de los videojuegos arcade con ''Pong''', 1972, 'Un simple juego de tenis de mesa de píxeles en blanco y negro inauguró la multimillonaria industria del entretenimiento interactivo.', 'La primera máquina de pruebas en una taberna de California se descompuso porque el depósito se llenó tanto de monedas que se atascó.', 'Siglo XX d.C.', 'Gamepad2', 'medio'),
  ('e-el-exorcista-1973', 'cine', 'Estreno de ''El Exorcista'' de William Friedkin', 1973, 'Fenómeno cultural sociológico y primer filme de terror en la historia en competir por el Óscar a Mejor Película de la Academia.', 'Durante sus primeras semanas de exhibición en salas muchas salas suministraban bolsas especiales para el mareo ante el impacto del público.', 'Siglo XX d.C.', 'Ghost', 'medio'),
  ('e-tiburon-spielberg', 'cine', 'Steven Spielberg estrena ''Tiburón'' (Jaws)', 1975, 'Creó el concepto de ''blockbuster veraniego'' con una partitura de dos notas amenazantes y el tiburón mecánico que casi nunca funcionaba.', 'El tiburón mecánico fallaba tanto que Spielberg tuvo que sugerir su presencia con planos subjetivos desde el fondo del mar, haciéndola más aterradora.', 'Siglo XX d.C.', 'Waves', 'medio'),
  ('e-rocky-balboa-1976', 'cine', 'Estreno de ''Rocky'' y debut de la cámara Steadicam', 1976, 'Stallone escribió el guion en tres días y rodó con presupuesto modesto la historia del boxeador underdog que ganó el Óscar a Mejor Película.', 'Fue uno de los primeros filmes en emplear el flamante invento de la cámara ''Steadicam'' para la mítica carrera subiendo las escaleras de Filadelfia.', 'Siglo XX d.C.', 'Award', 'medio'),
  ('e-star-wars', 'cine', 'Estreno de ''Star Wars: Una Nueva Esperanza''', 1977, 'Luke Skywalker, Han Solo y Darth Vader revolucionaron la ciencia ficción, los efectos especiales de ILM y el merchandising cinematográfico.', 'El sonido de la espada láser fue creado mezclando el zumbido de un proyector de cine viejo con la interferencia de un televisor sobre un micrófono.', 'Siglo XX d.C.', 'Sword', 'medio'),
  ('e-alien-octavo-pasajero', 'cine', 'Estreno de ''Alien: el octavo pasajero'' de Ridley Scott', 1979, 'Magistral simbiosis de claustrofobia espacial y terror biomecánico con la teniente Ellen Ripley enfrentando al letal xenomorfo.', 'El sobresalto de los actores durante la escena del embrión rompiendo el pecho de Kane fue auténtico: Scott ocultó los detalles del efecto especial para captar terror real.', 'Siglo XX d.C.', 'Sparkles', 'medio'),
  ('e-pacman', 'cine', 'Lanzamiento del videojuego Pac-Man en arcades', 1980, 'El círculo amarillo que devora puntos y huye de cuatro fantasmas en un laberinto se convirtió en el ícono definitivo de la cultura pop de los 80.', 'El creador Toru Iwatani se inspiró en la forma de una pizza a la que le faltaba una rebanada mientras almorzaba.', 'Siglo XX d.C.', 'Ghost', 'medio'),
  ('e-resplandor-kubrick', 'cine', 'Estreno de ''El Resplandor'' (The Shining)', 1980, 'Clásico psicológico ambientado en el nevado Hotel Overlook con Jack Torrance sucumbiendo a la locura hacha en mano.', 'La escalofriante línea ''Here''s Johnny!'' al romper la puerta del baño fue una genial improvisación de Jack Nicholson imitando un saludo televisivo.', 'Siglo XX d.C.', 'DoorClosed', 'medio'),
  ('e-et-extraterrestre', 'cine', 'Estreno de ''E.T., el extraterrestre''', 1982, 'La conmovedora amistad entre el niño Elliott y un pequeño ser de otro planeta que desea ''llamar a casa'', famosa por la bicicleta volando frente a la Luna.', 'La marca M&M''s rechazó aparecer en la película; en su lugar apareció Reese''s Pieces y sus ventas se dispararon un 300% en dos semanas.', 'Siglo XX d.C.', 'Sparkles', 'medio'),
  ('e-blade-runner-1982', 'cine', 'Estreno de ''Blade Runner'' de Ridley Scott', 1982, 'Fijó el canon visual del subgénero ciberpunk con sus rascacielos lluviosos, neones reflectantes y androides replicantes.', 'El conmovedor soliloquio final de Roy Batty (''He visto cosas que vosotros no creeríais...'') fue retocado la noche antes por el propio actor Rutger Hauer.', 'Siglo XX d.C.', 'Cpu', 'medio'),
  ('e-cazafantasmas-1984', 'cine', 'Estreno de ''Los Cazafantasmas'' (Ghostbusters)', 1984, 'Comedia sobrenatural con mochilas de protones que se convirtió en arrollador fenómeno de taquilla y cultura pop.', 'El entrañable automóvil ''Ecto-1'' era en realidad una ambulancia fúnebre Cadillac Miller-Meteor de 1959 acondicionada por el equipo de rodaje.', 'Siglo XX d.C.', 'Zap', 'medio'),
  ('e-terminator-1984', 'cine', 'Estreno de ''The Terminator'' de James Cameron', 1984, 'Thriller futurista sobre viajes en el tiempo y un cyborg asesino que popularizó en el léxico mundial la frase ''I''ll be back''.', 'James Cameron concibió el argumento en una pesadilla con fiebre en Roma donde soñaba con un esqueleto de cromo incandescente arrastrándose entre llamas.', 'Siglo XX d.C.', 'Bot', 'medio'),
  ('e-super-mario', 'cine', 'Lanzamiento de ''Super Mario Bros'' en NES', 1985, 'Rescató a la industria de los videojuegos de la crisis con sus saltos de plataformas fluidos y la música inolvidable de Koji Kondo.', 'Mario tiene bigote y gorra porque en la resolución de 8 bits era imposible dibujar una boca creíble y cabello que se moviera.', 'Siglo XX d.C.', 'Gamepad2', 'medio'),
  ('e-volver-al-futuro', 'cine', 'Estreno de ''Volver al Futuro'' (Back to the Future)', 1985, 'El DeLorean que viaja en el tiempo a 88 millas por hora gracias al condensador de flujo, convirtiéndose en el icono de los viajes temporales.', 'En el guion original, la máquina del tiempo era un refrigerador viejo en lugar de un automóvil deportivo.', 'Siglo XX d.C.', 'Clock', 'medio'),
  ('e-totoro-ghibli', 'cine', 'Estreno de ''Mi Vecino Totoro'' de Hayao Miyazaki', 1988, 'Poema visual animado sobre la infancia, la naturaleza y los espíritus del bosque que consagró a Totoro como la mascota insignia de Ghibli.', 'En los cines nipones se proyectó en sesión doble junto al desgarrador drama bélico ''La tumba de las luciérnagas'', un contraste emocional rotundo.', 'Siglo XX d.C.', 'Heart', 'medio'),
  ('e-gameboy-tetris', 'cine', 'Lanzamiento de la Game Boy con ''Tetris''', 1989, 'La consola portátil gris con pantalla monocromática de cuatro tonos de verde vendió más de 118 millones de unidades en todo el mundo.', 'Una Game Boy expuesta a bombas durante la Guerra del Golfo quedó chamuscada pero siguió funcionando perfectamente.', 'Siglo XX d.C.', 'Smartphone', 'medio'),
  ('e-batman-burton-1989', 'cine', 'Estreno de ''Batman'' de Tim Burton', 1989, 'Redefinió el cine moderno de superhéroes con una atmósfera gótica y expresionista desatando la fiebre comercial de la ''Batimanía''.', 'Jack Nicholson negoció un porcentaje sobre las ganancias de taquilla y mercadotecnia que le reportó más de 60 millones de dólares.', 'Siglo XX d.C.', 'Moon', 'medio'),
  ('e-silencio-inocentes-1991', 'cine', 'Estreno de ''El Silencio de los Inocentes''', 1991, 'Thriller psicológico que conquistó los cinco grandes galardones principales de la Academia gracias al magnético caníbal Hannibal Lecter.', 'Anthony Hopkins aparece en la pantalla un total de apenas 16 a 24 minutos a lo largo de todo el metraje para ganar el Óscar a Mejor Actor.', 'Siglo XX d.C.', 'Lock', 'medio'),
  ('e-jurassic-park', 'cine', 'Estreno de ''Jurassic Park'' y la revolución CGI', 1993, 'El T-Rex y los velociraptores generados por computadora e increíbles animatrónicos hicieron creer al público que los dinosaurios caminaban de nuevo.', 'A pesar de sus dos horas de duración, los dinosaurios solo aparecen en pantalla durante un total de 15 minutos en toda la película.', 'Siglo XX d.C.', 'Film', 'medio'),
  ('e-pulp-fiction', 'cine', 'Estreno de ''Pulp Fiction'' de Quentin Tarantino', 1994, 'Revolucionó el cine independiente con su estructura no lineal en capítulos entrelazados, diálogos filosos y la Palma de Oro en Cannes.', 'La famosa billetera que dice ''Bad Mother Fucker'' pertenecía en la vida real al propio Quentin Tarantino.', 'Siglo XX d.C.', 'Clapperboard', 'medio'),
  ('e-playstation', 'cine', 'Sony lanza la primera consola PlayStation en Japón', 1994, 'Apostó por el formato CD-ROM y los gráficos 3D poligonales, rompiendo el dominio de Nintendo y Sega y vendiendo más de 100 millones de unidades.', 'Originalmente nació como una colaboración secreta con Nintendo para crear un lector de CD para la Super Nintendo antes de romper relaciones.', 'Siglo XX d.C.', 'Tv', 'medio'),
  ('e-rey-leon-disney-1994', 'cine', 'Estreno de ''El Rey León'' de Disney', 1994, 'Cúspide dorada de la animación tradicional inspirada en Hamlet de Shakespeare con canciones compuestas por Elton John y Tim Rice.', 'Los ilustradores de Disney trajeron leones de verdad a los estudios de animación de Burbank para estudiar al milímetro sus andares y anatomía muscular.', 'Siglo XX d.C.', 'Crown', 'medio'),
  ('e-forest-gump-1994', 'cine', 'Estreno de ''Forrest Gump'' y sus efectos digitales', 1994, 'Travesía nostálgica por décadas decisivas de la historia norteamericana popularizando citas perennes como ''La vida es como una caja de bombones''.', 'Insertó digitalmente a Tom Hanks en noticieros históricos interactuando con figuras reales como John F. Kennedy y Richard Nixon.', 'Siglo XX d.C.', 'Heart', 'medio'),
  ('e-toy-story', 'cine', 'Estreno de ''Toy Story'' (primer largometraje 100% CGI)', 1995, 'Pixar hizo historia en la animación cinematográfica dando vida a los juguetes Woody y Buzz Lightyear completamente por computadora.', 'Cada fotograma individual de la película tardaba entre 45 minutos y 30 horas de renderizado en las granjas de servidores de Pixar.', 'Siglo XX d.C.', 'Smile', 'medio'),
  ('e-titanic', 'cine', 'Estreno de ''Titanic'' de James Cameron', 1997, 'Empató el récord de 11 premios Óscar y fue la primera película en superar los mil millones de dólares de recaudación en taquilla.', 'Cameron descendió personalmente en sumergibles rusos al pecio real del Titanic en el fondo del Atlántico para filmar planos auténticos.', 'Siglo XX d.C.', 'Ship', 'medio'),
  ('e-matrix', 'cine', 'Estreno de ''The Matrix'' y el efecto ''bullet time''', 1999, 'Filosofía cyberpunk, gabardinas de cuero negro y la ilusión visual de esquivar balas con 120 cámaras sincronizadas en arco.', 'La famosa lluvia de código verde digital fue creada escaneando símbolos de libros de recetas de sushi japonesas de la esposa del diseñador.', 'Siglo XX d.C.', 'Glasses', 'medio'),
  ('e-senor-anillos', 'cine', 'Estreno de ''El Señor de los Anillos: La Comunidad del Anillo''', 2001, 'Rodada simultáneamente en los paisajes naturales de Nueva Zelanda, elevó la fantasía épica a la cima del prestigio y la crítica cinematográfica.', 'Se forjaron a mano más de 48.000 piezas de armadura y millones de anillas de cota de malla para el vestuario de los extras.', 'Siglo XXI d.C.', 'Crown', 'medio'),
  ('e-shrek-dreamworks-2001', 'cine', 'Estreno de ''Shrek'' por DreamWorks Animation', 2001, 'Parodia irreverente de los cuentos tradicionales que se adjudicó el primer Premio Óscar otorgado en la historia a Mejor Película de Animación.', 'El triunfo arrollador del carismático ogro verde y Asno catapultó a los estudios DreamWorks como el rival hegemónico de Pixar y Disney.', 'Siglo XXI d.C.', 'Smile', 'medio'),
  ('e-viaje-chihiro-2001', 'cine', 'Estreno de ''El viaje de Chihiro'' de Hayao Miyazaki', 2001, 'Obra maestra que conquistó el Óscar y el Oso de Oro de Berlín sumergiendo a Chihiro en una casa de baños termales para deidades espirituales.', 'Miyazaki no redactó un guion literario previo completo: comenzaba a dibujar los guiones gráficos dejando fluir el desarrollo de la trama.', 'Siglo XXI d.C.', 'Sparkles', 'medio'),
  ('e-piratas-caribe-2003', 'cine', 'Estreno de ''Piratas del Caribe: La maldición del Perla Negra''', 2003, 'Resucitó de manera espectacular el cine clásico de corsarios gracias a la estrafalaria genialidad del Capitán Jack Sparrow.', 'Durante el rodaje los directivos temían que los andares ebrios y extravagantes de Johnny Depp provocaran una catástrofe en taquilla.', 'Siglo XXI d.C.', 'Compass', 'medio')
INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('e-iron-man-mcu-2008', 'cine', 'Estreno de ''Iron Man'' y nacimiento del Universo Marvel (MCU)', 2008, 'Puso la primera piedra del macrocosmos cinematográfico interconectado más lucrativo y taquillero de la historia del cine.', 'La célebre escena tras los créditos con Nick Fury hablando de la ''Iniciativa Vengadores'' se rodó en máximo secreto con solo tres técnicos.', 'Siglo XXI d.C.', 'Zap', 'medio'),
  ('e-el-caballero-noche-ledger', 'cine', 'Estreno de ''The Dark Knight'' y el Joker de Heath Ledger', 2008, 'Elevó el cine de superhéroes al más alto estatus de tragedia criminal con una interpretación magistral y póstuma de Heath Ledger como el Joker.', 'Heath Ledger se aisló en una habitación de hotel durante un mes redactando un diario íntimo para moldear la perturbadora psicología y risa del villano.', 'Siglo XXI d.C.', 'Mask', 'medio'),
  ('e-avatar-3d', 'cine', 'Estreno de ''Avatar'' y el renacimiento del cine 3D', 2009, 'Transportó a la audiencia al planeta Pandora con tecnología de captura de movimiento fotorrealista, convirtiéndose en la película más taquillera de la historia.', 'Cameron esperó más de 10 años para filmarla porque la tecnología de efectos digitales que tenía en mente en los años 90 aún no existía.', 'Siglo XXI d.C.', 'Eye', 'medio'),
  ('e-origen-inception-2010', 'cine', 'Estreno de ''El Origen'' (Inception) de Christopher Nolan', 2010, 'Thriller cerebral sobre espionaje corporativo onírico donde los personajes descienden a través de múltiples capas de sueños dentro de sueños.', 'El plano final del tótem giratorio desató uno de los debates más intensos y apasionados sobre la realidad y la ficción en foros de todo el mundo.', 'Siglo XXI d.C.', 'HelpCircle', 'medio'),
  ('e-gta-v-lanzamiento', 'cine', 'Lanzamiento récord del videojuego ''Grand Theft Auto V''', 2013, 'El hito de entretenimiento comercial más rentable de la historia, recaudando 800 millones de dólares en sus primeras 24 horas a la venta.', 'Superó en un solo día el estreno de taquilla de cualquier superproducción de Hollywood o lanzamiento discográfico jamás realizado.', 'Siglo XXI d.C.', 'Gamepad2', 'medio'),
  ('e-interstellar-2014', 'cine', 'Estreno de ''Interstellar'' y el agujero negro Gargantúa', 2014, 'Odisea interestelar a través de un agujero de gusano para salvar a la humanidad guiada por las ecuaciones de relatividad general del Nobel Kip Thorne.', 'La renderización visual del disco de acreción del agujero negro fue tan rigurosa que derivó en la publicación de artículos científicos formales.', 'Siglo XXI d.C.', 'Globe', 'medio'),
  ('e-parasitos-bong-joon-ho', 'cine', 'Triunfo histórico de ''Parásitos'' en los Premios Óscar', 2019, 'Primera película rodada enteramente en un idioma no inglés en conquistar la estatuilla de Mejor Película en los Óscar de la Academia.', 'En su alegre rueda de prensa el director surcoreano bromeó disculpándose con los grabadores porque sus cuatro premios Óscar pesaban demasiado.', 'Siglo XXI d.C.', 'Award', 'medio'),
  ('e-avengers-endgame-2019', 'cine', 'Estreno de ''Avengers: Endgame'' y fin de una era', 2019, 'Clímax narrativo de 22 películas cruzadas que batió el récord de taquilla mundial debutando con más de 1.200 millones en su primer fin de semana.', 'La emblemática frase de respuesta de Tony Stark (''Y yo... soy Iron Man'') fue concebida en la sala de montaje e incorporada en tomas adicionales.', 'Siglo XXI d.C.', 'Shield', 'medio'),
  ('e-juegos-del-calamar-2021', 'cine', 'Fenómeno global de la serie ''El juego del calamar''', 2021, 'Distopía surcoreana de supervivencia que se convirtió en la serie televisiva más vista en la historia de la plataforma Netflix.', 'El creador pasó diez años con el guion rechazado por productores que lo calificaban de excesivamente bizarro y grotesco.', 'Siglo XXI d.C.', 'Target', 'medio'),
  ('e-oppenheimer-nolan-2023', 'cine', 'Estreno de ''Oppenheimer'' y el fenómeno Barbenheimer', 2023, 'Biopic colosal en gran formato IMAX sobre el padre de la bomba atómica que desató un masivo retorno de espectadores a las salas de cine.', 'Nolan recreó el resplandor de la prueba nuclear Trinity sin utilizar gráficos computarizados (CGI), empleando magnesio y combustible de aviación.', 'Siglo XXI d.C.', 'Flame', 'medio'),
  ('cf-megido', 'conflictos', 'Batalla de Megido en Canaán', -1457, 'Considerada la primera batalla documentada con detalle de la historia militar; Tutmosis III sorprendió a la coalición rebelde cananea cruzando un peligroso desfiladero.', 'El nombre de esta milenaria colina cananea (''Har Megiddo'') dio origen a la palabra bíblica ''Armagedón''.', 'Siglo XV a.C.', 'Swords', 'medio'),
  ('cf-kadesh', 'conflictos', 'Batalla de Kadesh y carros de combate', -1274, 'El mayor choque de carros tirados por caballos de la antigüedad entre los imperios egipcio e hitita a orillas del río Orontes.', 'Condujo al Tratado de Kadesh, el acuerdo de paz y no agresión mutuo más antiguo que se conserva grabado en piedra y arcilla.', 'Siglo XIII a.C.', 'Shield', 'medio'),
  ('cf-maraton', 'conflictos', 'Batalla de Maratón frente a los persas', -490, 'La infantería pesada hoplita ateniense cargó a la carrera envolviendo los flancos del colosal ejército persa enviado por Darío I.', 'El mensajero Filípides corrió 42 kilómetros desde la costa hasta Atenas para anunciar ''¡Hemos vencido!'' antes de desplomarse.', 'Siglo V a.C.', 'Zap', 'medio'),
  ('cf-termopilas', 'conflictos', 'Batalla del paso de las Termópilas', -480, 'Trescientos espartanos y aliados griegos resistieron durante tres días en un estrecho desfiladero frente al avance del emperador persa Jerjes I.', 'Cuando los persas intimidaron diciendo que sus flechas taparían el sol, el espartano Dienekes replicó: ''Mejor, así lucharemos a la sombra''.', 'Siglo V a.C.', 'Shield', 'medio'),
  ('cf-salamina', 'conflictos', 'Batalla naval de trirremes en Salamina', -480, 'Los ágiles trirremes atenienses atrajeron a la masiva flota persa al estrecho canal embistiéndolos con sus espolones de bronce.', 'Jerjes instaló un trono de oro en lo alto del monte Egaleo para presenciar la victoria, pero terminó viendo la aniquilación de sus naves.', 'Siglo V a.C.', 'Ship', 'medio'),
  ('cf-platea', 'conflictos', 'Batalla de Platea y fin de la invasión persa', -479, 'La mayor fuerza hoplita confederada de la historia griega derrotó en campo abierto al ejército persa de Mardonio sellando la libertad de Grecia.', 'Los griegos dedicaron una columna de bronce con tres serpientes entrelazadas en el oráculo de Delfos, hoy conservada en Estambul.', 'Siglo V a.C.', 'Swords', 'medio'),
  ('cf-leuctra', 'conflictos', 'Batalla de Leuctra y el fin del dominio espartano', -371, 'El genio militar tebano rompió la invencibilidad espartana inventando el ''orden oblicuo'', concentrando una columna de 50 filas en un flanco.', 'El rey espartano Cleómbroto I cayó en combate, marcando la primera derrota militar a gran escala de los espartanos en tierra abierta.', 'Siglo IV a.C.', 'Shield', 'medio'),
  ('cf-queronea', 'conflictos', 'Batalla de Queronea y unificación de Grecia', -338, 'Las falanges con sarissas de Macedonia vencieron a atenienses y tebanos; Alejandro lideró con 18 años la carga de caballería de los Compañeros.', 'Filipo II erigió el colosal León de Queronea de piedra sobre la fosa donde fueron sepultados los valientes miembros del Batallón Sagrado tebano.', 'Siglo IV a.C.', 'Crown', 'medio'),
  ('cf-gaugamela', 'conflictos', 'Batalla de Gaugamela y caída del Imperio Persa', -331, 'Obra maestra táctica donde Alejandro abrió una brecha en el centro persa y cargó en cuña directamente contra el carro real de Darío.', 'Darío había nivelado y despejado la llanura para que sus carros con guadañas en las ruedas pudieran correr libremente, pero la táctica macedonia los esquivó.', 'Siglo IV a.C.', 'Swords', 'medio'),
  ('cf-hidapses', 'conflictos', 'Batalla del Río Hidaspes contra elefantes de guerra', -326, 'Alejandro cruzó el caudaloso río indio en plena tormenta nocturna y enfrentó una temible barrera frontal de 200 elefantes de guerra.', 'Tras vencer al rey Poros, Alejandro quedó tan conmovido por su dignidad y valentía que no solo le perdonó la vida sino que le devolvió su reino expandido.', 'Siglo IV a.C.', 'Shield', 'medio'),
  ('cf-canas', 'conflictos', 'Batalla de Cannas y el cerco perfecto de Aníbal', -216, 'Aníbal formó una línea convexa que fue retrocediendo ordenadamente para atraer al grueso del ejército romano hasta rodear y aniquilar a 50.000 legionarios.', 'Se estudia en todas las academias militares del mundo moderno como el ejemplo perfecto de maniobra de doble envolvimiento.', 'Siglo III a.C.', 'Swords', 'medio'),
  ('cf-zama', 'conflictos', 'Batalla de Zama y la caída de Cartago', -202, 'El comandante romano contrarrestó la carga de 80 elefantes abriendo pasillos en sus líneas con trompetas y los envolvió con caballería númida.', 'Escipión adoptó el apodo honorífico de ''El Africano'' tras esta victoria decisiva que convirtió a Roma en el amo indiscutido del Mediterráneo.', 'Siglo III a.C.', 'Crown', 'medio'),
  ('cf-alesia', 'conflictos', 'Asedio de Alesia y la doble muralla de César', -52, 'César construyó una muralla interior para asediar la fortaleza gala y otra muralla exterior para protegerse de 200.000 galos de refuerzo.', 'Vercingétorix arrojó sus armas a los pies de César rindiéndose para evitar que su pueblo muriera de inanición dentro del fuerte.', 'Siglo I a.C.', 'Castle', 'medio'),
  ('cf-farsalia', 'conflictos', 'Batalla de Farsalia en la Guerra Civil romana', -48, 'En las llanuras de Grecia, los veteranos leales de César derrotaron al ejército del Senado comandado por Pompeyo, sellando el destino de la República.', 'César ordenó a sus legionarios clavar sus lanzas hacia los rostros de los jóvenes jinetes aristócratas de Pompeyo, sabiendo que huirían para proteger su apariencia.', 'Siglo I a.C.', 'Swords', 'medio'),
  ('cf-accio', 'conflictos', 'Batalla naval de Accio y nacimiento del Imperio Romano', -31, 'Las liburnas ligeras dirigidas por Agripa neutralizaron a los pesados quinquerremes de Marco Antonio y la reina Cleopatra en las costas griegas.', 'Octavio se convirtió tras esta batalla en el emperador absoluto de Roma adoptando el título reverencial de ''César Augusto''.', 'Siglo I a.C.', 'Ship', 'medio'),
  ('cf-bosque-teutoburgo', 'conflictos', 'Desastre romano del Bosque de Teutoburgo', 9, 'Las tribus germanas emboscaron en ciénagas y densos bosques a tres legiones romanas completas aniquilando a más de 20.000 soldados.', 'El emperador Augusto se golpeaba la cabeza contra las puertas del palacio en Roma gritando en sueños: ''¡Varo, devuélveme mis legiones!''.', 'Siglo I d.C.', 'AlertTriangle', 'medio'),
  ('cf-acantilados-rojos', 'conflictos', 'Batalla de los Acantilados Rojos (Chibi)', 208, 'La mayor batalla fluvial de la historia china en el río Yangtsé, donde naves cargadas con paja incendiaron la inmensa armada de Cao Cao encadenada.', 'Frenó la unificación forzosa del norte e inauguró el legendario período de los Tres Reinos de China inmortalizado en la literatura oriental.', 'Siglo III d.C.', 'Flame', 'medio'),
  ('cf-puente-milvio', 'conflictos', 'Batalla del Puente Milvio y la visión de la Cruz', 312, 'Constantino venció a su rival a las puertas de Roma tras pintar el monograma cristiano ''Crismón'' en los escudos de sus soldados.', 'Antes del combate Constantino aseguró ver en el cielo una cruz brillante con la inscripción latina: ''In hoc signo vinces'' (Con este signo vencerás).', 'Siglo IV d.C.', 'Shield', 'medio'),
  ('cf-adrianopolis', 'conflictos', 'Batalla de Adrianópolis y colapso de las legiones', 378, 'La caballería pesada visigoda embistió el flanco del ejército imperial romano oriental aniquilando a dos tercios de las tropas y al propio emperador.', 'El historiador Amiano Marcelino la calificó como la peor catástrofe militar de Roma desde la Batalla de Cannas seiscientos años antes.', 'Siglo IV d.C.', 'Swords', 'medio'),
  ('cf-campos-catalaunicos', 'conflictos', 'Batalla de los Campos Cataláunicos contra Atila', 451, 'Una coalición de romanos y visigodos frenó el avance arrollador de los hunos de Atila en las llanuras de Châlons en la Galia.', 'Aecio, llamado ''el último de los romanos'', había vivido en su juventud como rehén de intercambio entre los propios hunos conociendo todas sus tácticas.', 'Siglo V d.C.', 'Shield', 'medio'),
  ('cf-yarmuk', 'conflictos', 'Batalla de Yarmuk y conquista del Levante', 636, 'Las fuerzas del Califato Rashidun derrotaron a un ejército imperial bizantino numéricamente superior en los desfiladeros del río Yarmuk.', 'Jálid utilizó una tormenta de arena cegadora del desierto para cargar contra los bizantinos tomándolos completamente desorientados.', 'Siglo VII d.C.', 'Swords', 'medio'),
  ('cf-al-qadisiyya', 'conflictos', 'Batalla de al-Qadisiyya y caída del Imperio Sasánida', 636, 'Combate de cuatro días en Mesopotamia donde las tropas árabes neutralizaron a los elefantes de guerra persas cegándolos con flechas.', 'La captura del legendario estandarte persa cubierto de joyas preciosas (''Derafsh Kaviani'') marcó el derrumbe final de la Persia sasánida.', 'Siglo VII d.C.', 'Crown', 'medio'),
  ('cf-tours-poitiers', 'conflictos', 'Batalla de Poitiers y la resistencia de Carlos Martel', 732, 'La férrea formación de infantería franca resistió firmemente las cargas de caballería omeya frenando la expansión islámica en el corazón de Europa.', 'Carlos se ganó tras la batalla el sobrenombre de ''Martel'' (el Martillo) por golpear y quebrar las líneas enemigas como hierro sobre yunque.', 'Siglo VIII d.C.', 'Shield', 'medio'),
  ('cf-hastings', 'conflictos', 'Batalla de Hastings y la conquista normanda', 1066, 'La caballería normanda fingió retiradas tácticas para romper el formidable muro de escudos anglosajón en la colina de Senlac.', 'El rey Harold II murió al ser alcanzado por una flecha en el ojo, acontecimiento inmortalizado en el célebre bordado del Tapiz de Bayeux.', 'Siglo XI d.C.', 'Crown', 'medio'),
  ('cf-manzikert', 'conflictos', 'Batalla de Manzikert y la entrada a Anatolia', 1071, 'Los arqueros a caballo turcos selyúcidas derrotaron al ejército bizantino capturando por primera vez con vida a un emperador de Constantinopla.', 'Alp Arslan trató con caballerosidad al emperador vencido colocándole un pie sobre el cuello en señal simbólica de triunfo y liberándolo tras pactar un rescate.', 'Siglo XI d.C.', 'Castle', 'medio'),
  ('cf-asedio-jerusalen', 'conflictos', 'Asedio y toma de Jerusalén en la Primera Cruzada', 1099, 'Los cruzados europeos asaltaron las murallas de la Ciudad Santa utilizando torres de asedio construidas con maderas de barcos genoveses desmontados.', 'Godofredo rechazó portar una corona de oro en la ciudad proclamando que jamás llevaría corona real donde Cristo vistió una corona de espinas.', 'Siglo XI d.C.', 'Shield', 'medio'),
  ('cf-hattin', 'conflictos', 'Batalla de los Cuernos de Hattin', 1187, 'Saladino atrajo al ejército cruzado a una meseta árida bajo un calor sofocante e incendió los pastizales secos dejándolos cercados y sin agua.', 'La victoria permitió a Saladino recuperar la ciudad de Jerusalén para el Islam con relativa clemencia hacia la población civil.', 'Siglo XII d.C.', 'Flame', 'medio'),
  ('cf-navas-tolosa', 'conflictos', 'Batalla de Las Navas de Tolosa en Jaén', 1212, 'La coalición militar de los reinos de Castilla, Navarra y Aragón derrotó al ejército almohade quebrando la defensa andalusí en Sierra Morena.', 'Un pastor local llamado Martín Halaja guio secretamente a las tropas cristianas a través de un paso montuoso desconocido para sorprender a los almohades.', 'Siglo XIII d.C.', 'Swords', 'medio'),
  ('cf-rio-kalka', 'conflictos', 'Batalla del Río Kalka y la invasión mongola', 1223, 'Una fuerza expedicionaria mongola fingió una huida durante nueve días consecutivos hasta que los príncipes rusos rompieron formación y fueron masacrados.', 'Subutai y sus oficiales cenaron sobre una plataforma de madera colocada encima de los príncipes rusos prisioneros maniatados.', 'Siglo XIII d.C.', 'Zap', 'medio'),
  ('cf-ain-yalut', 'conflictos', 'Batalla de Ain Jalut y el freno a los mongoles', 1260, 'En el valle de Jezreel en Galilea, la caballería mameluca infligió la primera gran derrota en campo abierto al temido Imperio Mongol.', 'Baibars utilizó por primera vez en la historia militar primitiva cañones de mano (''midfa'') para asustar con estampidos a los caballos mongoles.', 'Siglo XIII d.C.', 'Shield', 'medio'),
  ('cf-bannockburn', 'conflictos', 'Batalla de Bannockburn y la libertad de Escocia', 1314, 'Los escoceses organizaron erizos defensivos de piqueros llamados ''schiltrons'' destrozando la pesada caballería de los caballeros ingleses.', 'El propio rey Robert the Bruce partió el casco y cráneo del caballero inglés Henry de Bohun con un solo golpe de hacha al inicio del combate.', 'Siglo XIV d.C.', 'Swords', 'medio'),
  ('cf-crecy', 'conflictos', 'Batalla de Crécy y el poder del arco largo galés', 1346, 'Miles de arqueros ingleses descargaron una lluvia ininterrumpida de flechas con arcos de tejo aniquilando a la flor de la caballería francesa armada con ballestas.', 'Los arqueros clavaban decenas de flechas en el lodo frente a ellos para poder disparar hasta diez flechas mortíferas por minuto.', 'Siglo XIV d.C.', 'Target', 'medio'),
  ('cf-azincourt', 'conflictos', 'Batalla de Azincourt bajo el fango', 1415, 'Enrique V derrotó a una fuerza francesa vastly superior en número aprovechando un estrecho campo de cultivo recién arado convertido en espeso lodo.', 'El inmortal discurso de San Crispín atribuido por Shakespeare (''Nosotros pocos, nosotros felices pocos, nosotros banda de hermanos'') se inspiró en este día.', 'Siglo XV d.C.', 'Crown', 'medio'),
  ('cf-asedio-constantinopla', 'conflictos', 'Asedio y Caída de Constantinopla', 1453, 'Los otomanos bombardearon las legendarias murallas teodosianas con gigantescos cañones de bronce fundidos por el ingeniero Urbano, poniendo fin a la Edad Media.', 'Mehmed transportó docenas de barcos de guerra por tierra sobre troncos engrasados durante la noche para burlar la gran cadena de hierro del Cuerno de Oro.', 'Siglo XV d.C.', 'Castle', 'medio'),
  ('cf-toma-tenochtitlan', 'conflictos', 'Caída de México-Tenochtitlan en el lago Texcoco', 1521, 'Asedio de 93 días apoyado por 13 bergantines armados construidos en tierra y decenas de miles de aliados indígenas tlaxcaltecas contra el imperio mexica.', 'El último tlatoani mexica Cuauhtémoc fue capturado en una canoa intentando romper el cerco naval en el lago.', 'Siglo XVI d.C.', 'Ship', 'medio'),
  ('cf-pavia', 'conflictos', 'Batalla de Pavía y captura del rey de Francia', 1525, 'Los arcabuceros de los Tercios españoles destrozaron la famosa caballería pesada blindada francesa en el parque de Mirabello.', 'El monarca francés Francisco I fue apresado con vida y trasladado a una torre de Madrid; envió a su madre la frase: ''Todo se ha perdido, salvo el honor''.', 'Siglo XVI d.C.', 'Shield', 'medio'),
  ('cf-lepanto', 'conflictos', 'Batalla naval de Lepanto en el golfo de Corinto', 1571, 'El mayor combate naval de galeras a remo de la historia entre la Santa Liga cristiana y la armada del Imperio Otomano.', 'El célebre autor Miguel de Cervantes combatió con fiebre y recibió dos disparos en el pecho y uno en la mano izquierda, ganándose el apodo de ''El Manco de Lepanto''.', 'Siglo XVI d.C.', 'Ship', 'medio'),
  ('cf-sekigahara', 'conflictos', 'Batalla de Sekigahara y unificación de Japón', 1600, 'El mayor choque de samuráis en la niebla donde Ieyasu venció al Ejército Occidental gracias a la traición oportuna del clan Kobayakawa.', 'Esta decisiva jornada puso fin a la sangrienta era Sengoku de guerras civiles e inauguró más de 250 años de paz bajo el Shogunato Tokugawa.', 'Siglo XVII d.C.', 'Swords', 'medio'),
  ('cf-asedio-viena', 'conflictos', 'Batalla de Kahlenberg y la salvación de Viena', 1683, 'La mayor carga de caballería de la historia europea: 18.000 jinetes encabezados por 3.000 Húsares Alados descendieron de la colina quebrando el asedio otomano.', 'Las enormes alas de madera con plumas de águila de los húsares producían un silbido ensordecedor que sembraba el pánico entre las filas enemigas.', 'Siglo XVII d.C.', 'Crown', 'medio'),
  ('cf-blenheim', 'conflictos', 'Batalla de Blenheim en la Guerra de Sucesión Española', 1704, 'Victoria anglo-imperial decisiva a orillas del río Danubio que salvó a Viena y quebró la racha de imbatibilidad de las tropas de Luis XIV de Francia.', 'La reina Ana de Gran Bretaña regaló al duque una inmensa finca donde mandó erigir el fastuoso Palacio de Blenheim, donde nacería Winston Churchill.', 'Siglo XVIII d.C.', 'Castle', 'medio')
INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('cf-poltava', 'conflictos', 'Batalla de Poltava y el ascenso del Imperio Ruso', 1709, 'En las llanuras ucranianas, las tropas rusas modernizadas por Pedro el Grande aniquilaron al ejército sueco terminando con su condición de gran potencia báltica.', 'El rey Carlos XII de Suecia tuvo que ser transportado en camilla durante el combate al haber recibido un balazo en el pie días antes.', 'Siglo XVIII d.C.', 'Crown', 'medio'),
  ('cf-yorktown', 'conflictos', 'Asedio de Yorktown y triunfo de la Revolución Americana', 1781, 'Fuerzas combinadas continentales y francesas sitiaron al general británico Cornwallis en Virginia mientras la flota del almirante De Grasse bloqueaba el mar.', 'Durante la ceremonia formal de rendición de las tropas casacas rojas británicas, la banda militar tocó la melodía popular ''El mundo al revés''.', 'Siglo XVIII d.C.', 'Flag', 'medio'),
  ('cf-trafalgar', 'conflictos', 'Batalla naval de Trafalgar en las costas de Cádiz', 1805, 'Nelson revolucionó las tácticas navales cortando en dos columnas perpendiculares la línea combinada hispano-francesa de buques de línea.', 'Antes del combate izó en el HMS Victory el célebre mensaje de banderas: ''Inglaterra espera que cada hombre cumpla con su deber''. Murió por un balazo en cubierta.', 'Siglo XIX d.C.', 'Ship', 'medio'),
  ('cf-austerlitz', 'conflictos', 'Batalla de Austerlitz (de los Tres Emperadores)', 1805, 'La obra maestra táctica de Napoleón: fingió debilidad en su flanco derecho para atraer a los aliados y partió su centro lanzando el asalto a la meseta de Pratzen.', 'El famoso ''Sol de Austerlitz'' rasgó la densa niebla matinal exactamente en el momento en que las divisiones francesas del mariscal Soult iniciaron la carga.', 'Siglo XIX d.C.', 'Sun', 'medio'),
  ('cf-borodino', 'conflictos', 'Batalla de Borodino a las puertas de Moscú', 1812, 'La jornada más sangrienta de todas las Guerras Napoleónicas con más de 70.000 bajas en un solo día de bombardeos incesantes de artillería en el río Moscova.', 'Aunque Napoleón ocupó el campo y entró en Moscú, los rusos incendiaron su propia capital obligando a la catastrófica retirada invernal de la Grande Armée.', 'Siglo XIX d.C.', 'Flame', 'medio'),
  ('cf-leipzig', 'conflictos', 'Batalla de las Naciones en Leipzig', 1813, 'El mayor enfrentamiento armado previo a la Primera Guerra Mundial con más de medio millón de combatientes de Rusia, Prusia, Austria y Suecia.', 'La voladura accidental del puente sobre el río Elster dejó atrapados a 30.000 soldados franceses forzando la primera abdicación de Napoleón.', 'Siglo XIX d.C.', 'Globe', 'medio'),
  ('cf-waterloo', 'conflictos', 'Batalla de Waterloo y la caída final de Napoleón', 1815, 'Los cuadros de infantería británica resistieron las desesperadas cargas de caballería del mariscal Ney hasta que el ejército prusiano llegó al anochecer.', 'El suelo empapado de barro retrasó el inicio del ataque de Napoleón en cuatro preciosas horas, tiempo suficiente para que los refuerzos prusianos arribaran.', 'Siglo XIX d.C.', 'Swords', 'medio'),
  ('cf-alamo', 'conflictos', 'Asedio y Batalla de El Álamo en Texas', 1836, 'Menos de 200 defensores texanos resistieron durante trece días dentro de la antigua misión franciscana frente a miles de soldados mexicanos.', 'El grito de guerra ''¡Recuerden El Álamo!'' motivó pocas semanas después la captura de Santa Anna en la decisiva Batalla de San Jacinto.', 'Siglo XIX d.C.', 'Castle', 'medio'),
  ('cf-gettysburg', 'conflictos', 'Batalla de Gettysburg y la Carga de Pickett', 1863, 'Punto de inflexión de la Guerra de Secesión estadounidense; el Ejército de la Unión frenó la invasión confederada al norte en Pensilvania.', 'Meses después Abraham Lincoln pronunció allí el inmortal Discurso de Gettysburg dedicando el cementerio militar en solo dos minutos.', 'Siglo XIX d.C.', 'Flag', 'medio'),
  ('cf-sedan', 'conflictos', 'Batalla de Sedán y caída del Segundo Imperio Francés', 1870, 'La superior artillería pesada Krupp de Prusia rodeó a las fuerzas francesas capturando al mismísimo emperador Napoleón III con más de 100.000 hombres.', 'Esta aplastante victoria desembocó meses después en la proclamación del Imperio Alemán en la Galería de los Espejos de Versalles.', 'Siglo XIX d.C.', 'Crown', 'medio'),
  ('cf-tsushima', 'conflictos', 'Batalla naval de Tsushima en el estrecho de Corea', 1905, 'La armada japonesa aniquiló a la Flota rusa del Báltico que había navegado más de 30.000 kilómetros alrededor de África para ser emboscada.', 'Fue la primera vez en la era moderna que una potencia asiática derrotó militarmente a un imperio europeo de primera línea.', 'Siglo XX d.C.', 'Ship', 'medio'),
  ('cf-marne', 'conflictos', 'Primera Batalla del Marne y los taxis de París', 1914, 'El contraataque aliado frenó el plan Schlieffen alemán a solo 40 kilómetros de París, obligando a ambos ejércitos a atrincherarse durante cuatro años.', 'El gobernador militar de París requisó 600 taxis parisinos Renault para transportar con urgencia a miles de soldados de infantería al frente.', 'Siglo XX d.C.', 'Car', 'medio'),
  ('cf-verdun', 'conflictos', 'Batalla de Verdún y el lema ¡No pasarán!', 1916, 'El enfrentamiento más largo de la Gran Guerra (300 días) concebido para ''desangrar'' al ejército francés con más de 40 millones de proyectiles de artillería.', 'La ''Voie Sacrée'' (Vía Sagrada) fue una carretera donde un camión militar pasaba cada 14 segundos día y noche para abastecer a la guarnición.', 'Siglo XX d.C.', 'ShieldAlert', 'medio'),
  ('cf-somme', 'conflictos', 'Batalla del Somme y el debut del tanque blindado', 1916, 'Ofensiva masiva británica y francesa que provocó más de un millón de bajas; vio el primer uso de tanques de combate blindados en la historia humana.', 'En su primer día el ejército británico sufrió 57.470 bajas, la jornada más sangrienta de toda la historia militar de Gran Bretaña.', 'Siglo XX d.C.', 'AlertTriangle', 'medio'),
  ('cf-batalla-inglaterra', 'conflictos', 'Batalla de Inglaterra en los cielos británicos', 1940, 'Primera campaña militar disputada exclusivamente en el aire; los cazas británicos guiados por radar frustraron los planes nazis de invadir Gran Bretaña.', 'Churchill les dedicó la inmortal frase: ''Nunca en el campo de los conflictos humanos tantos debieron tanto a tan pocos''.', 'Siglo XX d.C.', 'Plane', 'medio'),
  ('cf-midway', 'conflictos', 'Batalla naval de Midway en el Pacífico', 1942, 'Los bombarderos en picado Dauntless de EE.UU. hundieron cuatro portaviones pesados de la flota imperial japonesa en apenas seis minutos de combate.', 'Los criptoanalistas estadounidenses descifraron el código naval secreto ''JN-25'' simulando una falsa avería de agua potable en Midway para confirmar el objetivo.', 'Siglo XX d.C.', 'Ship', 'medio'),
  ('cf-stalingrado', 'conflictos', 'Batalla de Stalingrado y el cerco al VI Ejército', 1942, 'Brutal guerra urbana casa por casa en las ruinas de la ciudad del Volga culminada por la Operación Urano que embolsó a 300.000 soldados nazis.', 'La famosa ''Casa de Pávlov'' fue defendida por un puñado de soldados soviéticos durante casi dos meses; en los mapas alemanes figuraba marcada como fortaleza.', 'Siglo XX d.C.', 'Snowflake', 'medio'),
  ('cf-el-alamein', 'conflictos', 'Segunda Batalla de El Alamein en Egipto', 1942, 'El VIII Ejército británico rompió las densas líneas defensivas de campos de minas ítalo-alemanas alejando para siempre la amenaza sobre el Canal de Suez.', 'Churchill escribió: ''Antes de El Alamein no tuvimos una sola victoria; después de El Alamein jamás sufrimos una derrota''.', 'Siglo XX d.C.', 'Sun', 'medio'),
  ('cf-kursk', 'conflictos', 'Batalla de Kursk y el mayor choque de blindados', 1943, 'En el saliente de Kursk chocaron más de dos millones de hombres y 6.000 tanques de guerra (T-34 soviéticos contra Tiger y Panther alemanes).', 'Los soviéticos construyeron ocho cinturones defensivos escalonados con más de un millón de minas antitanque enterradas antes del asalto.', 'Siglo XX d.C.', 'Shield', 'medio'),
  ('cf-dia-d-normandia', 'conflictos', 'Desembarco de Normandía (Día D y Operación Overlord)', 1944, 'La mayor invasión anfibia de la historia militar: 156.000 soldados aliados cruzaron el canal de la Mancha desembarcando en cinco playas francesas.', 'Los aliados crearon un ejército fantasma falso comandado por el general Patton con tanques inflables y transmisiones falsas para engañar al alto mando alemán.', 'Siglo XX d.C.', 'Anchor', 'medio'),
  ('cf-iwo-jima', 'conflictos', 'Batalla de Iwo Jima y la bandera en el Monte Suribachi', 1945, 'Cinco semanas de sangrientos combates en túneles subterráneos volcánicos por una pequeña isla clave para las escoltas aéreas hacia Tokio.', 'La histórica fotografía de Joe Rosenthal izando la bandera de las barras y estrellas en la cumbre se convirtió en el icono inmortal del Cuerpo de Marines.', 'Siglo XX d.C.', 'Award', 'medio'),
  ('cf-dien-bien-phu', 'conflictos', 'Batalla y Asedio de Dien Bien Phu en Indochina', 1954, 'Las tropas del Viet Minh subieron cañones pesados a mano a través de empinadas montañas selváticas sitiando la base aerotransportada francesa.', 'La capitulación de la guarnición francesa selló el fin del dominio colonial francés en el sudeste asiático y la partición de Vietnam.', 'Siglo XX d.C.', 'Mountain', 'medio'),
  ('ex-hanno-africa', 'exploraciones', 'Periplo de Hannón el Navegante por África', -500, 'Comandó una flota de 60 barcos cruzando las Columnas de Hércules (Gibraltar) para cartografiar la costa atlántica de África hasta el Golfo de Guinea.', 'Describió una colosal montaña volcánica en erupción que los cartagineses bautizaron como ''El Carro de los Dioses'', posiblemente el Monte Camerún.', 'Siglo V a.C.', 'Ship', 'medio'),
  ('ex-piteas-tule', 'exploraciones', 'Viaje de Piteas de Masalia hacia el Ártico y Tule', -325, 'Geógrafo griego que circunnavegó Gran Bretaña y navegó hacia el norte helado descubriendo la mítica isla de Tule donde el sol no se pone en verano.', 'Fue el primer explorador documentado en describir el sol de medianoche y el fenómeno del mar cubierto por densa banquisa de hielo flotante.', 'Siglo IV a.C.', 'Compass', 'medio'),
  ('ex-zhang-qian-seda', 'exploraciones', 'Expediciones de Zhang Qian y la Ruta de la Seda', -138, 'Enviado imperial que cruzó desiertos y cordilleras de Asia Central abriendo las rutas de comercio que conectaron para siempre a China con el mundo grecorromano.', 'Fue capturado por la confederación nómada Xiongnu y mantenido cautivo durante diez años, pero jamás abandonó su misión exploratoria.', 'Siglo II a.C.', 'Footprints', 'medio'),
  ('ex-erik-rojo-groenlandia', 'exploraciones', 'Colonización de Groenlandia por Erik el Rojo', 982, 'Desterrado de Islandia, navegó hacia el oeste helado y fundó los primeros asentamientos nórdicos en los fiordos suroccidentales de la gran isla.', 'La bautizó astutamente como ''Grønland'' (Tierra Verde) como reclamo publicitario para atraer a colonos vikingos a radicarse allí.', 'Siglo X d.C.', 'Anchor', 'medio'),
  ('ex-leif-erikson-vinland', 'exploraciones', 'Llegada de Leif Erikson a América (Vinland)', 1000, 'El navegante vikingo alcanzó las costas de Terranova en la actual Canadá, erigiendo el campamento de L''Anse aux Meadows casi cinco siglos antes que Colón.', 'La llamó ''Vinland'' (Tierra del Vino o de los Pastos) tras encontrar viñas y frutos silvestres en sus fértiles valles costeros.', 'Siglo X d.C.', 'Ship', 'medio'),
  ('ex-benjamin-tudela', 'exploraciones', 'Gran viaje de Benjamín de Tudela a Oriente', 1165, 'Viajero hispano-judío de Navarra que recorrió el Mediterráneo, Constantinopla, Bagdad y Persia documentando con precisión la vida urbana y comercial medieval.', 'Su ''Libro de Viajes'' precedió en más de un siglo a las crónicas de Marco Polo y es una de las fuentes demográficas más valiosas del siglo XII.', 'Siglo XII d.C.', 'BookOpen', 'medio'),
  ('ex-marco-polo-china', 'exploraciones', 'Marco Polo inicia su viaje a la corte de Kublai Kan', 1271, 'Mercader veneciano de 17 años que recorrió la Ruta de la Seda durante 24 años viviendo al servicio del Gran Kan en Pekín y las costas del sudeste asiático.', 'Dictó ''El libro de las maravillas'' en una prisión genovesa a su compañero de celda Rustichello de Pisa.', 'Siglo XIII d.C.', 'Compass', 'medio'),
  ('ex-ibn-battuta', 'exploraciones', 'Ibn Battuta inicia 30 años de travesía mundial', 1325, 'El mayor viajero del mundo premoderno recorrió más de 117.000 kilómetros a través de 44 países modernos desde el Sahara y La Meca hasta la India y China.', 'Partió de Marruecos a los 21 años solo con la intención de realizar la peregrinación del Hajj y no regresó a casa hasta casi tres décadas después.', 'Siglo XIV d.C.', 'Footprints', 'medio'),
  ('ex-zheng-he-flota-tesoro', 'exploraciones', 'Zarpa la colosal Flota del Tesoro de Zheng He', 1405, 'Armada china de más de 300 navíos colosales de nueve mástiles (barcos tesoro de 120 metros) que exploró el Océano Índico, Arabia y África oriental.', 'Zheng He llevó de vuelta a la Ciudad Prohibida de Pekín animales exóticos nunca vistos en China como cebras y jirafas, recibidas como quílines sagrados.', 'Siglo XV d.C.', 'Ship', 'medio'),
  ('ex-enrique-navegante-sagres', 'exploraciones', 'Fundación de la Escuela de Navegación de Sagres', 1419, 'Centro pionero portugués en el Cabo de San Vicente que reunió a cosmógrafos, astrónomos y capitanes impulsando el diseño de la carabela atlántica.', 'A pesar de su apodo de ''El Navegante'', el infante casi nunca se hizo a la mar; su genialidad radicó en financiar y organizar sistemáticamente las expediciones.', 'Siglo XV d.C.', 'Compass', 'medio'),
  ('ex-bartolome-diaz-buena-esperanza', 'exploraciones', 'Bartolomé Díaz dobla el Cabo de Buena Esperanza', 1488, 'Navegó al extremo meridional de África tras días de tempestades demostrando que el océano Atlántico se comunicaba directamente con el Índico.', 'Díaz lo llamó inicialmente ''Cabo de las Tormentas'', pero el rey Juan II de Portugal le cambió el nombre por ''Buena Esperanza'' ante la ansiada ruta a las especias.', 'Siglo XV d.C.', 'Anchor', 'medio'),
  ('ex-colon-primer-viaje', 'exploraciones', 'Cristóbal Colón arriba a la isla de Guanahaní', 1492, 'La expedición de tres carabelas (Santa María, Pinta y Niña) cruzó el Atlántico encontrando el continente americano y cambiando para siempre la historia global.', 'El vigía Rodrigo de Triana avistó tierra a las dos de la madrugada del 12 de octubre de 1492 desde el castillo de proa de la carabela Pinta.', 'Siglo XV d.C.', 'Ship', 'medio'),
  ('ex-juan-caboto-norteamerica', 'exploraciones', 'Juan Caboto reclama Terranova para la corona inglesa', 1497, 'Navegante veneciano al servicio de Enrique VII de Inglaterra que cruzó el Atlántico norte a bordo del Matthew avistando las costas de Canadá.', 'Caboto reportó bancos de bacalao tan densos y gigantescos en Terranova que los marineros podían capturarlos simplemente arrojando canastos lastrados al mar.', 'Siglo XV d.C.', 'Compass', 'medio'),
  ('ex-vasco-da-gama-india', 'exploraciones', 'Vasco da Gama arriba a Calicut en la India', 1498, 'Completó la primera travesía marítima continua desde Europa hasta la India bordeando África, rompiendo el monopolio otomano y veneciano de las especias.', 'Al llegar a puerto, un comerciante tunecino le preguntó en castellano qué buscaban tan lejos, a lo que un marinero respondió: ''¡Venimos a buscar cristianos y especias!''.', 'Siglo XV d.C.', 'Ship', 'medio'),
  ('ex-alvares-cabral-brasil', 'exploraciones', 'Pedro Álvares Cabral avista las costas de Brasil', 1500, 'Al realizar una amplia maniobra marítima hacia el suroeste atlántico (''la volta do mar'') para evitar corrientes africanas, desembarcó en Porto Seguro.', 'Bautizó la tierra inicialmente como ''Ilha de Vera Cruz'', antes de que la riqueza del árbol del palo brasil diera nombre definitivo a la nación.', 'Siglo XV d.C.', 'Flag', 'medio'),
  ('ex-americo-vespucio-nuevo-mundo', 'exploraciones', 'Américo Vespucio identifica el ''Nuevo Mundo''', 1501, 'Exploró la costa atlántica sudamericana y dedujo por su escala continental que las tierras halladas no eran Asia sino una ''cuarta parte del mundo'' desconocida.', 'En 1507 el cartógrafo alemán Martin Waldseemüller imprimió el primer mapa universal bautizando las nuevas tierras como ''América'' en su honor.', 'Siglo XVI d.C.', 'Globe', 'medio'),
  ('ex-juan-ponce-florida', 'exploraciones', 'Ponce de León explora la costa de Florida', 1513, 'Desembarcó en la costa oriental norteamericana bautizándola como La Florida en honor a la festividad de la Pascua Florida.', 'Aunque la leyenda popular le atribuyó la búsqueda de la mítica Fuente de la Eterna Juventud, su meta primordial era descubrir nuevas tierras y oro.', 'Siglo XVI d.C.', 'Sun', 'medio'),
  ('ex-nunez-balboa-pacifico', 'exploraciones', 'Vasco Núñez de Balboa divisa el Océano Pacífico', 1513, 'Cruzó la densa selva del istmo de Panamá y divisó desde una cumbre montañosa la inmensidad del ''Mar del Sur'', tomando posesión para España con espada en mano.', 'Entró en el mar con armadura y el estandarte real hasta que el agua le cubrió las rodillas jurando defender las aguas para la corona.', 'Siglo XVI d.C.', 'Eye', 'medio'),
  ('ex-solis-rio-plata', 'exploraciones', 'Juan Díaz de Solís descubre el Río de la Plata', 1516, 'Buscando un paso interoceánico hacia las islas de las Especias, penetró en el colosal estuario sudamericano al que llamó ''Mar Dulce'' por su agua no salina.', 'Solís desembarcó en la orilla oriental y fue emboscado por indígenas charrúas a la vista de los tripulantes que aguardaban en los buques.', 'Siglo XVI d.C.', 'Compass', 'medio'),
  ('ex-magallanes-estrecho', 'exploraciones', 'Fernando de Magallanes cruza el Estrecho Austral', 1520, 'Halló el codiciado laberinto náutico entre los océanos Atlántico y Pacífico en el confín de Sudamérica, bautizando la orilla sur como ''Tierra del Fuego''.', 'Al salir a las aguas abiertas del nuevo mar tras semanas de tormentas lo encontró tan calmo y apacible que lo bautizó ''Océano Pacífico''.', 'Siglo XVI d.C.', 'Ship', 'medio'),
  ('ex-elcano-vuelta-mundo', 'exploraciones', 'Juan Sebastián Elcano culmina la Primera Vuelta al Mundo', 1522, 'Tras la muerte de Magallanes en Filipinas, Elcano guio a 18 exhaustos supervivientes en la nao Victoria de regreso a Sevilla completando la primera circunnavegación.', 'El emperador Carlos V le otorgó un escudo de armas con un globo terráqueo y el lema latino inmortal: ''Primus circumdedisti me'' (Fuiste el primero en rodearme).', 'Siglo XVI d.C.', 'Globe', 'medio'),
  ('ex-verrazzano-bahia-nueva-york', 'exploraciones', 'Giovanni da Verrazzano entra en la bahía de Nueva York', 1524, 'Navegante florentino al servicio de Francia que exploró la costa este norteamericana anclando en el estrecho que hoy cruza el puente colgante Verrazzano-Narrows.', 'Describió la bahía neoyorquina como ''un lago hermosísimo'' poblado por canoas nativas que daban la bienvenida a los marineros.', 'Siglo XVI d.C.', 'Anchor', 'medio'),
  ('ex-cabeza-de-vaca-norteamerica', 'exploraciones', 'La increíble odisea a pie de Cabeza de Vaca', 1528, 'Tras naufragar en Texas, cuatro supervivientes caminaron descalzos durante ocho años más de 8.000 km por el suroeste de Norteamérica hasta reencontrar compatriotas en México.', 'Sobrevivieron ejerciendo como curanderos y comerciantes entre tribus nativas, realizando la primera intervención quirúrgica documentada en Norteamérica.', 'Siglo XVI d.C.', 'Footprints', 'medio'),
  ('ex-jacques-cartier-san-lorenzo', 'exploraciones', 'Jacques Cartier remonta el río San Lorenzo', 1534, 'Explorador bretón que reclamó la región para el rey Francisco I de Francia navegando el río interior y visitando las aldeas iroquesas de Stadaconé y Hochelaga.', 'Interpretó la palabra hurona ''kanata'' (que significa aldea o poblado) como el nombre de toda la región, dando origen a la palabra ''Canadá''.', 'Siglo XVI d.C.', 'Compass', 'medio'),
  ('ex-coronado-gran-canon', 'exploraciones', 'Vázquez de Coronado y el hallazgo del Gran Cañón', 1540, 'Buscando las míticas Siete Ciudades de Oro de Cíbola por Nuevo México y Arizona, su capitán Cárdenas se convirtió en el primer europeo en contemplar el Gran Cañón del Colorado.', 'Los soldados intentaron descender hasta el río Colorado creyendo que medía un par de metros de ancho, pero tuvieron que regresar al comprobar su colosal abismo.', 'Siglo XVI d.C.', 'Mountain', 'medio'),
  ('ex-de-soto-misisipi', 'exploraciones', 'Hernando de Soto descubre el río Misisipi', 1541, 'Lideró una extensa expedición por el sureste de los actuales Estados Unidos cruzando por primera vez el caudaloso ''Padre de las Aguas''.', 'Cuando De Soto murió de fiebre junto al río, sus hombres lastraron su cadáver y lo hundieron a medianoche en las aguas para que los nativos creyeran que era inmortal.', 'Siglo XVI d.C.', 'Anchor', 'medio'),
  ('ex-orellana-rio-amazonas', 'exploraciones', 'Francisco de Orellana desciende y navega el río Amazonas', 1542, 'Separado de la expedición de Gonzalo Pizarro, construyó el bergantín San Pedro y recorrió miles de kilómetros por el río más caudaloso del mundo hasta el Atlántico.', 'Bautizaron el río como ''Amazonas'' tras combatir con una feroz tribu de mujeres guerreras armadas con arcos que recordaban a las amazonas de la mitología griega.', 'Siglo XVI d.C.', 'Ship', 'medio'),
  ('ex-urdangeta-tornaviaje', 'exploraciones', 'Andrés de Urdaneta halla la ruta del Tornaviaje', 1565, 'Descubrió que navegando hacia el norte de Japón la corriente de Kuroshio permitía cruzar el Pacífico de vuelta a América, inaugurando la ruta del Galeón de Manila.', 'Esta ruta marítima funcionó ininterrumpidamente durante 250 años conectando comercialmente por primera vez a Asia, América y Europa.', 'Siglo XVI d.C.', 'Compass', 'medio')
INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('ex-drake-golden-hind', 'exploraciones', 'Francis Drake completa su vuelta al mundo en el Golden Hind', 1580, 'El corsario inglés circunnavegó el planeta asaltando puertos del Pacífico español y regresó a Plymouth con un botín legendario en especias y plata.', 'La reina Isabel I de Inglaterra subió personalmente a bordo del Golden Hind en el Támesis para nombrarlo caballero tras recibir su cuota de riquezas.', 'Siglo XVI d.C.', 'Ship', 'medio'),
  ('ex-willem-barents-spitsbergen', 'exploraciones', 'Willem Barents descubre el archipiélago de Svalbard', 1596, 'Explorador holandés que buscaba el Paso del Noreste hacia China; su barco quedó atrapado en el hielo de Nueva Zembla obligándolos a construir una cabaña ártica.', 'Construyeron ''Het Behouden Huys'' (La Casa Salvada) desarmando parte de su propia nave para sobrevivir a temperaturas polares de -40 °C combatiendo osos polares.', 'Siglo XVI d.C.', 'Snowflake', 'medio'),
  ('ex-champlain-fundacion-quebec', 'exploraciones', 'Samuel de Champlain funda Quebec y explora los Grandes Lagos', 1608, 'Cartógrafo y explorador que estableció la colonia de Quebec y navegó en canoas indígenas por el lago Hurón y el lago Ontario trazando mapas minuciosos.', 'Descubrió el gran lago que hoy lleva su nombre (Lago Champlain) en la frontera entre Canadá y los Estados Unidos.', 'Siglo XVII d.C.', 'Map', 'medio'),
  ('ex-henry-hudson-bahia', 'exploraciones', 'Henry Hudson explora la inmensa Bahía de Hudson', 1610, 'Navegó por el estrecho y mar interior más grande de Norteamérica creyendo haber encontrado el ansiado paso marítimo navegable hacia Asia.', 'Al quedar atrapados por el hielo invernal la tripulación amotinada lo abandonó en un pequeño bote abierto en medio de las gélidas aguas junto a su hijo adolescente.', 'Siglo XVII d.C.', 'Compass', 'medio'),
  ('ex-abel-tasman-australasia', 'exploraciones', 'Abel Tasman descubre Tasmania y Nueva Zelanda', 1642, 'Comandó los buques Heemskerck y Zeehaen circunnavegando Australia sin verla de frente y convirtiéndose en el primer europeo en avistar las islas neozelandesas.', 'Bautizó inicialmente a la isla como ''Tierra de Van Diemen'' en honor al gobernador colonial que patrocinó su arriesgada expedición marítima.', 'Siglo XVII d.C.', 'Ship', 'medio'),
  ('ex-vitus-bering-estrecho', 'exploraciones', 'Vitus Bering navega el estrecho entre Asia y América', 1728, 'Navegante danés al servicio de la corona rusa que demostró que Siberia y América del Norte no estaban unidas por tierra firme navegando por el estrecho que lleva su nombre.', 'Tardó varios años cruzando a pie y en trineo toda la inmensa taiga siberiana solo para llegar a la costa y empezar a construir los barcos de la misión.', 'Siglo XVIII d.C.', 'Compass', 'medio'),
  ('ex-james-cook-primer-viaje', 'exploraciones', 'El Capitán James Cook cartografía Australia y Nueva Zelanda', 1770, 'A bordo del HMS Endeavour observó el tránsito de Venus en Tahití y cartografió minuciosamente las dos islas de Nueva Zelanda y la costa oriental de Australia.', 'El Endeavour encalló casi fatalmente en la Gran Barrera de Coral teniendo que arrojar cañones por la borda para aligerar peso y salvar la nave.', 'Siglo XVIII d.C.', 'Ship', 'medio'),
  ('ex-cook-circulo-antartico', 'exploraciones', 'James Cook cruza por primera vez el Círculo Polar Antártico', 1773, 'Penetró en los mares helados del sur alcanzando los 71° de latitud sur rodeado de icebergs colosales, desmintiendo la existencia de un continente fértil austral habitable.', 'Gracias al uso estricto de chucrut fermentado, cítricos y limpieza a bordo, Cook no perdió a un solo marinero por escorbuto en toda la travesía.', 'Siglo XVIII d.C.', 'Snowflake', 'medio'),
  ('ex-la-perouse-pacifico', 'exploraciones', 'La gran expedición científica de La Pérouse por el Pacífico', 1785, 'Misión enciclopédica francesa encargada por Luis XVI con dos fragatas repletas de naturalistas que recorrió Alaska, Hawái, Japón y Australia antes de desaparecer.', 'El rey Luis XVI, momentos antes de subir a la guillotina en 1793, preguntó a sus guardias: ''¿Se tienen noticias del señor de La Pérouse?''.', 'Siglo XVIII d.C.', 'Compass', 'medio'),
  ('ex-malaspina-expedicion', 'exploraciones', 'La Expedición científica de Malaspina alrededor del mundo', 1789, 'Viaje ilustrado de cinco años en las corbetas Descubierta y Atrevida que recopiló la mayor colección botánica, hidrográfica y artística del imperio hispano.', 'A su regreso a Madrid las intrigas palaciegas provocaron el encarcelamiento de Malaspina y la censura de sus minuciosos informes políticos durante décadas.', 'Siglo XVIII d.C.', 'BookOpen', 'medio'),
  ('ex-alexander-mackenzie-pacifico', 'exploraciones', 'Alexander Mackenzie cruza Norteamérica por tierra', 1793, 'Primer europeo en cruzar a pie y en canoa todo el continente norteamericano al norte de México hasta las costas del océano Pacífico en la Columbia Británica.', 'Pintó con bermellón y grasa de oso en una roca marina: ''Alex Mackenzie de Canadá por tierra, el veintidós de julio de mil setecientos noventa y tres''.', 'Siglo XVIII d.C.', 'Footprints', 'medio'),
  ('ex-humboldt-america', 'exploraciones', 'Alexander von Humboldt inicia su expedición americana', 1799, 'Viaje científico pionero de cinco años por Venezuela, Cuba, Colombia, Ecuador, Perú y México que fundó la biogeografía y la visión ecológica moderna de la Tierra.', 'Ascendió el volcán Chimborazo hasta los 5.875 metros sin equipo de oxígeno moderno, estableciendo el récord mundial de altitud para su época.', 'Siglo XVIII d.C.', 'Mountain', 'medio'),
  ('ex-lewis-clark-expedicion', 'exploraciones', 'La Expedición de Lewis y Clark hacia el Pacífico', 1804, 'Comisionados por Thomas Jefferson tras la compra de Luisiana, recorrieron 13.000 kilómetros inexplorados guiados por la valiente intérprete shoshone Sacagawea.', 'Clark escribió en su diario al avistar el océano en Oregón: ''¡Océano a la vista! ¡Oh! El gozo''.', 'Siglo XIX d.C.', 'Compass', 'medio'),
  ('ex-bellinghausen-antartida', 'exploraciones', 'Fabian von Bellingshausen avista el continente Antártico', 1820, 'La expedición imperial rusa avistó por primera vez la barrera de hielo continental de la Antártida circunnavegando todo el casquete polar austral.', 'Fue el primer explorador en completar una vuelta al mundo polar antártica después de James Cook medio siglo antes.', 'Siglo XIX d.C.', 'Snowflake', 'medio'),
  ('ex-darwin-beagle', 'exploraciones', 'Charles Darwin zarpa en el viaje del HMS Beagle', 1831, 'Travesía científica de cinco años alrededor del globo donde sus observaciones de fósiles y pinzones en las Islas Galápagos engendraron la Teoría de la Evolución.', 'Darwin sufrió de mareos crónicos incapacitantes durante casi todos los días que el barco estuvo en altamar.', 'Siglo XIX d.C.', 'Eye', 'medio'),
  ('ex-ross-barrera-antartica', 'exploraciones', 'James Clark Ross descubre la Gran Barrera de Hielo Antártica', 1841, 'Buscando el Polo Sur magnético penetró en el mar que hoy lleva su nombre descubriendo dos volcanes antárticos a los que bautizó con el nombre de sus navíos.', 'El volcán Monte Erebus es el volcán activo más austral de la Tierra y cuenta con un lago permanente de lava hirviendo en su cráter helado.', 'Siglo XIX d.C.', 'Flame', 'medio'),
  ('ex-franklin-paso-noroeste', 'exploraciones', 'La trágica expedición perdida de Sir John Franklin', 1845, 'Los buques HMS Erebus y Terror quedaron atrapados en la banquisa cerca de la isla Rey Guillermo; todos los hombres perecieron intentando caminar sobre el hielo.', 'La búsqueda desesperada de Franklin durante décadas por decenas de misiones de rescate terminó cartografiando casi todo el Ártico canadiense.', 'Siglo XIX d.C.', 'AlertTriangle', 'medio'),
  ('ex-livingstone-cataratas-victoria', 'exploraciones', 'David Livingstone contempla las Cataratas Victoria', 1855, 'Misionero y explorador escocés que remontó el río Zambeze siendo el primer europeo en contemplar la atronadora catarata bautizada en honor a la reina británica.', 'El pueblo local Kololo las llamaba ''Mosi-oa-Tunya'' (El humo que truena); Livingstone escribió que ''escenas tan hermosas debieron ser contempladas por ángeles en su vuelo''.', 'Siglo XIX d.C.', 'Compass', 'medio'),
  ('ex-burton-speke-tanganica', 'exploraciones', 'Richard Burton y John Speke buscan las fuentes del Nilo', 1858, 'Cruzaron el África oriental diezmados por fiebres tropicales descubriendo el lago Tanganica; Speke avanzó al norte avistando en solitario el inmenso lago Victoria.', 'El enigma milenario de dónde nacía el río Nilo desató una enconada y trágica rivalidad científica entre ambos exploradores británicos en Londres.', 'Siglo XIX d.C.', 'Compass', 'medio'),
  ('ex-burke-wills-australia', 'exploraciones', 'Expedición de Burke y Wills a través del desierto australiano', 1860, 'La primera expedición en cruzar Australia de sur a norte desde Melbourne hasta el Golfo de Carpentaria con camellos importados de la India.', 'En su regreso exhaustos alcanzaron el campamento base de Cooper Creek solo nueve horas después de que el grupo de apoyo se marchara creyéndolos muertos.', 'Siglo XIX d.C.', 'Footprints', 'medio'),
  ('ex-stanley-livingstone-tanganica', 'exploraciones', 'Encuentro de Stanley y Livingstone: ''¿El doctor Livingstone, supongo?''', 1871, 'El periodista del New York Herald encontró al célebre explorador tras años desaparecido en el corazón de África, pronunciando el saludo más famoso de la historia.', 'Stanley se quitó educadamente su salacot colonial en medio de la jungla saludando con flema victoriana al único hombre blanco en miles de kilómetros a la redonda.', 'Siglo XIX d.C.', 'Heart', 'medio'),
  ('ex-challenger-oceanografia', 'exploraciones', 'La expedición del HMS Challenger funda la oceanografía', 1872, 'Navegó 130.000 kilómetros por todos los océanos utilizando kilómetros de cables de cáñamo para sondear las profundidades abisales y catalogar 4.700 nuevas especies marinas.', 'Descubrió la Fosa de las Marianas y la ''Fosa Challenger'', desmintiendo la creencia de que a gran profundidad reinaba una zona desierta sin vida.', 'Siglo XIX d.C.', 'Ship', 'medio'),
  ('ex-nordenskiold-paso-nordeste', 'exploraciones', 'Nordenskiöld completa por primera vez el Paso del Nordeste', 1878, 'El explorador sueco-finlandés navegó a lo largo de toda la costa ártica siberiana saliendo por el estrecho de Bering tras pasar un invierno atrapado en el hielo.', 'Fue la primera vez en la historia de la navegación que un buque conectó el océano Atlántico y el Pacífico a través del mar polar septentrional de Eurasia.', 'Siglo XIX d.C.', 'Compass', 'medio'),
  ('ex-nansen-fram-deriva', 'exploraciones', 'Fridtjof Nansen y la épica deriva del buque Fram en el hielo', 1893, 'Diseñó un barco con casco redondo para no ser aplastado por los hielos, congelándose deliberadamente en la banquisa para derivar hacia el Polo Norte.', 'Al ver que el barco no pasaba por el polo, Nansen y Johansen partieron a pie con esquís y trineos de perros sobreviviendo al invierno ártico comiendo carne de morsa.', 'Siglo XIX d.C.', 'Snowflake', 'medio'),
  ('ex-peary-polo-norte', 'exploraciones', 'Robert Peary y Matthew Henson reclaman el Polo Norte', 1909, 'Afirmaron haber alcanzado el Polo Norte geográfico a pie sobre la banquisa con trineos tirados por perros esquimales acompañados por cuatro nativos inuit.', 'Matthew Henson, un afroamericano experto en supervivencia ártica y lengua inuktitut, fue quien realmente colocó la bandera en el punto acordado.', 'Siglo XX d.C.', 'Flag', 'medio'),
  ('ex-amundsen-polo-sur', 'exploraciones', 'Roald Amundsen conquista el Polo Sur geográfico', 1911, 'Planificación magistral utilizando esquís, trineos con perros de Groenlandia y ropa tradicional de piel de reno para llegar primero al punto más austral de la Tierra.', 'Plantó la bandera noruega en su tienda de campaña ''Polheim'' dejando una respetuosa carta dirigida a su rival británico Robert Falcon Scott.', 'Siglo XX d.C.', 'Flag', 'medio'),
  ('ex-scott-polo-sur', 'exploraciones', 'La expedición Terra Nova de Robert Falcon Scott al Polo Sur', 1912, 'Llegaron al Polo Sur 34 días después que Amundsen encontrando la bandera rival; en su regreso a pie perecieron todos atrapados por una tempestad helada.', 'En su tienda final se hallaron sus diarios donde Scott escribió con mano firme en sus últimos minutos: ''Por el amor de Dios, cuiden de nuestra gente''.', 'Siglo XX d.C.', 'AlertTriangle', 'medio'),
  ('ex-shackleton-endurance', 'exploraciones', 'La odisea de supervivencia del Endurance de Shackleton', 1914, 'Su barco fue triturado por el hielo antártico; lideró una travesía épica en un bote de remos de siete metros por 1.300 km de mares embravecidos sin perder un solo hombre.', 'Su anuncio de reclutamiento decía: ''Se buscan hombres para viaje peligroso. Sueldos bajos, frío extremo, largos meses de completa oscuridad. Retorno dudoso''.', 'Siglo XX d.C.', 'Ship', 'medio'),
  ('ex-hillary-norgay-everest', 'exploraciones', 'Edmund Hillary y Tenzing Norgay coronan el Monte Everest', 1953, 'Primeros montañistas en pisar la cima del ''Techo del Mundo'' a 8.848 metros de altitud en la cordillera del Himalaya.', 'En la cumbre pasaron apenas quince minutos sacando fotos; Tenzing enterró en la nieve una ofrenda budista de galletas y chocolate.', 'Siglo XX d.C.', 'Mountain', 'medio'),
  ('ex-piccard-walsh-marianas', 'exploraciones', 'Descenso al abismo de las Marianas en el batiscafo Trieste', 1960, 'Descendieron a casi 11.000 metros de profundidad en el Abismo Challenger soportando una presión hidrostática aplastante de más de mil atmósferas.', 'Al tocar el lecho marino iluminaron con sus reflectores y descubrieron con asombro un pez plano vivo demostrando que la vida prospera incluso en el punto más profundo de la Tierra.', 'Siglo XX d.C.', 'Anchor', 'medio'),
  ('ex-yuri-gagarin-vostok', 'exploraciones', 'Yuri Gagarin se convierte en el primer hombre en el espacio', 1961, 'Completó una órbita completa alrededor del planeta Tierra en 108 minutos inaugurando la era de la exploración espacial humana.', 'Al contemplar nuestro planeta desde la ventriloquia de su cápsula exclamó con emoción: ''¡La Tierra es azul! ¡Qué maravillosa es!''.', 'Siglo XX d.C.', 'Rocket', 'medio'),
  ('ex-armstrong-alunizaje', 'exploraciones', 'Neil Armstrong y Buzz Aldrin pisan la Luna (Apolo 11)', 1969, 'El módulo lunar ''Eagle'' se posó en el Mar de la Tranquilidad ante la mirada de 600 millones de espectadores en televisión.', 'Al apoyar su bota izquierda en el polvo lunar Armstrong pronunció: ''Es un pequeño paso para un hombre, pero un gran salto para la humanidad''.', 'Siglo XX d.C.', 'Moon', 'medio'),
  ('ex-ballard-titanic', 'exploraciones', 'Robert Ballard localiza los restos sumergidos del Titanic', 1985, 'Con el robot submarino ''Argo'' halló el transatlántico partido en dos a 3.800 metros de profundidad en el Atlántico Norte tras 73 años de misterio.', 'La expedición fue una tapadera oficial de la Marina de EE.UU. que en realidad buscaba investigar dos submarinos nucleares hundidos durante la Guerra Fría.', 'Siglo XX d.C.', 'Ship', 'medio'),
  ('ex-voyager-1-interestelar', 'exploraciones', 'La sonda Voyager 1 cruza hacia el espacio interestelar', 2012, 'El objeto fabricado por el ser humano más lejano de la historia atravesó la heliopausa abandonando la influencia del viento de nuestro Sol.', 'Porta en su estructura el ''Disco de Oro'' con sonidos, saludos en 55 idiomas humanos y música de Bach, Beethoven y Chuck Berry para posibles civilizaciones estelares.', 'Siglo XXI d.C.', 'Rocket', 'medio'),
  ('ar-epopeya-gilgamesh', 'arte', 'Grabación de la Epopeya de Gilgamesh en arcilla', -2100, 'La obra maestra literaria más antigua conocida de la humanidad narra la búsqueda de la inmortalidad y la amistad entre el rey Gilgamesh y Enkidu.', 'Contiene el relato de Utnapishtim sobre el diluvio universal milenario grabado en escritura cuneiforme doce siglos antes de Homero.', 'Siglo XXI a.C.', 'Scroll', 'medio'),
  ('ar-iliada-odisea-homero', 'arte', 'Composición de la Ilíada y la Odisea por Homero', -750, 'Los dos grandes poemas épicos fundacionales de la literatura occidental que inmortalizaron la cólera de Aquiles en Troya y el regreso de Odiseo a Ítaca.', 'Durante siglos no se escribieron sino que se memorizaban y cantaban de viva voz con lira por aedos y rapsodas en banquetes griegos.', 'Siglo VIII a.C.', 'BookOpen', 'medio'),
  ('ar-teogonia-hesiodo', 'arte', 'Composición de la Teogonía de Hesíodo', -700, 'Poema fundamental que sistematizó la mitología griega relatando el origen del cosmos desde el Caos primordial hasta el triunfo de Zeus sobre los Titanes.', 'Hesíodo afirmó que las nueve Musas se le aparecieron en persona mientras pastoreaba sus ovejas al pie del Monte Helicón inspirándole sus versos.', 'Siglo VII a.C.', 'Sparkles', 'medio'),
  ('ar-taoteching-laotse', 'arte', 'Redacción del Dào Dé Jīng por Lao-Tse', -550, 'Texto fundamental de la filosofía oriental y del taoísmo compuesto por 81 capítulos poéticos sobre el flujo natural del Tao y el principio del ''Wu Wei''.', 'Según la tradición china, Lao-Tse escribió el libro en la puerta fronteriza occidental antes de marcharse cabalgando sobre un buey azul hacia lo desconocido.', 'Siglo VI a.C.', 'BookOpen', 'medio'),
  ('ar-analectas-confucio', 'arte', 'Compilación de las Analectas de Confucio', -500, 'Máximas y diálogos éticos sobre la benevolencia (Ren), la piedad filial y la rectitud moral que moldearon durante dos milenios la civilización asiática.', 'Enseñó la famosa Regla de Oro ética cinco siglos antes de Cristo: ''No hagas a los demás lo que no quieras que te hagan a ti''.', 'Siglo V a.C.', 'Scroll', 'medio'),
  ('ar-tragedia-edipo-sofocles', 'arte', 'Estreno de ''Edipo Rey'' de Sófocles en Atenas', -429, 'La cumbre de la tragedia clásica griega que explora el destino inexorable, la verdad dolorosa y la ceguera humana en el Teatro de Dioniso.', 'Aristóteles la calificó en su Poética como la obra dramática más perfecta jamás escrita por su magistral estructura de peripecia y anagnórisis.', 'Siglo V a.C.', 'Theater', 'medio'),
  ('ar-republica-platon', 'arte', 'Platón escribe ''La República'' y el Mito de la Caverna', -375, 'Diálogo filosófico maestro sobre la justicia, el Estado ideal gobernado por filósofos y la alegoría de prisioneros que solo ven sombras proyectadas.', 'Platón fundó la Academia de Atenas a la entrada de un olivar consagrado al héroe Academo; en su dintel se leía: ''No entre nadie que no sepa geometría''.', 'Siglo IV a.C.', 'BookOpen', 'medio'),
  ('ar-etica-nicomaco-aristoteles', 'arte', 'Aristóteles redacta la ''Ética a Nicómaco''', -340, 'Tratado medular sobre la felicidad (eudaimonía) y la teoría de la virtud entendida como el justo término medio entre dos extremos viciosos.', 'Fue dedicada a su hijo Nicómaco; Aristóteles enseñaba caminando con sus alumnos por los jardines del Liceo, por lo que fueron llamados ''peripatéticos''.', 'Siglo IV a.C.', 'BookOpen', 'medio'),
  ('ar-venus-milo', 'arte', 'Escultura de la Afrodita de Milos (Venus de Milo)', -130, 'Estatua helenística esculpida en mármol de Paros hallada semienterrada en la isla egea de Milos, paradigma de la belleza escultórica clásica.', 'Sus brazos originales se perdieron en una disputa entre marineros franceses y turcos mientras intentaban embarcar la escultura en la playa en 1820.', 'Siglo II a.C.', 'Palette', 'medio'),
  ('ar-eneida-virgilio', 'arte', 'Virgilio culmina la composición de la Eneida', -19, 'Epopeya nacional romana que narra el escape del príncipe troyano Eneas tras la caída de Troya para fundar la estirpe que engendraría a Roma.', 'Virgilio pidió en su lecho de muerte que quemaran el manuscrito por considerarlo incompleto, pero el emperador Augusto prohibió destruir la obra de arte.', 'Siglo I a.C.', 'Scroll', 'medio'),
  ('ar-metamorfosis-ovidio', 'arte', 'Publicación de ''Las Metamorfosis'' de Ovidio', 8, 'Monumento poético de quince libros en hexámetros latinos que compila más de 250 mitos clásicos de transformación desde el Caos hasta Julio César.', 'Poco después de terminarla, el emperador Augusto desterró a Ovidio a la remota Tomis en el Mar Negro por ''un poema y un error'' que jamás reveló.', 'Siglo I d.C.', 'Sparkles', 'medio'),
  ('ar-cartas-lucilio-seneca', 'arte', 'Séneca escribe las ''Epístolas Morales a Lucilio''', 65, 'Colección de 124 cartas que constituye el manual práctico más humano y elocuente del estoicismo romano sobre el tiempo, la serenidad y la muerte.', 'Séneca escribió estas reflexiones mientras el emperador Nerón, su antiguo alumno, lo acorralaba políticamente hasta ordenarle el suicidio forzoso.', 'Siglo I d.C.', 'BookOpen', 'medio'),
  ('ar-meditaciones-marco-aurelio', 'arte', 'Marco Aurelio escribe sus ''Meditaciones'' en el Danubio', 180, 'Diario íntimo espiritual en griego antiguo (''A sí mismo'') redactado a la luz de las antorchas en tiendas de campaña militares durante las Guerras Marcomanas.', 'Jamás estuvo destinado a ser publicado; era un diálogo privado consigo mismo para no dejarse corromper por el poder absoluto del Imperio.', 'Siglo II d.C.', 'BookOpen', 'medio'),
  ('ar-confesiones-agustin', 'arte', 'San Agustín de Hipona escribe las ''Confesiones''', 397, 'Primera gran autobiografía psicológica íntima de Occidente, donde examina su juventud turbulenta, su conversión cristiana y la naturaleza del tiempo.', 'Contiene la famosa paradoja temporal: ''¿Qué es el tiempo? Si nadie me lo pregunta, lo sé; pero si quiero explicárselo a quien me lo pregunta, no lo sé''.', 'Siglo IV d.C.', 'Heart', 'medio'),
  ('ar-mil-y-una-noches', 'arte', 'Compilación de ''Las Mil y Una Noches'' en Bagdad', 850, 'Monumento narrativo oriental donde la valiente Sherezade pospone su ejecución noche tras noche hilvanando cuentos como Aladino, Simbad y Alí Babá.', 'El recurso literario de encadenar historias dentro de historias (''cuento enmarcado'') influyó directamente en el Decamerón y el Quijote siglos después.', 'Siglo IX d.C.', 'Moon', 'medio'),
  ('ar-genji-monogatari', 'arte', 'Murasaki Shikibu escribe ''La historia de Genji''', 1010, 'Considerada por los críticos literarios internacionales como la primera novela psicológica moderna del mundo, retratando la vida del ''Príncipe Radiante''.', 'Fue escrita por una dama de la nobleza en caligrafía fonética japonesa ''kana'', ya que a las mujeres de la época se les prohibía aprender chino oficial.', 'Siglo XI d.C.', 'BookOpen', 'medio')
INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('ar-cantar-mio-cid', 'arte', 'Composición del ''Cantar de mio Cid'' en Castilla', 1200, 'Cantar de gesta cumbre de la épica medieval hispánica que narra las hazañas, el destierro injusto y la honra recuperada del caballero castellano.', 'El manuscrito original único que custodia la Biblioteca Nacional de España en Madrid fue copiado por un clérigo llamado Per Abbat en 1207.', 'Siglo XII d.C.', 'Shield', 'medio'),
  ('ar-suma-teologica-tomas-aquino', 'arte', 'Santo Tomás de Aquino redacta la ''Suma Teológica''', 1265, 'Monumento de la escolástica medieval que concilió armónicamente la fe cristiana con la filosofía racional de Aristóteles mediante sus ''Cinco Vías''.', 'Poco antes de morir tuvo una experiencia mística en Nápoles y dejó su pluma diciendo: ''Todo lo que he escrito me parece paja comparado con lo que he visto''.', 'Siglo XIII d.C.', 'BookOpen', 'medio'),
  ('ar-divina-comedia-dante', 'arte', 'Dante Alighieri completa ''La Divina Comedia''', 1320, 'Viaje visionario en tercetos encadenados a través del Infierno, Purgatorio y Paraíso que fijó las bases de la lengua italiana moderna y la teología poética.', 'Dante la tituló simplemente ''Commedia'' porque tenía un final feliz celestial; el adjetivo ''Divina'' fue añadido con fervor por Giovanni Boccaccio en 1555.', 'Siglo XIV d.C.', 'Crown', 'medio'),
  ('ar-decaneron-boccaccio', 'arte', 'Giovanni Boccaccio publica el ''Decamerón''', 1353, 'Cien relatos relatados durante diez días por diez jóvenes refugiados en una villa toscana mientras la Peste Negra asolaba las calles de Florencia.', 'Celebró la astucia mundana, el erotismo y el ingenio humano, rompiendo con el rígido teocentrismo e inaugurando el Humanismo renacentista.', 'Siglo XIV d.C.', 'Smile', 'medio'),
  ('ar-cuentos-canterbury-chaucer', 'arte', 'Geoffrey Chaucer escribe ''Los cuentos de Canterbury''', 1387, 'Mosaico vivo y satírico de la sociedad medieval inglesa narrado por peregrinos de todas las clases que viajan al santuario de Santo Tomás Becket.', 'Elevó el inglés medio de dialecto popular a lengua literaria culta, razón por la cual Chaucer es considerado el ''Padre de la literatura inglesa''.', 'Siglo XIV d.C.', 'BookOpen', 'medio'),
  ('ar-nacimiento-venus-botticelli', 'arte', 'Sandro Botticelli pinta ''El nacimiento de Venus''', 1485, 'Pintura al temple sobre lienzo en Florencia que representa a la diosa del amor emergiendo del mar empujada hacia la orilla sobre una concha por los Céfiros.', 'El rostro de Venus está inspirado en Simonetta Vespucci, considerada la mujer más hermosa de la Florencia renacentista que murió trágicamente a los 23 años.', 'Siglo XV d.C.', 'Palette', 'medio'),
  ('ar-ultima-cena-leonardo', 'arte', 'Leonardo da Vinci pinta ''La Última Cena'' en Milán', 1498, 'Mural magistral en el refectorio de Santa Maria delle Grazie que capta con perspectiva lineal el momento exacto en que Jesús dice: ''Uno de vosotros me traicionará''.', 'Leonardo pasaba días enteros mirando fijamente la pared sin dar una sola pincelada; cuando el prior del convento se quejó, amenazó con usar el rostro del prior para Judas.', 'Siglo XV d.C.', 'Palette', 'medio'),
  ('ar-mona-lisa-gioconda', 'arte', 'Leonardo da Vinci inicia el retrato de la ''Mona Lisa''', 1503, 'El retrato pictórico más célebre y enigmático del mundo, célebre por su técnica del ''sfumato'' y su sonrisa sutil que parece cambiar según el ángulo de observación.', 'Leonardo jamás entregó el cuadro a quien se lo encargó; viajó con él por toda Italia y Francia retocando capas microscópicas de barniz hasta su muerte.', 'Siglo XVI d.C.', 'Palette', 'medio'),
  ('ar-david-miguel-angel', 'arte', 'Miguel Ángel esculpe el colosal ''David'' en Florencia', 1504, 'Escultura en mármol de más de cinco metros que retrata a David en tensión psicológica con la honda al hombro instantes antes de arrojar la piedra contra Goliat.', 'El gigantesco bloque de mármol blanco había sido apodado ''El Gigante'' y yacía abandonado e inutilizado durante 40 años porque otros escultores lo consideraban defectuoso.', 'Siglo XVI d.C.', 'Palette', 'medio'),
  ('ar-escuela-atenas-rafael', 'arte', 'Rafael Sanzio pinta ''La Escuela de Atenas''', 1511, 'Fresco renacentista en las Estancias Vaticanas que reúne a los sabios de la antigüedad con Platón señalando hacia el cielo ideal y Aristóteles con la palma hacia la tierra terrenal.', 'Rafael usó el rostro de su contemporáneo Leonardo da Vinci para pintar a Platón y el de Miguel Ángel sentado en primer plano como Heráclito.', 'Siglo XVI d.C.', 'Palette', 'medio'),
  ('ar-boveda-sixtina', 'arte', 'Miguel Ángel devela los frescos de la Capilla Sixtina', 1512, 'Más de 500 metros cuadrados de frescos bíblicos en el techo del Vaticano culminados por el célebre ''Toque de la Creación'' entre los dedos de Dios y Adán.', 'Miguel Ángel pintó de pie sobre andamios de madera diseñados por él mismo con la cabeza inclinada hacia atrás durante cuatro extenuantes años.', 'Siglo XVI d.C.', 'Palette', 'medio'),
  ('ar-el-principe-maquiavelo', 'arte', 'Nicolás Maquiavelo redacta ''El Príncipe'' en San Casciano', 1513, 'Tratado pionero de ciencia política realista que separó la moral religiosa del ejercicio del poder estatal fundando el pragmatismo político moderno.', 'Se le atribuye popularmente la frase ''El fin justifica los medios'', aunque en realidad escribió que ''un gobernante debe aprender a no ser bueno cuando la necesidad lo exija''.', 'Siglo XVI d.C.', 'BookOpen', 'medio'),
  ('ar-utopia-tomas-moro', 'arte', 'Tomás Moro publica ''Utopía'' en Lovaina', 1516, 'Diálogo satírico y filosófico que acuñó la palabra ''Utopía'' describiendo una sociedad insular perfecta con tolerancia religiosa y sin propiedad privada.', 'El término ''Utopía'' es un juego de palabras inventado por Moro con raíces griegas que significa a la vez ''no-lugar'' (ou-topos) y ''buen lugar'' (eu-topos).', 'Siglo XVI d.C.', 'Compass', 'medio'),
  ('ar-hamlet-shakespeare', 'arte', 'William Shakespeare estrena la tragedia de ''Hamlet''', 1601, 'Obra cumbre del drama universal sobre la venganza, la locura fingida y el dilema existencial del príncipe danés ante el fantasma de su padre asesinado.', 'El célebre monólogo ''Ser o no ser, esa es la cuestión'' se pronuncia antes de la escena del cementerio con la calavera del bufón Yorick.', 'Siglo XVII d.C.', 'Theater', 'medio'),
  ('ar-don-quijote-cervantes', 'arte', 'Cervantes publica ''El ingenioso hidalgo Don Quijote de la Mancha''', 1605, 'La primera novela polifónica moderna y la obra cumbre de la lengua castellana que parodió los libros de caballerías con Don Quijote y Sancho Panza.', 'Es el libro más traducido y editado de la historia de la humanidad después de la Biblia.', 'Siglo XVII d.C.', 'BookOpen', 'medio'),
  ('ar-vida-sueno-calderon', 'arte', 'Calderón de la Barca estrena ''La vida es sueño''', 1635, 'Joya del teatro del Siglo de Oro español que aborda el libre albedrío frente al destino a través del cautiverio del príncipe Segismundo en su torre.', 'El célebre monólogo de Segismundo concluye: ''¿Qué es la vida? Una ilusión, una sombra, una ficción... que toda la vida es sueño, y los sueños, sueños son''.', 'Siglo XVII d.C.', 'Theater', 'medio'),
  ('ar-discurso-metodo-descartes', 'arte', 'Descartes publica el ''Discurso del método'' (''Pienso, luego existo'')', 1637, 'Inauguró la filosofía moderna aplicando la duda metódica radical hasta hallar la primera verdad indubitable: ''Cogito, ergo sum''.', 'Escribió el tratado en lengua francesa vernácula en lugar de latín académico para que cualquier persona con sentido común pudiera razonar sus postulados.', 'Siglo XVII d.C.', 'HelpCircle', 'medio'),
  ('ar-ronda-noche-rembrandt', 'arte', 'Rembrandt pinta la obra maestra ''La ronda de noche''', 1642, 'Revolucionó el retrato corporativo de milicias civiles holandesas con un colosal claroscuro dinámico donde los arcabuceros avanzan en plena acción.', 'El cuadro en realidad transcurre a plena luz del día; fue llamado ''Ronda de noche'' en el siglo XIX porque el barniz oxidado y el hollín habían oscurecido la tela.', 'Siglo XVII d.C.', 'Palette', 'medio'),
  ('ar-meninas-velazquez', 'arte', 'Diego Velázquez pinta ''Las Meninas'' en el Alcázar', 1656, 'Cúspide de la pintura barroca universal que juega con la perspectiva, la realidad y la ilusión reflejando a los reyes Felipe IV y Mariana en un espejo al fondo.', 'La cruz roja de la Orden de Santiago en el pecho del propio Velázquez fue añadida tres años después, según la leyenda por la propia mano del rey tras ser ordenado caballero.', 'Siglo XVII d.C.', 'Palette', 'medio'),
  ('ar-paraiso-perdido-milton', 'arte', 'John Milton publica el poema épico ''El paraíso perdido''', 1667, 'Monumento de la poesía barroca en verso blanco que narra la rebelión de Satanás y la caída de Adán y Eva en el Jardín del Edén.', 'Milton estaba completamente ciego cuando lo compuso, dictando los doce libros verso a verso de memoria a sus hijas cada mañana.', 'Siglo XVII d.C.', 'BookOpen', 'medio'),
  ('ar-moliere-avaro', 'arte', 'Molière estrena ''El avaro'' en París', 1668, 'Comedia de caracteres satírica que ridiculiza la codicia obsesiva y desquiciada a través del inolvidable personaje de Harpagón.', 'Años después Molière sufrió una hemorragia en pleno escenario representando ''El enfermo imaginario'' vestido de amarillo, dando origen a la superstición teatral contra el color amarillo.', 'Siglo XVII d.C.', 'Smile', 'medio'),
  ('ar-etica-spinoza', 'arte', 'Publicación póstuma de la ''Ética'' de Baruch Spinoza', 1677, 'Tratado filosófico revolucionario demostrado según el orden geométrico de Euclides que identifica a Dios con la propia Naturaleza (''Deus sive Natura'').', 'Fue excomulgado de la comunidad judía portuguesa a los 23 años y se ganó la vida puliendo lentes ópticas para telescopios rechazando cátedras universitarias para ser libre.', 'Siglo XVII d.C.', 'BookOpen', 'medio'),
  ('ar-viajes-gulliver-swift', 'arte', 'Jonathan Swift publica ''Los viajes de Gulliver''', 1726, 'Feroz sátira política y misantrópica sobre la mezquindad humana a través de viajes a tierras de enanos (Liliput), gigantes (Brobdingnag) y caballos sabios.', 'Tuvo tal éxito instantáneo que se agotó en una semana; Swift se divirtió viendo cómo los políticos que satirizaba compraban el libro sin darse cuenta de la burla.', 'Siglo XVIII d.C.', 'Compass', 'medio'),
  ('ar-enciclopedia-diderot', 'arte', 'Publicación de la ''Encyclopédie'' de Diderot y D''Alembert', 1751, 'El mayor proyecto intelectual de la Ilustración francesa: 28 volúmenes ilustrados dedicados a difundir la razón, las artes y los oficios contra el oscurantismo.', 'Fue prohibida reiteradamente por la censura real y el Papa, pero continuó imprimiéndose clandestinamente gracias a la protección secreta de ministros ilustrados.', 'Siglo XVIII d.C.', 'BookOpen', 'medio'),
  ('ar-candido-voltaire', 'arte', 'Voltaire publica la sátira filosófica ''Cándido''', 1759, 'Novela ágil y mordaz que demuele el optimismo ingenuo de Leibniz frente a catástrofes como el terremoto de Lisboa, concluyendo con el consejo de ''cultivar nuestro jardín''.', 'Se convirtió en un bestseller escandaloso en toda Europa vendiendo miles de ejemplares ilegales en Ginebra y París en pocos días.', 'Siglo XVIII d.C.', 'Smile', 'medio'),
  ('ar-critica-razon-pura-kant', 'arte', 'Immanuel Kant publica la ''Crítica de la razón pura''', 1781, 'Produjo el ''Giro Copernicano'' de la epistemología demostrando cómo el espacio, el tiempo y las categorías moldean activamente la percepción de la realidad.', 'Kant era tan puntual y metódico en su paseo diario por Königsberg que los habitantes de la ciudad sincronizaban sus relojes al verlo pasar.', 'Siglo XVIII d.C.', 'HelpCircle', 'medio'),
  ('ar-fausto-goethe', 'arte', 'Goethe publica la primera parte de ''Fausto''', 1808, 'Obra cumbre de las letras alemanas donde el insatisfecho doctor Fausto pacta con el demonio Mefistófeles su alma a cambio del conocimiento y la plenitud vital.', 'Goethe tardó casi sesenta años en redactar las dos partes de Fausto, sellando el manuscrito definitivo pocas semanas antes de morir en 1832.', 'Siglo XIX d.C.', 'Flame', 'medio'),
  ('ar-tres-mayo-goya', 'arte', 'Francisco de Goya pinta ''Los fusilamientos del 3 de mayo''', 1814, 'Pintura visceral que denunció la brutalidad bélica con el hombre de la camisa blanca con los brazos en cruz frente al pelotón de fusilamiento de Napoleón en Madrid.', 'Rompió con la tradición de pintar la guerra como hazaña gloriosa, inaugurando el expresionismo moderno como grito humanitario contra la barbarie.', 'Siglo XIX d.C.', 'Palette', 'medio'),
  ('ar-frankenstein-mary-shelley', 'arte', 'Mary Shelley publica ''Frankenstein o el moderno Prometeo''', 1818, 'Piedra fundacional de la ciencia ficción moderna nacida durante ''el año sin verano'' en Villa Diodati a orillas del lago de Ginebra junto a Lord Byron.', 'En la novela original el monstruo no es un gigante mudo y torpe como en las películas, sino una criatura elocuente, sensible y lectora de John Milton.', 'Siglo XIX d.C.', 'Zap', 'medio'),
  ('ar-gran-ola-kanagawa', 'arte', 'Katsushika Hokusai estampa ''La gran ola de Kanagawa''', 1831, 'Xilografía ukiyo-e japonesa que muestra una garra monumental de espuma marina a punto de engullir tres barcas de pescadores con el Monte Fuji sereno al fondo.', 'Utilizó por primera vez el pigmento importado ''Azul de Prusia'', desatando la fiebre mundial por el arte nipón (Japonismo) que cautivó a Van Gogh y Monet.', 'Siglo XIX d.C.', 'Palette', 'medio'),
  ('ar-miserables-victor-hugo', 'arte', 'Victor Hugo publica la novela épica ''Los Miserables''', 1862, 'Monumento a la redención humana, la justicia social y las barricadas de París a través de la odisea de un exconvicto regenerado por el amor de una niña huérfana.', 'Tras el lanzamiento Hugo envió a su editor un telegrama que contenía solo el signo: ''¿?''. El editor le respondió con igual genialidad: ''!'' para avisarle del éxito total.', 'Siglo XIX d.C.', 'Heart', 'medio'),
  ('ar-crimen-castigo-dostoievski', 'arte', 'Fiódor Dostoievski publica ''Crimen y Castigo''', 1866, 'Thriller psicológico en San Petersburgo sobre un estudiante que asesina a una anciana usurera creyéndose un hombre extraordinario por encima de la ley.', 'Dostoievski la escribió bajo tremenda presión financiera dictando simultáneamente otra novela a su taquígrafa para pagar urgentes deudas de juego.', 'Siglo XIX d.C.', 'HelpCircle', 'medio'),
  ('ar-guerra-paz-tolstoi', 'arte', 'León Tolstói culmina ''Guerra y Paz''', 1869, 'Catedral literaria de más de 1.200 páginas que entrelaza las vidas íntimas de cinco familias aristocráticas rusas durante la invasión de Napoleón en 1812.', 'Su esposa Sofía Behrs copió a mano el monumental manuscrito completo corregido por Tolstói más de siete veces consecutivas a la luz de las velas.', 'Siglo XIX d.C.', 'BookOpen', 'medio'),
  ('ar-impresion-sol-naciente-monet', 'arte', 'Claude Monet pinta ''Impresión, sol naciente''', 1872, 'Pinceladas sueltas y luminosas de barcas entre la bruma del amanecer que dieron involuntariamente su nombre histórico al movimiento Impresionista.', 'El crítico de arte Louis Leroy acuñó despectivamente el término ''impresionistas'' en un periódico satírico diciendo que un boceto de papel pintado era más acabado.', 'Siglo XIX d.C.', 'Palette', 'medio'),
  ('ar-pensador-rodin', 'arte', 'Auguste Rodin concibe la escultura ''El Pensador''', 1880, 'Bronce de musculatura tensa con la barbilla apoyada en la mano que encarna la meditación filosófica profunda y el esfuerzo intelectual humano.', 'Originalmente medía apenas 70 centímetros e iba colocado en lo alto de ''La Puerta del Infierno'' representando a Dante Alighieri contemplando su obra.', 'Siglo XIX d.C.', 'Palette', 'medio'),
  ('ar-asi-hablo-zaratustra-nietzsche', 'arte', 'Nietzsche publica ''Así habló Zaratustra''', 1883, 'Poema filosófico en prosa que proclama ''la muerte de Dios'', la voluntad de poder, el eterno retorno y la superación del hombre hacia el ''Übermensch''.', 'Nietzsche concibió la idea del eterno retorno mientras caminaba junto a una roca piramidal junto al lago de Silvaplana en los Alpes suizos.', 'Siglo XIX d.C.', 'Sparkles', 'medio'),
  ('ar-girasoles-van-gogh', 'arte', 'Vincent van Gogh pinta ''Los Girasoles'' en Arlés', 1888, 'Explosión de amarillos vibrantes e intensos pintados para decorar la habitación de Paul Gauguin en la célebre ''Casa Amarilla'' en el sur de Francia.', 'Durante toda su vida Van Gogh vendió solo un cuadro reconocido oficialmente (''El viñedo rojo''); un siglo después un cuadro de girasoles se subastó por 40 millones.', 'Siglo XIX d.C.', 'Palette', 'medio'),
  ('ar-grito-munch', 'arte', 'Edvard Munch pinta ''El Grito'' en Oslo', 1893, 'Icono universal de la angustia existencial moderna con un cielo rojo encendido y una figura andrógina tapándose los oídos ante el grito desgarrador de la naturaleza.', 'El cielo rojo sangre que inspiró la pintura se debió probablemente a las partículas volcánicas suspendidas tras la cataclísmica erupción del Krakatoa.', 'Siglo XIX d.C.', 'Palette', 'medio'),
  ('ar-senoritas-avignon-picasso', 'arte', 'Picasso pinta ''Las señoritas de Aviñón'' y nace el Cubismo', 1907, 'Rompió radicalmente con quinientos años de perspectiva renacentista fragmentando los cuerpos en planos geométricos influenciados por máscaras africanas.', 'Cuando su amigo el pintor Henri Matisse vio la tela en el taller de Bateau-Lavoir en Montmartre pensó inicialmente que Picasso se había vuelto loco.', 'Siglo XX d.C.', 'Palette', 'medio'),
  ('ar-metamorfosis-kafka', 'arte', 'Franz Kafka publica ''La Metamorfosis''', 1915, 'El comerciante Gregorio Samsa despierta una mañana transformado en un monstruoso insecto, parábola cumbre de la alienación y el absurdo contemporáneo.', 'Kafka dio instrucciones expresas por carta a su editor de que en la portada del libro jamás se dibujara al insecto de forma explícita.', 'Siglo XX d.C.', 'Bug', 'medio'),
  ('ar-ulises-james-joyce', 'arte', 'James Joyce publica ''Ulises'' en París', 1922, 'Relata las andanzas cotidianas de Leopold Bloom por las calles de Dublín durante un solo día (el 16 de junio de 1904) mediante el flujo de conciencia.', 'Fue prohibida por obscenidad en Gran Bretaña y Estados Unidos durante más de una década; cada 16 de junio se celebra el ''Bloomsday'' en todo el planeta.', 'Siglo XX d.C.', 'BookOpen', 'medio'),
  ('ar-gran-gatsby-fitzgerald', 'arte', 'F. Scott Fitzgerald publica ''El Gran Gatsby''', 1925, 'Retrato deslumbrante y melancólico de la Era del Jazz, la opulencia de Long Island y el desencanto del sueño americano personificado en la luz verde del muelle.', 'En vida de Fitzgerald vendió menos de 20.000 copias; durante la Segunda Guerra Mundial el ejército estadounidense repartió 150.000 ejemplares gratis a soldados consagrándola.', 'Siglo XX d.C.', 'Heart', 'medio'),
  ('ar-guernica-picasso', 'arte', 'Pablo Picasso pinta el monumental lienzo ''Guernica''', 1937, 'Mural monumental en blanco y negro para el pabellón de la República Española en París, inmortalizando el dolor civil tras el bombardeo de la Legión Cóndor.', 'Cuando un oficial nazi vio una fotografía del cuadro en el taller de Picasso y preguntó: ''¿Hizo usted esto?'', el pintor respondió tajante: ''No, lo hicieron ustedes''.', 'Siglo XX d.C.', 'Palette', 'medio'),
  ('ar-principito-saint-exupery', 'arte', 'Antoine de Saint-Exupéry publica ''El Principito''', 1943, 'Poética fábula ilustrada por el propio autor sobre un aviador varado en el desierto que conoce a un niño venido del asteroide B-612.', 'Nos legó una de las frases más queridas de la literatura universal: ''Sólo con el corazón se puede ver bien; lo esencial es invisible para los ojos''.', 'Siglo XX d.C.', 'Heart', 'medio'),
  ('ar-1984-george-orwell', 'arte', 'George Orwell publica la novela distópica ''1984''', 1949, 'Profecía literaria contra el totalitarismo que introdujo conceptos imperecederos en la cultura humana como el Gran Hermano, la Policía del Pensamiento y la Neolengua.', 'Orwell escribió la novela mientras padecía tuberculosis avanzada en una solitaria granja de la brumosa isla escocesa de Jura.', 'Siglo XX d.C.', 'Eye', 'medio'),
  ('ar-cien-anos-soledad-marquez', 'arte', 'García Márquez publica ''Cien años de soledad''', 1967, 'Obra cumbre del Realismo Mágico que fundó el pueblo mítico de Macondo a través de siete generaciones marcadas por mariposas amarillas, soledad y guerras.', 'Gabo empeñó la batidora y el secador de pelo de su esposa Mercedes Barcha en Ciudad de México para poder pagar los estampillas de correo y enviar el manuscrito a Buenos Aires.', 'Siglo XX d.C.', 'Sparkles', 'medio'),
  ('dp-juegos-olimpicos-antiguos', 'deportes', 'Primeros Juegos Olímpicos de la Antigüedad en Olimpia', -776, 'Celebrados en honor al dios Zeus en el santuario de Olimpia; Coroebo ganó la carrera del ''stadion'' convirtiéndose en el primer campeón olímpico registrado.', 'Durante la celebración se proclamaba la tregua sagrada (''ékécheiria''): todas las guerras entre polis griegas debían suspenderse de forma obligatoria.', 'Siglo VIII a.C.', 'Flame', 'medio'),
  ('dp-milon-crotona', 'deportes', 'Milón de Crotona y su sexto laurel olímpico en lucha', -510, 'El atleta más legendario de la antigüedad grecorromana conquistó seis coronas olímpicas de lucha consecutivas entrenando levantando un ternero diario hasta que creció a buey.', 'Se decía que era capaz de sujetar una granada fresca en la palma de su mano sin aplastarla y nadie lograba doblarle un solo dedo.', 'Siglo VI a.C.', 'Dumbbell', 'medio'),
  ('dp-filipides-maraton', 'deportes', 'La hazaña de Filípides corriendo desde Maratón a Atenas', -490, 'Tras la victoria sobre los persas en la bahía de Maratón, corrió sin descanso 42 kilómetros para anunciar la victoria gritando ''¡Nenikékamen!'' antes de expirar.', 'Su histórica gesta inspiró la prueba reina del atletismo moderno incorporada en los primeros Juegos Olímpicos contemporáneos en 1896.', 'Siglo V a.C.', 'Footprints', 'medio'),
  ('dp-carrera-cuadrigas-roma', 'deportes', 'Carreras de cuadrigas en el Circo Máximo de Roma', 100, 'El mayor espectáculo deportivo de masas del mundo antiguo albergaba a 250.000 espectadores divididos en facciones de colores (Rojos, Blancos, Azules y Verdes).', 'El auriga hispano Diocles ganó más de 35 millones de sestercios en su carrera deportiva, siendo considerado el deportista mejor pagado de todos los tiempos ajustado por inflación.', 'Siglo I d.C.', 'Trophy', 'medio')
INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('dp-juegos-atenas-1896', 'deportes', 'Inauguración de los Primeros Juegos Olímpicos Modernos', 1896, 'El renacimiento del olimpismo en el reconstruido Estadio Panathinaikó de mármol blanco de Atenas con 241 atletas masculinos de 14 naciones.', 'El pastor de agua griego Spyridon Louis ganó la primera maratón moderna parando a mitad del camino en una posada para beber una copa de vino que le ofreció su tío.', 'Siglo XIX d.C.', 'Flame', 'medio'),
  ('dp-tour-francia-1903', 'deportes', 'Primera edición del Tour de Francia en bicicleta', 1903, 'Sesenta ciclistas pedalearon sobre caminos de tierra de noche y día en seis etapas titánicas de más de 400 km con bicicletas de piñón fijo sin cambios de marcha.', 'Maurice Garin ganó la prueba con casi tres horas de ventaja sobre el segundo clasificado recibiendo una ovación multitudinaria en el Parque de los Príncipes en París.', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('dp-maraton-dorando-pietri', 'deportes', 'La dramática maratón olímpica de Dorando Pietri en Londres', 1908, 'El fondista italiano entró al estadio White City completamente deshidratado y desorientado, cayendo cinco veces antes de que los jueces lo ayudaran a cruzar la meta.', 'Fue descalificado por recibir ayuda externa, pero la reina Alejandra de Inglaterra le entregó personalmente una copa dorada idéntica por su conmovedor coraje.', 'Siglo XX d.C.', 'Heart', 'medio'),
  ('dp-jim-thorpe-estocolmo', 'deportes', 'Jim Thorpe deslumbra en los Juegos Olímpicos de Estocolmo', 1912, 'El atleta indígena nativo-americano arrasó en pentatlón y decatlón con zapatos desparejados rescatados de la basura la misma mañana de la competencia.', 'El rey Gustavo V de Suecia le estrechó la mano al entregarle el trofeo diciéndole con admiración: ''Señor, usted es el mejor atleta del mundo''.', 'Siglo XX d.C.', 'Award', 'medio'),
  ('dp-juegos-invierno-chamonix-1924', 'deportes', 'Primeros Juegos Olímpicos de Invierno en Chamonix', 1924, 'Celebrados a los pies del imponente Mont Blanc en los Alpes franceses con pruebas de patinaje de velocidad, esquí de fondo, salto y curling sobre nieve y hielo natural.', 'La esquiadora de patinaje artística noruega Sonja Henie compitió en Chamonix con apenas once años de edad terminando última, antes de ganar tres oros consecutivos.', 'Siglo XX d.C.', 'Snowflake', 'medio'),
  ('dp-babe-ruth-bambino', 'deportes', 'Babe Ruth conecta 60 cuadrangulares en una sola temporada', 1927, 'El legendario bateador de los New York Yankees pulverizó los registros del béisbol profesional en la mítica alineación conocida como ''Murderers'' Row''.', 'Ruth conectó más cuadrangulares en solitario en esa temporada que cualquiera de los otros equipos completos de la Liga Americana.', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('dp-primer-mundial-uruguay-1930', 'deportes', 'Uruguay conquista la Primera Copa Mundial de Fútbol', 1930, 'Los anfitriones celestes derrotaron 4-2 a Argentina en la gran final inaugural de Montevideo alzando el trofeo Jules Rimet ante 93.000 apasionados hinchas.', 'El delantero uruguayo Héctor Castro anotó el gol decisivo jugando sin su antebrazo derecho, que había perdido en un accidente de carpintería en su juventud.', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('dp-jesse-owens-berlin-1936', 'deportes', 'Jesse Owens gana cuatro oros olímpicos en Berlín', 1936, 'El velocista afroamericano pulverizó la propaganda de la supremacía aria en el Estadio Olímpico de Berlín ganando los 100m, 200m, salto largo y relevos 4x100m.', 'Su rival alemán de salto de longitud, Luz Long, lo aconsejó amistosamente sobre dónde iniciar su carrera de salto para no hacer nulo, forjando una célebre amistad.', 'Siglo XX d.C.', 'Award', 'medio'),
  ('dp-maracanazo-1950', 'deportes', 'El ''Maracanazo'': Uruguay enmudece a 200.000 brasileños', 1950, 'A Brasil le bastaba empatar para ser campeón del mundo en su colosal estadio recién inaugurado, pero Ghiggia anotó el 2-1 sellando una de las mayores hazañas del deporte.', 'Ghiggia resumió la tarde con su célebre frase: ''Sólo tres personas han silenciado el Maracaná con 200.000 personas: Frank Sinatra, el Papa Juan Pablo II y yo''.', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('dp-milla-cuatro-minutos-bannister', 'deportes', 'Roger Bannister derriba la barrera de los 4 minutos en la milla', 1954, 'Médico y atleta aficionado británico que cruzó la milla en 3 minutos y 59,4 segundos derribando una barrera que los fisiólogos de la época consideraban físicamente imposible.', 'Entrenaba durante su hora de almuerzo de 45 minutos mientras realizaba sus prácticas en el hospital St. Mary de Londres.', 'Siglo XX d.C.', 'Timer', 'medio'),
  ('dp-pele-mundial-1958', 'deportes', 'Pelé deslumbra al planeta con 17 años en Suecia 58', 1958, 'El joven prodigio brasileño anotó un hat-trick en semifinales y dos goles memorables de sombrero en la final ante Suecia (5-2), consagrando el ''Joga Bonito''.', 'El rey Gustavo VI Adolfo de Suecia bajó personalmente al césped tras el silbatazo final para estrechar la mano del adolescente bañado en lágrimas de emoción.', 'Siglo XX d.C.', 'Crown', 'medio'),
  ('dp-abebe-bikila-roma-1960', 'deportes', 'Abebe Bikila gana la maratón olímpica de Roma descalzo', 1960, 'Miembro de la guardia imperial etíope que corrió 42 kilómetros por las calles empedradas de Roma descalzo a la luz de las antorchas, batiendo el récord del mundo.', 'Al ser consultado sobre por qué corrió sin zapatillas deportivas, respondió: ''Quería que el mundo supiera que mi país, Etiopía, siempre ha ganado con heroísmo y determinación''.', 'Siglo XX d.C.', 'Footprints', 'medio'),
  ('dp-wilt-chamberlain-100-puntos', 'deportes', 'Wilt Chamberlain anota 100 puntos en un solo partido de la NBA', 1962, 'El pívot de los Philadelphia Warriors encestó 36 tiros de campo y 28 tiros libres ante los New York Knicks, un récord insuperado en el baloncesto profesional.', 'No hubo cámaras de televisión en el estadio; la icónica fotografía de Wilt sosteniendo un pedazo de papel con el número ''100'' escrito a lápiz dio la vuelta al mundo.', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('dp-muhammad-ali-liston', 'deportes', 'Muhammad Ali vence a Sonny Liston y grita ''¡Soy el rey!''', 1964, 'Con 22 años bailó sobre el cuadrilátero flotando como mariposa y picando como abeja obligando al temido campeón Liston a retirarse en su taburete en Miami Beach.', 'Al finalizar saltó a las cuerdas señalando a los periodistas escépticos al grito de: ''¡Tráguense sus palabras! ¡He sacudido el mundo!''.', 'Siglo XX d.C.', 'Award', 'medio'),
  ('dp-black-power-mexico-1968', 'deportes', 'El saludo del ''Black Power'' en el podio de México 68', 1968, 'Smith y Carlos alzaron sus puños enfundados en guantes negros con las cabezas gachas durante el himno de EE.UU. como protesta por los derechos civiles y la discriminación racial.', 'El medallista de plata australiano Peter Norman los apoyó solidariamente portando en su pecho la insignia del Proyecto Olímpico por los Derechos Humanos.', 'Siglo XX d.C.', 'Award', 'medio'),
  ('dp-bob-beamon-salto-siglo', 'deportes', 'El ''Salto del Siglo'' de Bob Beamon en México 68', 1968, 'Voló por los aires en el foso de arena alcanzando los 8,90 metros, pulverizando el récord mundial de salto de longitud por 55 centímetros de una sola vez.', 'El sistema óptico de medición láser no llegaba tan lejos en el foso, por lo que los jueces tuvieron que buscar con urgencia una cinta métrica manual de acero.', 'Siglo XX d.C.', 'Zap', 'medio'),
  ('dp-brasil-mexico-1970', 'deportes', 'El Brasil de Pelé se corona tricampeón mundial en México 70', 1970, 'Golearon 4-1 a Italia en el Estadio Azteca con una exhibición coral de fútbol ofensivo irrepetible, quedándose con la Copa Jules Rimet en propiedad perpetua.', 'El cuarto gol anotado por el capitán Carlos Alberto tras ocho pases consecutivos y una asistencia perfecta de Pelé es considerado el mejor gol colectivo de los mundiales.', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('dp-mark-spitz-munich-1972', 'deportes', 'Mark Spitz conquista siete oros olímpicos en natación', 1972, 'El nadador estadounidense ganó siete medallas de oro estableciendo siete récords mundiales en cada una de las pruebas que disputó luciendo su célebre bigote.', 'Compitió con bigote porque bromeó con los entrenadores rivales diciéndoles que el vello facial desviaba el agua lejos de su boca haciéndolo más hidrodinámico.', 'Siglo XX d.C.', 'Award', 'medio'),
  ('dp-naranja-mecanica-cruyff', 'deportes', 'Nace el ''Fútbol Total'' de la Naranja Mecánica de Cruyff', 1974, 'La selección de los Países Bajos revolucionó las tácticas del fútbol mundial donde cualquier jugador de campo podía defender, presionar y atacar en cualquier posición.', 'En la final ante Alemania Occidental marcaron gol de penalti en el minuto uno tras dieciséis pases seguidos sin que los alemanes hubieran tocado la pelota.', 'Siglo XX d.C.', 'Sparkles', 'medio'),
  ('dp-rumble-in-the-jungle-ali-foreman', 'deportes', '''The Rumble in the Jungle'': Muhammad Ali noquea a Foreman', 1974, 'Ali ideó la táctica del ''rope-a-dope'' apoyándose en las cuerdas flojas para absorber los demoledores golpes de Foreman hasta agotarlo y noquearlo en el octavo asalto.', 'Sesenta mil espectadores en el estadio cantaban al unísono en lengua lingala: ''¡Ali boma ye!'' (¡Ali, mátalo!).', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('dp-nadia-comaneci-diez-perfecto', 'deportes', 'Nadia Comăneci y el primer ''10 perfecto'' de la gimnasia', 1976, 'La gimnasta rumana ejecutó una rutina impecable en las barras asimétricas en Montreal deslumbrando al jurado que le otorgó la máxima puntuación de la historia.', 'El marcador electrónico del recinto mostró ''1.00'' porque los fabricantes del tablero creían que era humanamente imposible obtener un 10.00 y no tenían espacio para cuatro dígitos.', 'Siglo XX d.C.', 'Award', 'medio'),
  ('dp-milagro-sobre-hielo-1980', 'deportes', 'El ''Milagro sobre el hielo'' de los universitarios de EE.UU.', 1980, 'Un equipo de estudiantes universitarios aficionados estadounidenses derrotó 4-3 a la todopoderosa máquina profesional de la Unión Soviética cuatro veces campeona olímpica.', 'El narrador de televisión Al Michaels exclamó en los últimos segundos la frase más famosa del periodismo deportivo estadounidense: ''¿Creen ustedes en los milagros? ¡SÍ!''.', 'Siglo XX d.C.', 'Snowflake', 'medio'),
  ('dp-maradona-gol-del-siglo', 'deportes', 'Maradona anota la ''Mano de Dios'' y el ''Gol del Siglo''', 1986, 'En cuartos de final de México 86 ante Inglaterra anotó primero con el puño pícaro y cuatro minutos después eludió a cinco jugadores ingleses partiendo de mitad de cancha.', 'El relato radial de Víctor Hugo Morales (''¡Barrilete cósmico, ¿de qué planeta viniste?!'') quedó grabado para siempre en la memoria colectiva del fútbol mundial.', 'Siglo XX d.C.', 'Crown', 'medio'),
  ('dp-carl-lewis-seul-1988', 'deportes', 'Carl Lewis revalida los 100m en Seúl tras el dopaje de Ben Johnson', 1988, 'La carrera de 100 metros más polémica y veloz del siglo; Johnson cruzó primero pero fue descalificado por esteroides coronando el oro olímpico para Carl Lewis.', 'Lewis acumuló en su carrera nueve medallas de oro olímpicas en cuatro ediciones consecutivas igualando el mito de Jesse Owens.', 'Siglo XX d.C.', 'Zap', 'medio'),
  ('dp-ayrton-senna-monaco', 'deportes', 'Ayrton Senna y la vuelta de clasificación mágica en Mónaco', 1988, 'Batió a su compañero Alain Prost por casi segundo y medio en las calles del Principado describiendo haber conducido en un estado de trance casi místico fuera del cuerpo.', 'Senna declaró: ''De repente me asusté porque me di cuenta de que estaba más allá de mi comprensión consciente... frené lentamente y volví a boxes''.', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('dp-dream-team-barcelona-1992', 'deportes', 'El mítico ''Dream Team'' de EE.UU. deslumbra en Barcelona 92', 1992, 'La primera vez que jugadores profesionales de la NBA compitieron en unos Juegos Olímpicos, ganando todos sus encuentros por un promedio aplastante de 44 puntos.', 'El entrenador Chuck Daly no pidió ni un solo tiempo muerto en todo el torneo olímpico para detener el juego de su constelación de estrellas.', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('dp-michael-jordan-first-three-peat', 'deportes', 'Michael Jordan y los Bulls completan su primer tricampeonato', 1993, 'Derrotaron a los Phoenix Suns de Charles Barkley en las Finales con Jordan promediando 41 puntos por partido, hazaña inédita en las finales modernas de la NBA.', 'Poco después anunció su primer retiro del baloncesto profesional para cumplir el sueño de su difunto padre de jugar béisbol profesional.', 'Siglo XX d.C.', 'Crown', 'medio'),
  ('dp-haka-mundial-rugby-1995', 'deportes', 'Sudáfrica campeona de Rugby y el abrazo de Nelson Mandela', 1995, 'Los Springboks derrotaron a los All Blacks neozelandeses; el presidente Mandela vistió la camiseta verde del equipo uniendo a un país fracturado por el apartheid.', 'Cuando el periodista preguntó a Pienaar qué sintió teniendo a 63.000 aficionados apoyándolos, respondió: ''No teníamos 63.000 sudafricanos; teníamos a 43 millones''.', 'Siglo XX d.C.', 'Heart', 'medio'),
  ('dp-chilavert-goles-arquero', 'deportes', 'José Luis Chilavert y el gol de arquero desde mitad de cancha', 1996, 'El portero paraguayo pateó un tiro libre directo desde detrás del círculo central sorprendiendo adelantado al arquero Germán Burgos de River Plate.', 'Es el único guardameta en la historia del fútbol profesional en haber anotado un hat-trick de tres goles en un solo partido oficial.', 'Siglo XX d.C.', 'Zap', 'medio'),
  ('dp-tiger-woods-masters-1997', 'deportes', 'Tiger Woods gana el Masters de Augusta por 12 golpes de ventaja', 1997, 'Se convirtió en el campeón más joven y el primer golfista de ascendencia afroamericana y asiática en ganar la Chaqueta Verde con un récord histórico de 18 bajo par.', 'La sintonía televisiva del torneo superó a cualquier evento deportivo previo impulsando una transformación global del golf profesional.', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('dp-francia-mundial-1998', 'deportes', 'Zidane lidera a Francia hacia su primera Copa del Mundo', 1998, 'Anotó dos cabezazos inapelables en el primer tiempo de la final goleando 3-0 al campeón defensor Brasil ante más de un millón de personas festejando en los Campos Elíseos.', 'La imagen de Zidane fue proyectada con letras gigantes sobre el Arco del Triunfo de París con el lema: ''Merci Zizou''.', 'Siglo XX d.C.', 'Trophy', 'medio'),
  ('dp-the-last-shot-jordan', 'deportes', '''The Last Shot'' de Michael Jordan para su sexto anillo de la NBA', 1998, 'Robó el balón a Karl Malone y anotó el tiro de media distancia a falta de 5,2 segundos coronando el segundo tricampeonato y su sexto trofeo de campeón.', 'Mantuvo la muñeca suspendida en el aire contemplando cómo el balón entraba limpio en la canasta en la que fue su última jugada oficial con la camiseta de Chicago Bulls.', 'Siglo XX d.C.', 'Crown', 'medio'),
  ('dp-cathy-freeman-sidney-2000', 'deportes', 'Cathy Freeman enciende el pebetero y gana el oro en Sídney 2000', 2000, 'Atleta aborigen australiana que encendió el pebetero olímpico y soportó la descomunal presión de 112.000 compatriotas para ganar la final de 400 metros lisos.', 'Dio la vuelta de honor portando entrelazadas sobre sus hombros tanto la bandera de Australia como la bandera del pueblo aborigen australiano.', 'Siglo XXI d.C.', 'Flame', 'medio'),
  ('dp-ronaldo-fenomeno-korea-japon', 'deportes', 'Ronaldo el ''Fenómeno'' corona a Brasil pentacampeón en 2002', 2002, 'Tras superar dos devastadoras roturas de tendón rotuliano, fue bota de oro con 8 goles y anotó los dos tantos de la final ante Alemania.', 'Se cortó el cabello con un peculiar flequillo triangular antes de la semifinal para que la prensa hablara de su peinado en lugar del estado de sus rodillas.', 'Siglo XXI d.C.', 'Trophy', 'medio'),
  ('dp-grecia-eurocopa-2004', 'deportes', 'Grecia sorprende al continente conquistando la Eurocopa 2004', 2004, 'La mayor sorpresa en la historia del fútbol de selecciones: con férrea disciplina táctica derrotaron dos veces a la anfitriona Portugal de Cristiano Ronaldo y Figo.', 'Las casas de apuestas británicas pagaban 100 a 1 por el título griego antes del inicio del torneo en tierras lusas.', 'Siglo XXI d.C.', 'Shield', 'medio'),
  ('dp-roger-federer-wimbledon-record', 'deportes', 'La era dorada de Roger Federer en el césped de Wimbledon', 2006, 'El tenista suizo desplegó un tenis de elegancia insuperable con su revés a una mano alcanzando cuatro coronas consecutivas en el All England Club londinense.', 'Encadenó un récord absoluto de 23 semifinales consecutivas en torneos de Grand Slam a lo largo de más de seis temporadas sin desfallecer.', 'Siglo XXI d.C.', 'Crown', 'medio'),
  ('dp-zidane-cabezazo-materazzi', 'deportes', 'El cabezazo de Zidane e Italia campeona del mundo en Berlín', 2006, 'Dramático desenlace en la prórroga de la final donde Zidane fue expulsado con tarjeta roja directa tras cabecear a Materazzi en su último partido profesional.', 'Zidane pasó junto a la dorada Copa del Mundo cabizbajo rumbo al túnel de vestuarios en una de las fotografías deportivas más icónicas del siglo XXI.', 'Siglo XXI d.C.', 'Trophy', 'medio'),
  ('dp-michael-phelps-beijing-ocho-oros', 'deportes', 'Michael Phelps conquista ocho medallas de oro en Beijing 2008', 2008, 'El nadador de Baltimore batió el legendario récord de Mark Spitz al ganar ocho oros en una misma edición de los Juegos Olímpicos con siete récords mundiales.', 'En la final de 100 metros mariposa venció al serbio Milorad Čavić por una sola centésima de segundo (0,01s) con una última brazada desesperada en la pared.', 'Siglo XXI d.C.', 'Award', 'medio'),
  ('dp-usain-bolt-100-metros-record', 'deportes', 'Usain Bolt pulveriza el récord de los 100m lisos en Berlín', 2009, 'El velocista jamaiquino detuvo el cronómetro en unos inhumanos 9,58 segundos en la pista azul del Estadio Olímpico de Berlín a una velocidad punta de 44,7 km/h.', 'Completó los 100 metros dando solo 41 zancadas de más de 2,4 metros cada una, mientras sus competidores necesitaban 45 zancadas para la misma distancia.', 'Siglo XXI d.C.', 'Zap', 'medio'),
  ('dp-espana-mundial-sudafrica-2010', 'deportes', 'El gol de Iniesta en el minuto 116 y España campeona del mundo', 2010, 'En la prórroga ante los Países Bajos y tras la milagrosa parada de Casillas con el pie a Robben, Iniesta empalmó una volea inolvidable al fondo de la red.', 'Iniesta se quitó la camiseta en el festejo mostrando una dedicatoria estampada en su pecho: ''Dani Jarque, siempre con nosotros'' para su amigo fallecido.', 'Siglo XXI d.C.', 'Trophy', 'medio'),
  ('dp-partido-mas-largo-tenis', 'deportes', 'Isner y Mahut juegan el partido más largo de la historia', 2010, 'Duelo épico que duró 11 horas y 5 minutos a lo largo de tres días consecutivos, culminando con un quinto set de 70-68 a favor de Isner.', 'El marcador electrónico de la Pista 18 se averió y congeló en dos ocasiones porque los programadores jamás previeron un marcador superior a 47 juegos.', 'Siglo XXI d.C.', 'Timer', 'medio'),
  ('dp-messi-91-goles-anuales', 'deportes', 'Lionel Messi establece el récord histórico de 91 goles en un año', 2012, 'Superó el récord de 85 goles que ostentaba el alemán Gerd Müller desde 1972, promediando más de 1,3 goles por partido a lo largo de 69 cotejos.', 'Marcó 79 goles con la camiseta del FC Barcelona y 12 goles con la albiceleste de Argentina durante doce meses consecutivos de magia pura.', 'Siglo XXI d.C.', 'Crown', 'medio'),
  ('dp-alemania-brasil-siete-uno', 'deportes', 'El ''Mineirazo'': Alemania golea 7-1 a Brasil en Belo Horizonte', 2014, 'La mayor humillación futbolística sufrida por el pentacampeón en su propio suelo en semifinales mundialistas encajando cuatro goles en seis minutos.', 'Miroslav Klose anotó su 16° gol en copas del mundo durante el partido desbancando a Ronaldo como el máximo goleador histórico de los mundiales.', 'Siglo XXI d.C.', 'Zap', 'medio'),
  ('dp-chile-bicampeon-america', 'deportes', 'Chile se consagra bicampeón de América en penales ante Argentina', 2016, 'Tras ganar la Copa América 2015 en Santiago, ''La Roja'' repitió la gloria en Nueva Jersey en la Copa América Centenario derrotando a la Argentina de Messi.', 'Claudio Bravo realizó en el tiempo suplementario una legendaria atajada con la yema de los dedos a un cabezazo angulado de Sergio Agüero.', 'Siglo XXI d.C.', 'Trophy', 'medio'),
  ('dp-leicester-city-campeon', 'deportes', 'El milagro del Leicester City campeón de la Premier League', 2016, 'Un humilde club con presupuesto modesto que se salvó del descenso la temporada previa conquistó la liga de fútbol más competitiva del planeta.', 'Las casas de apuestas pagaban 5000 a 1 por su consagración antes de arrancar la liga, la cuota ganadora más improbable de la historia del deporte.', 'Siglo XXI d.C.', 'Trophy', 'medio'),
  ('dp-cavaliers-remontada-finales', 'deportes', 'LeBron James y los Cavaliers remontan un 1-3 en las Finales de la NBA', 2016, 'Primer equipo en la historia de la NBA en revertir un déficit de 1-3 en las finales derrotando al equipo del récord de 73 victorias en su propia cancha en el 7° partido.', 'El memorable tapón en contraataque de LeBron James sobre Andre Iguodala (''The Block'') en los minutos finales quedó grabado en los anales del baloncesto.', 'Siglo XXI d.C.', 'Crown', 'medio'),
  ('dp-patriots-remontada-super-bowl-51', 'deportes', 'Tom Brady y los Patriots remontan un 3-28 en el Super Bowl LI', 2017, 'Perdían por 25 puntos en el tercer cuarto antes de orquestar la mayor remontada en la historia del fútbol americano ganando en tiempo extra con James White.', 'Brady conquistó en esa noche mágica su quinto anillo de campeón del Super Bowl siendo nombrado MVP indiscutido.', 'Siglo XXI d.C.', 'Trophy', 'medio'),
  ('dp-barcelona-remontada-psg', 'deportes', 'La histórica remontada 6-1 del FC Barcelona ante el PSG', 2017, 'Tras caer 4-0 en París en Champions League, anotaron tres goles en los últimos siete minutos de descuento con Sergi Roberto desatando el delirio en el minuto 95.', 'Los sismógrafos del Instituto de Ciencias de la Tierra de Barcelona registraron un auténtico microsismo provocado por el salto de 96.000 hinchas con el sexto gol.', 'Siglo XXI d.C.', 'Flame', 'medio'),
  ('dp-serena-williams-23-grand-slam', 'deportes', 'Serena Williams gana el Abierto de Australia embarazada', 2017, 'Derrotó a su hermana Venus en la final conquistando su 23° título de Grand Slam en la era abierta sin ceder un solo set mientras cursaba ocho semanas de gestación.', 'Superó la marca de Steffi Graf como la jugadora más laureada de la era moderna del tenis mundial.', 'Siglo XXI d.C.', 'Award', 'medio'),
  ('dp-real-madrid-tres-champions-seguidas', 'deportes', 'Real Madrid conquista su tercera Champions League consecutiva', 2018, 'Vencieron 3-1 al Liverpool con una inolvidable chilena aérea de Gareth Bale, logrando un tricampeonato moderno consecutivo sin precedentes en el fútbol europeo.', 'Zinedine Zidane se convirtió en el único entrenador en la historia en ganar tres Copas de Europa de forma consecutiva.', 'Siglo XXI d.C.', 'Crown', 'medio')
INSERT INTO public.timeline_events (id, categoria, nombre, anio, descripcion, pista, siglo, icono, dificultad)
VALUES
  ('dp-kipchoge-maraton-sub-dos-horas', 'deportes', 'Eliud Kipchoge corre el maratón en menos de 2 horas (1:59:40)', 2019, 'El atleta keniata completó los 42,195 km con una formación en cuña de liebres y zapatillas especiales rompiendo la mítica barrera de las dos horas.', 'Al cruzar la meta se golpeó el pecho proclamando al mundo su célebre lema inspiracional: ''No Human Is Limited'' (Ningún ser humano tiene límites).', 'Siglo XXI d.C.', 'Timer', 'medio'),
  ('dp-rafael-nadal-catorce-roland-garros', 'deportes', 'Rafael Nadal conquista su 14° título de Roland Garros', 2022, 'Con 36 años y jugando con infiltraciones anestésicas en su pie izquierdo alzó su decimocuarta Copa de los Mosqueteros en París con un balance de 112 victorias y 3 derrotas.', 'La Federación Francesa de Tenis erigió una estatua de acero inoxidable de Nadal en la entrada del recinto parisino en vida del propio jugador.', 'Siglo XXI d.C.', 'Trophy', 'medio'),
  ('dp-messi-campeon-mundo-qatar', 'deportes', 'Lionel Messi y Argentina conquistan la Copa del Mundo en Qatar', 2022, 'La final más dramática y emocionante de todos los tiempos: 3-3 tras la prórroga ante Francia con triplete de Mbappé y atajada histórica del ''Dibu'' en el minuto 123.', 'Messi vistió la tradicional túnica real árabe ''bisht'' antes de levantar el trofeo que coronó su gloriosa trayectoria deportiva como campeón absoluto.', 'Siglo XXI d.C.', 'Crown', 'medio'),
  ('dp-manchester-city-triplete', 'deportes', 'El Manchester City de Pep Guardiola conquista el ansiado Triplete', 2023, 'Conquistaron la Premier League, la FA Cup y la Champions League con un golazo de Rodri, consagrando la supremacía táctica del técnico catalán.', 'Pep Guardiola se convirtió en el primer entrenador de fútbol de la historia en conquistar dos Tripletes continentales con dos clubes distintos (Barcelona y City).', 'Siglo XXI d.C.', 'Trophy', 'medio'),
  ('dp-simone-biles-gimnasia-paris', 'deportes', 'Simone Biles agranda su leyenda en los Juegos de París 2024', 2024, 'Tras superar problemas de salud mental en Tokio, regresó con saltos acrobáticos de extrema dificultad que llevan su nombre cosechando tres oros olímpicos.', 'Llegó a once medallas olímpicas y treinta medallas mundiales portando un collar de cabra con diamantes en alusión a su título de G.O.A.T. (La mejor de todos los tiempos).', 'Siglo XXI d.C.', 'Award', 'medio'),
  ('dp-armand-duplantis-record-garrocha', 'deportes', 'Armand Duplantis bate el récord mundial de garrocha en París (6,25m)', 2024, 'El saltador con pértiga sueco superó el listón en 6,25 metros en su tercer y último intento en el Stade de France ante 80.000 espectadores delirando.', 'Tras caer en la colchoneta corrió por la pista e imitó la postura de tiro del tirador olímpico turco Yusuf Dikeç en un festejo que se volvió viral en todo el planeta.', 'Siglo XXI d.C.', 'Zap', 'medio'),
  ('dp-cristiano-ronaldo-900-goles', 'deportes', 'Cristiano Ronaldo alcanza la marca histórica de 900 goles oficiales', 2024, 'El delantero portugués anotó ante Croacia en la Liga de Naciones de la UEFA convirtiéndose en el primer jugador en la historia documentada en llegar a 900 goles.', 'Rompió a llorar de rodillas junto al banderín de córner celebrando la longevidad de su disciplina física a sus casi 40 años de edad.', 'Siglo XXI d.C.', 'Flame', 'medio'),
  ('dp-novak-djokovic-golden-slam', 'deportes', 'Novak Djokovic conquista el oro olímpico y completa el Golden Slam', 2024, 'A sus 37 años y con el menisco operado semanas antes, derrotó a Carlos Alcaraz en dos tie-breaks magistrales conquistando el único trofeo que le faltaba en su vitrina.', 'Rompió en llanto tembloroso en medio de la arcilla roja de la Philippe-Chatrier y subió a la tribuna para fundirse en un abrazo con su hija Tara con la bandera serbia.', 'Siglo XXI d.C.', 'Trophy', 'medio')
